/* 令和8年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r08.committeeSessions.push(...[{"id":"r08-20260511-5","meetingId":"r08-m0405","date":"2026年5月11日","dateIso":"2026-05-11","committee":"総務委員会","time":"午後 １時００分～午後 ２時３６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"多言語通訳の三者間通話サービス等の導入","agenda":"多言語通訳の三者間通話サービス等の導入","exchanges":[{"speaker":"西本委員","kind":"確認","question":"確認をしたいと思います。往々にして行政用語がいろいろあると思うのです。それを伝えるときに、ある程度、知識がないと伝えづらいだろうと思うのですけれども、その辺の訓練なのか、研修なのか、それ相応の知識を持っている方のオペレーターなのか、そのところを教えてください。そういったときには、やはり携帯電話やスマホ等々からの問合せという形になるのか、そこをもう少し教えてください。","respondent":"與那嶺デジタル推進課長","answer":"なので、これまで実際に行政との通訳のやり取りをずっと続けている方が対応しますので、そういった意味での知識レベルは問題ないのかなと考えているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"そこにかければ、使っているスマホから直接話ができるという形になると思うのですけれども、やはりそうではない端末からとなると、ホームページ等々でお知らせはあるのだろうと思うのですけれども、そこまでイメージがないので、これは要望になるのですけれども、分かりやすいように書き直してくださいとかと、訳した言葉が出てくるのかどうか分からないのですけれども、端末だったら、すぐ何語というふうに。","respondent":"與那嶺デジタル推進課長","answer":"こういった通訳サービスの利用に関しては、電話がかかってきたときに、実際にしゃべっている言語が異なるケース、当然、押し間違いなども出てくるかと思いますが、逆にオペレーター側からすると、大体この人はこういうことをしゃべっているなというところが。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"最後に、電話がつながらないというケースはどのぐらい増えているのでしょうか。実際、窓口でやられていると思うのですけれども、多分これ、通話がもっと気楽になるから増えるとくると思うのです。大体どのぐらいを想定しているのか、そのボリューム的なところを教えてください。","respondent":"與那嶺デジタル推進課長","answer":"現状、電話はないのですけれども、まだ２割程度の時間の余裕があるというところでありますので、電話の時間も入れましょうというような形でございまして、実際にサービスを入れている近隣の自治体などに聞き取った中では、電話サービスを入れたところで、すぐに。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"通訳者が全部その内容を一緒に聞いているわけですから、その辺の対応とか、先ほども申し上げましたけれども、やはり専門用語、専門的な内容になると、専門の人が通訳者になっているわけではないので、自治体としては様々な業務を遂行している中で、きちんとそれに応えられるような対応ができるようになるのでしょうか、その辺について見解をお聞かせください。","respondent":"與那嶺デジタル推進課長","answer":"それまでに培ってきた知見、事業者の間で変わってはいるのですけれども、そういった通訳サービスを用いて手続をサポートする知見は積み上がっておりますし、その中で、先ほどご指摘のありましたプライバシーの問題であるとか。","voiceIndex":11,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"こういう方法でこれからやっていくというのは、これから大体中心になって動いていくと思うので、その場で区民も外国の方も分かりやすい、そこの場できちんと返事をできる、対応できるということはいいと思うので、ただ、今お話ししたとおり、個人情報とか、あと専門用語、やはり言語、言葉の技術的な対応も大事だと思うので、その辺をしっかり今まで積み上げてきたノウハウを活かしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"澤田委員","kind":"質問","question":"在住外国人向け情報のＬＩＮＥを、品川区のほうで配信されていると思うのですけれども、在住外国人の方はどれくらい登録されているのかということをお伺いしたいのですけれども。内容が少し違いますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"澤田委員","kind":"質問","question":"どれくらい把握されているか分からないのですけれども、これも活用されるのかなというところでご予定されているのでしょうか。例えば、今回の多言語の電話のサービスをやりますとかということは、こちらも活用されるご予定なのですか。","respondent":"與那嶺デジタル推進課長","answer":"品川区の在住外国人向けのサービスについては、登録者数は、所管外なので分からないところもあるのですけれども、もちろん周知に当たっては、こちらも情報発信の１つですので、活用して、住んでいる多くの方に知っていただくことが非常に大事だと思っていますので。","voiceIndex":16,"id":"exchange-007"},{"speaker":"澤田委員","kind":"意見","question":"すみません、数を聞いてしまって申し訳なかったのですけれども、そうしましたら、こちらを使っていただけるということでよかったなということと、すごくいいので、このＬＩＮＥに登録してくださる在住外国人の人が増えるといいなと思っていますので、今後ともどうぞよろしくお願いします。","respondent":"中西総務課長","answer":"在住外国人のＬＩＮＥの登録者数です。令和７年度で、英語版が８９５名の方が登録されている状況です。","voiceIndex":18,"id":"exchange-008"},{"speaker":"澤田委員","kind":"質問","question":"割合としては何割ぐらいというか、全体としてどれぐらいなのでしょうか。","respondent":"中西総務課長","answer":"割合は、すみません、今、正式な在住外国人の人数については、手元に資料がございませんが、１万８,０００人程度の方がいますので、そういった意味では、その中での約９００名という形になりますので、その程度の割合になります。","voiceIndex":20,"id":"exchange-009"},{"speaker":"澤田委員","kind":"質問・要望","question":"とてもいいシステムだと思うので、たくさんの方に登録していただけるようにしていただけたらいいなと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-010"},{"speaker":"山本委員","kind":"確認","question":"私からも質問します。今回、ビデオ通話に加えて電話での対応ができるということで、タブレットとかが窓口になくても、スマホを持っている外国人の方がいらしたら、ほぼ全ての窓口で対応ができるということだと思うので、１３言語の方々はということだと思うのですけれども、そういう理解で間違いないのか、幅広い全ての窓口に来て対応ができるということで間違いないのかということで、確認させてください。","respondent":"與那嶺デジタル推進課長","answer":"最初の説明でも少し触れたのですけれども、通訳タブレットを配置しておる窓口部署を中心に、大体、７３か所配置をしているのですけれども、区の組織の中には様々な部署がありまして、どの部署につなぐかということに関しても、今回は電話をつなぐところの間に入るものですので。","voiceIndex":23,"id":"exchange-011"},{"speaker":"山本委員","kind":"質問","question":"この１３言語を使う外国人の方が窓口にいらっしゃったときに、それを案内できるかというところになるのかなと思いまして、もちろん転入のときに聞いて知っているというケースもあると思うのですけれども、もともと住んでいる方が、実際に来ているかどうかはともかく、よく「窓口に行っても、なかなか伝わらないんだよね」みたいことを思っていたりする。","respondent":"與那嶺デジタル推進課長","answer":"そうですね、こういったサービス自体は、まず、後ろ側に区の職員がいるというところが前提ですので、これは通訳に関わらずなのですけれども、質問に対して分かりやすい説明をするというところがまず前提にあろうかと考えています。","voiceIndex":25,"id":"exchange-012"},{"speaker":"山本委員","kind":"意見","question":"このサービス導入で、これがしっかりと利用されることによって外国人の皆様にとってもすごくいい窓口になっていくと思いますので、期待しております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、皆さんからも、多くの方に使ってもらえるようにということであったのですけれども、私もそう思っていますが、先ほども、通訳、これまでやってきている中で、時間の余裕も若干あるということでしたけれども、やはりさらに使いやすくなってくるというところで、混雑の予測は、そんなに考えなくても大丈夫なのでしょうか。さらに通訳者を広げていくとか、そういうところは今のところはないのでしょうか。","respondent":"與那嶺デジタル推進課長","answer":"確かにサービスは増えますので、その中でつながりにくくなったであるとか、そういった形においては、基本的にはオペレーターがいるコールセンターがありますので、そこの中での人員の登用を要望するであるとか、そういったところがあろうかと思いますので、まず運用を進めながら。","voiceIndex":28,"id":"exchange-014"}]},{"id":"topic-02","title":"連携自治体との新たな取組み","agenda":"連携自治体との新たな取組み","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"幾つかもう既に申込みが終わっているということがありました。ただ、例えば、連携自治体とのワーケーション促進事業でいうと、ホームページで４月１５日から５月１５日という形で掲載されています。それと、これらも結構申込みが多かったということなのですが、どこに周知をして、どこから来ているアクセスというか、参加申込みが来ているのかという、それはいかがですか。そこをお尋ねします。","respondent":"野口官民共創担当課長","answer":"アクセス数に関しては、こちらは検証していないので分からない部分はあるのですけれども、Ｘであったり、区のホームページ、あとは、例えば、五反田バレーと連携させていただいて、五反田バレーの加入企業へのＰＲをさせていただいたりというところで多角的に実施していますので。","voiceIndex":34,"id":"exchange-015"},{"speaker":"西本委員","kind":"提案","question":"ＳＮＳを使ったりとかしていくということなのですけれども、もちろん直接的なＰＲ、いろいろな団体に行ったりとか、いろいろな団体のところでのお願いは、それはそれで１つの方法としていいと思いますが、やはり広くお伝えしていただきたいと思います。それともう１つ、ワーケーション促進事業、これ、よく分からないのです。どういう形式になるのですか。","respondent":"野口官民共創担当課長","answer":"そこをすり合わせるために、今回、スケジュールの６月の部分で書かせていただいております、我々品川区も一緒に入らせていただいて、三者でお話しさせていただいた中で、実は企業としては、こういうことを思って、このワーケーションプログラムを見て申請をしたものの。","voiceIndex":36,"id":"exchange-016"},{"speaker":"西本委員","kind":"提案","question":"何をするか分からないのです。だけど、こういう特徴があって、こういうことができそうですよということを自治体から提案してもらっているものがこのシートという形になっていて、それはマッチングみたいなものですよね。企業で、それだったら、こういうことを提案できるのだけれどもとかという、それから内容を詰めていくという感覚でよろしいでしょうか。その確認だけ。","respondent":"野口官民共創担当課長","answer":"シートには、そこまで具体的に書いているわけではないのですけれども、各自治体の持っている魅力のある部分といいますか、そういうところをまず出していただいて、そこに関心ある企業に手を挙げていただくというイメージでつくっておりますので。","voiceIndex":38,"id":"exchange-017"},{"speaker":"西本委員","kind":"意見","question":"なので、多分これから決定をして、すり合わせという時期に入ってくると思うのですけれども、その中で、区民の人たちにとってメリット、参加自治体のメリット、それがリンクしているのかどうかということをぜひ、当然やると思いますけれども、それが意外とずれてしまうと、やったものが、実際にできたものが当初の目的からずれてしまうというようなことが起きてしまうのが少し残念に思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"これは今までも市町村交流事業を品川区でもやっていたのですが、それに加えて、今回、参加事業者は、販路拡大や就業者の健康増進に取り組んでいくということなのですか。少し教えてください。","respondent":"野口官民共創担当課長","answer":"今、委員がおっしゃられている地域産業振興課でやっているような事業の部分も、一応、メリットとしては書かせていただいているのですけれども、あくまでも総務課が今回これを実施するというところで、人と人との交流がメインになりますので、企業側としては。","voiceIndex":41,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"やはり連携ということを考えて、今、この品川区、２３区は特にそうですけれども、これだけ多くの人を抱えているような自治体が多数あるわけですから、そういう方面にも、もっと力を入れたほうが、連携事業とすれば、私はもっといいものができるのではないかと思うのですが、これとは少し意味合いが違うのでしょうか。それだけ教えてください。","respondent":"野口官民共創担当課長","answer":"今回連携させていただいておるような、ある一定程度、距離が離れた自治体と連携することで、平時からの連携をするという、有事になった際に、いかにどうスムーズに有事の対応をするかという部分ももちろんあるかと思います。","voiceIndex":43,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、少し調べた範囲だと、飯田市なども、やはり交通事情を考えると、結構遠方で、やはり鉄道を使うなり、車で交通網を利用するなりしても、かなり大変なというか、そこへ行き着くまで相当の時間と難所を抱えるのではないかと少し思ったので、近くで、品川区としても、それぞれ防災課のほうで取り組んでいると思いますけれども、そういう方向にもこれからつながっていくと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-021"},{"speaker":"塚本副委員長","kind":"確認","question":"最初に、ワーケーションなのですけれども、ワーケーションは最近出てきた概念で、これ、企業からすると、福利厚生とは明確に違う位置づけのもの、職務、業務というふうに位置づけられるものかどうかが、少しその辺がよく分からないので、要するに、企業側としては、ワーケーションという枠組みの中で、地方に社員が仕事をしに行くという状況、健康増進とかということは。","respondent":"野口官民共創担当課長","answer":"地方都市と品川区の対立構造というわけではなくて、協力関係を築いていくのだといったところを考えてみて、品川区も地方に還元するところは還元しますし、逆に、各都市から連携することによって。","voiceIndex":46,"id":"exchange-022"},{"speaker":"塚本副委員長","kind":"意見","question":"ただ一方で、ワーケーションということでいくと、そういう行った先の自治体との話合いで、いろいろ連携先の自治体としては、販路拡大というか、地域活性化につながるというメリットがあって、ウエルカムで来てほしいとなると思いますけれども、行く人の社員のモチベーションとかそういうことでいくと、行く側としては、別にワーケーションの休暇、バカンスという意識の中で。","respondent":"野口官民共創担当課長","answer":"職というところから、その自治体を楽しんでもらう、知ってもらう、楽しむという言い方はあれですね、魅力を知ってもらうという意味もあるかと思いますので、ワーケーション、バカンスという意味合いも少々あるかもしれませんけれども。","voiceIndex":48,"id":"exchange-023"},{"speaker":"塚本副委員長","kind":"質問","question":"分かりました。では、ぜひよろしくお願いします。というのは、もっと言うと、これ、拡大したいみたいな話になると、飯田市のお話になるので、なかなか品川区だけの決定ではできないので、そういう意味では、補正とかで拡充できる可能性があるのかどうかというところを視野に入れた答弁をお願いします。","respondent":"野口官民共創担当課長","answer":"今後に関しては、これから検討していきたいというところで聞いていまして、我々品川区としても、今、塚本副委員長からもお褒めをいただいたように、拡充できないかというところは、ご相談、協議させていただいて、いろいろお話をさせていただいて。","voiceIndex":50,"id":"exchange-024"},{"speaker":"山本委員","kind":"提案","question":"体験交流ツアーです、これも拡大していくというところで、区民のこういった機会を増やしていくというのは、予算との調整の中ですごくいいことだと思っているのですけれども、この拡充した新たなツアー、これはどういう経緯で広がっていったのかなというところで、区の職員の皆さんが考えてアプローチしていったのか、相手側から、連携自治体からの提案とかをうまくもらってやったのかという。","respondent":"野口官民共創担当課長","answer":"交流ツアーの拡充の経緯ですけれども、我々もいろいろな自治体と連携している中で、各自治体といろいろコミュニケーションをとらせていただいたところ、どちらかというと前向きな自治体というのですか、やる気がある自治体と、今までにないようなメニューであったり。","voiceIndex":52,"id":"exchange-025"},{"speaker":"山本委員","kind":"提案","question":"小田原市などは、小田原市から積極的にいろいろな企画をつくったりして区へのご提案があったという話も少し聞いておりますので、何かそういう連携都市、連携自治体の方々の提案や予算などをうまく活用させていただきながら、こういう自治体連携を広げていくということを意識して進めていただきたいなです。もし今の点、何かコメントがあればおっしゃっていただければと思います。","respondent":"野口官民共創担当課長","answer":"おっしゃられるような地図にプロットして、ここの自治体はどこというようなことだと、私は今、理解しました。マンパワーという部分もありますので、できるところから実施していきたいと思いますので、引き続きよろしくお願いいたします。","voiceIndex":54,"id":"exchange-026"},{"speaker":"澤田委員","kind":"意見","question":"今いろいろなことを聞いてきた中で１つ思ったのが、今回、各自治体との体験交流ツアーを行う中で、向こうから来て、こちらから、品川区の皆さんが関係自治体のほうに行かれていろいろな体験をしてというところで交流していくと思うのですけれども、商店街にいらしたりとか、そういう交流もありますけれども、向こうの住民の方に来ていただいてとかということを今後考えていらっしゃるのかなと。","respondent":"野口官民共創担当課長","answer":"そうですね、今後については、体験交流ツアー等を使って、各自治体間の住民同士が交流をしていくと。その上で、今後のステップとして、今おっしゃられたところも、委員からいただきましたので、今後、検討していきたいと考えています。","voiceIndex":56,"id":"exchange-027"}]},{"id":"topic-03","title":"区ホームページ全面リニューアル","agenda":"区ホームページ全面リニューアル","exchanges":[{"speaker":"西本委員","kind":"質問","question":"だから、「前、ここにあったよな」という情報がなかなか探せない状況があるので、そこをもう少し分かりやすいように、情報のリンク、全て最新情報とか、それから、注意してくださいよという緊急性の高い情報が時間がたつことによってなくなってしまうという、どこにあるか分からなくなってしまうということも、とても不便さを感じているので、そこの情報の伝達の仕方を分かりやすくなるのかどうか。","respondent":"田口戦略広報課長","answer":"もう１点、２点目の最新情報を探しやすくですとか、緊急性の高い情報がいつの間にか消えてしまっているようなところがあるというようなご指摘ですが、こちらは、品川区からのお知らせというところに、あくまでも新しい情報が出たら消されていくというのではなく。","voiceIndex":65,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"なので、これは誰がやるのですか。各部署がそこにアクセスするような形になって自由に入れられるという形になっていくのですか。検索機能を大分変えているか、変えるのだろうなと思うのですけれども、もっと住民の方々がどういうアクセスの仕方をしているのかということを、多分、分析されていると思うのですけれども、だからこういうふうにするのですよということがあれば、教えてください。","respondent":"田口戦略広報課長","answer":"職員の研修も９月に実施を予定しておりますので、そのような際に、新しいイベントについては、ここのチェックボックスを入れて、しっかりと更新をするようにというようなところで教育をしていくという中で、今までは活用されていなかったかもしれないのですけれども、新サイト。","voiceIndex":67,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"意識的にしてほしい。これから研修もしていくということなのですけれども、自分たちのやっていることをどんどん宣伝してほしいのです。それで、いろいろな自治体のホームページのリニューアルも含めて検討しているということなのですが、今、いいなと、活用されているなというところが、もしも事例的にあったら、それを教えてほしいということと、予算額を見ると、業務委託で、約４,０００万円ですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"書いてあるのは分かります。なので、これ、どこかに頼むのですよね。業者に頼む。それはもう決まっているのですか。これは入札とかではなくて随意契約とか、そういう形になって決められているのか、それだけ教えてください。","respondent":"田口戦略広報課長","answer":"もう１点、事業者が決まっているかという件ですが、こちらは、昨年度にプロポーザルを実施しまして、事業者から提案を受けまして、そちらのほうで審議した結果、現在のフューチャーイン株式会社という会社に決まっているという状況です。","voiceIndex":71,"id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当に情報の閲覧というのは、これからますます増えていくし、ＡＩも使って導入していくわけですから、より複雑化されると思いますので、ミスをしないようにと言っても無理だと思うので、できるだけ情報を共有できるような、事業部が本当はつくればいいのでしょうけれども、またそこに専門的なものが知識を持っていないとなかなか更新もできないと思うので対応は難しいと思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-032"},{"speaker":"山本委員","kind":"質問・要望","question":"全面リニューアル以降は、この基準に則った表示の仕方で変わっていくということだと思うのですけれども、それは９月の職員研修でやられるということだったのですけれども、各所管が基本的には情報をアップデートというか、掲載していくということだと思うのですが、その人たちに、しっかりとそれがこの研修で行き届くものなのかという、その研修の内容と、結構大変な作業だと思うのですけれども。","respondent":"田口戦略広報課長","answer":"それ以外のページにつきましては、ＵＸライティングというような考え方、職員研修などでも実施いたしますし、あとは、マニュアルも全庁に配布いたしまして、ＵＸライティングという考え方、今年度だけではなくて、来年度。","voiceIndex":74,"id":"exchange-033"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。関連団体のサイトについては、そのようにしていただければと思いますし、しっかりと検索で新しいものが引っかかるように進めていただきたいということで要望いたします。ＵＸライティングのところ、アクセス件数が多いものから順番にということで、１００件というところで、まずは進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7405#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":32535,"voices":81}},{"id":"r08-20260512-21","meetingId":"r08-m0405","date":"2026年5月12日","dateIso":"2026-05-12","committee":"子ども若者支援・共生社会推進特別委員会","time":"午後 １時００分～午後 １時０４分","status":"正式会議録","sourceType":"formal","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7407#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=21&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":2022,"voices":12}},{"id":"r08-20260512-20","meetingId":"r08-m0405","date":"2026年5月12日","dateIso":"2026-05-12","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午後 １時００分～午後 １時０６分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"あくつ委員","kind":"意見","question":"ここで、もう文言も入れていただければありがたい。もうこの中に含まれてはいて、(5)のとおりなのですが、前回も私はこの課題は非常に問題だと思っているところで、中立性の確保を図るとともにの後に、議会への説明を尽くすなど当該事業化プロセスの透明性の担保に万全を期すこと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"意見","question":"事前説明としたほうがいいのか。まあ、いいです。あえて、そのタイミングがあったにもかかわらず、当委員会にも報告がなかったのは、私はかなり問題だと思っていますし、書いていただいているとおり、中立性の確保は非常に大事ですけれども、やはりそれは議会への報告がなかったことが非常に大きな問題なので、もっと分かりやすくするために、その文言を入れていただければありがたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7409#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":2521,"voices":16}},{"id":"r08-20260513-22","meetingId":"r08-m0405","date":"2026年5月13日","dateIso":"2026-05-13","committee":"まちづくり・公共交通推進特別委員会","time":"午後 １時００分～午後 １時０７分","status":"正式会議録","sourceType":"formal","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"石田（秀）副委員長","kind":"意見","question":"皆さん、お疲れさまでした。１年間、委員長を支え、しっかりと皆さんと一緒に議論ができるよう、努めてまいりました。我々も、行政側と本当にいい、いろいろなやり取りができたのかな。本当に、一番のショックだったのは、バスの運転士が５０人ぐらい定年でもう退職すると。しかしながら、募集をかけても５人しか入らない。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7411#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=22&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":2422,"voices":9}},{"id":"r08-20260514-10","meetingId":"r08-m0405","date":"2026年5月14日","dateIso":"2026-05-14","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"会派変更届","agenda":"会派変更届","exchanges":[{"speaker":"せお委員","kind":"質問・要望","question":"私は広報会議のリーダーをやらせていただいていて、区議会だよりの中で態度を示す場所があるのですけれども、そういったところでも様々工夫してやってきたところでありまして、やはり一番は、区民が混乱するのではないかと感じているところですし、新しく入った方も、今までは未来と態度が違うのかなと感じているところなのですけれども、そういったところで、やはり議会運営が混乱したりすると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-001"},{"speaker":"松永委員","kind":"意見","question":"新たに西本たか子議員を迎え入れて、これからもやっていきたいと思っています。態度表明も含めまして、しっかりと対話をさせていただきながら、情報共有させていただきながら、円滑な議会運営について、幹事長として努めていきたいと考えていますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"確認","question":"今日、質問するつもりはなかったのですけれども、せお委員からもあったので、伺いたいのですけれども、まず、未来は会派とはどういうものだとお考えですかというところを確認しておきたいのです。会派とは、一言でどういうものかをお伺いしたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"「同じ意見や考え方を持った」とは、先ほど松永委員からもご発言があったとおり、お話は様々な意見も出た上で、これはどの会派もそうだと思うのですけれども、最後は一つの結論に収れんして、そこで採決なり、会派の態度だと思うのですけれども、私たちもこの３年間から、今年度に入って４年目ですか、構成は変わっていますけれども、ずっと拝見していて、今まで数えると４０件以上、意見が一致していない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"私からも質問させていただきたいのですけれども、せお委員から、議案への態度が会派内で違うことがあったと指摘がありましてご質問があって、先ほど松永委員から、しっかりとした態度表明をしながらということはあったのですけれども、つまるところ、議案への態度が会派内で変わったりを認めるというのが未来の会派としての方針なのかどうか、そこを確認させてもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-005"},{"speaker":"松永委員","kind":"意見","question":"私たちの会派は、無所属と、あと様々な政党が集まっている会派です。それは一人一人、個人個人の意見があるのは当たり前だと思っていまして、それを一つにするために、話合いの中で今後も決めていく。では、何を終着点にするかは、議論を深めながら必ず一つに絞っていくです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"会派というからには、よく議論して結論を出すことが、まず大事だと思うのですけれども、そこはうちの会派ももちろんやっているところなのですが、やはり出された結論については、それについて態度表明がばらばらになりますと、区民の目線からすると、非常に分かりづらいというか、それはともすれば不誠実にもなりかねないということで、会派としては、やはりよく話し合って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"確認","question":"いろいろお伺いして、会派の話が相当出たので、一つだけ。これから様々、委員会のことだ何だと出てくると思いますけれども、第一会派であるならば、それはやはり与党でいいのですよね。野党なのですか。是々非々なのですか。第一会派を名のって、与党でやっていこうというお話は何度も聞いたけれども、確認のためにお伺いしたい。今日の議運でも。それをどう考えていらっしゃるのかを一つだけお聞きしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"それは先ほども答弁されていたから、それは私も聞いているので。だけれども、現実、そうではないことを、反対討論も含めて、自分の思いのとおりやっていくという方もいらっしゃって、それがきちんと、そうではないですよと、会派なのだから。だけど私としては、これから新幹事長になられる方としては、やっていくつもりですと言うのは、やれないということも含めて言っているという理解でいいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"意見","question":"「やっていきます」と、「やれます」、「やります」といったって、現実問題それが違ったらどうしますかみたいになってしまうわけで、それをここでやる気はないけれども、必ずそういうことも踏まえて、人数選択、何をしていくかは、第一会派としてしっかりやってもらわないと、それはいつまでたったって第一会派と認められないよと。現時点では我々はそう思うとだけは伝えておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-010"}]},{"id":"topic-02","title":"常任・議運・特別委員会の構成","agenda":"常任・議運・特別委員会の構成","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"申合せ確認事項の、会派に所属する議員の中から比例配分方式により委員を選出するという規定に基づいて、今回の案も出されていると思うのですけれども、そうなのか確認をさせていただきたいと思います。皆さん、あるいは正副のご意見なども伺えればと思います。","respondent":"まつざわ委員長","answer":"比例配分につきましては、そのとおり比例配分でやらせていただいております。そしてまた、全会派を入れるとのお話もありましたが、今ここで私が答えるというよりも、そういったことも含めて、ご意見として頂戴しながらも議論は深めていけばいいのかなと思っています。","voiceIndex":42,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"どこかで現行のルールを、変更の是非も含めて、議論していきたいとの話だったのですけれども、ぜひそういうのを議題にしていただきたいというか、議論のテーブルには乗せていただきたいと思うのですけれども、今後どのような場所で議論されていくのか、委員長にご意見を伺えればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"単純に比較すると、共産党が一つ枠が減ってしまっているのですが、子ども若者共生が１名入っていたのが、今回ないということですけれども、できればこちらにまた委員を配置させていただければと思うのですけれども、こういった案になった理由ですとか、あるいは共産党が改めて子ども若者共生特別委員会にも委員を配置したいという要望については、どのようにお考えでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"確認","question":"一応、念のために確認させてください。長期のお休みを取られている議員がいらっしゃると思いますけれども、それは全然、ここでお名前は出しませんけれども、先ほどの委員長のお話の中で、各会派から話を聞いて、それはしっかりできるのだということで、その上でこの配分になっているとのことでしたけれども、これは本当にそういうことでいいのかどうか確認させてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-014"},{"speaker":"まつざわ委員長","kind":"確認","question":"そのお話もさせていただきました。私もあくつ委員と同じ感覚を持っていまして、大丈夫なのかと、来れないのに名前だけあるのが、やはり私としても、欠席が果たしていいのかという疑問がありました上で、未来に確認しましたところ、しっかりできますと、参加することができますとしっかりとお答えをいただいたので、それを信じて、今回このような案としてご提出させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-015"},{"speaker":"あくつ委員","kind":"確認","question":"分かりました。委員長の言葉は信じますけれども、では今の委員長のご発言で、未来としては間違いないと一応、確認を取らせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"それに伴って、それがどう配分されるかも大変重要な問題だと思いますけれども、現状は選挙で行われておりまして、今回もそう決まったら、私たちももちろん従うわけなのですけれども、現状において、やはりより民主的で合意できる配分のやり方を求めるべきだと思っていまして、これはやはり比例配分を基本にして考えることかなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"今のお話ですと、比例配分みたいな考えをベースにして、最終的には選挙になっているわけですけれども、行われていくような、これまでもそうだったしと、委員長はそういう認識なのは分かりましたけれども、これからも基本的にはそういう考えもベースにしながら、現行のやり方で決めていくと捉えたのですけれども、そういった理解で間違いないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問・要望","question":"このたび、議会運営委員会の委員長に当たりまして、議会運営等いろいろと検討させていただいた結果、このたび辞退をさせていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7413#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":14472,"voices":99}},{"id":"r08-20260521-10","meetingId":"r08-m0405","date":"2026年5月21日","dateIso":"2026-05-21","committee":"議会運営委員会","time":"午後 １時００分～午後 １時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7415#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":1664,"voices":15}},{"id":"r08-20260526-10","meetingId":"r08-1r","date":"2026年5月26日","dateIso":"2026-05-26","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議事日程（１）、追加議事日程および追加議事日程（２）","agenda":"議事日程（１）、追加議事日程および追加議事日程（２）","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません、これでいいのですけれども、誤解を与えるとあれなので、追加議事日程の第１で、第５７号議案、専決処分の承認を求めることについて、総務委員会付託と書いてあるのですが、総務委員会は時間短縮のためにもすぐやるということですよね。それを言っておいてもらわないと、総合審査まで、本会議が終わって待っている感じになってしまうから。ここで一応、言っておいてもらったほうがありがたい。","respondent":"大澤区議会事務局長","answer":"休憩後、すぐに総務委員会を開きまして、ほかの常任委員会の予算の審査が終わった後に、もう一回総務委員会です。そういう順番でよろしくお願いいたします。","voiceIndex":10,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"賛成いたしますが、監査委員の選出方法について意見を述べさせていただきたいのですが、今回、２名の議員選出監査委員のうち、選任同意は１名だけで、第１会派になったしながわ未来からは選任されず、第２会派となった自民党はそのまま残りました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-002"}]},{"id":"topic-02","title":"議員研修会","agenda":"議員研修会","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"政務活動費の研修ということで、いろいろな角度があると思うのです。どのような趣旨というか、あと、要望が出たということなのですけれども、どういった要望だったのかを含めてお聞かせください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"申し訳ないですけれども、私も今いろいろな広報物を見ていて、大丈夫なのかなというものが結構あります。うちの会派も当然チェックはしていますけれども。一応補足で、そのとき要望させていただいた１人として補足をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7417#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":8835,"voices":47}},{"id":"r08-20260527-6","meetingId":"r08-1r","date":"2026年5月27日","dateIso":"2026-05-27","committee":"区民委員会","time":"午前１０時１０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５６号議案、令和８年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第５６号議案、令和８年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"こちらのほうは２５万世帯、１人世帯も含めて一律に１か月１,０００円、４か月で４,０００円の支給とのことですけれども、まずそこの中で１人世帯と複数人の世帯の中でもどうしても電気代の差が、必ずしも比例するかどうかということはあるかもしれないですが、下がることは当然ないわけですので、そうなるとやはり１人世帯と複数人の世帯との格差というのでしょうか。その辺りをどのように捉えているのか。","respondent":"今井しながわ生活応援担当課長","answer":"一律４,０００円給付とさせていただいた理由ですけれども、ご指摘のとおり世帯人数に応じて電気・ガスの料金に差が生じてくることは、区としても認識しています。","voiceIndex":6,"id":"exchange-001"},{"speaker":"こしば委員","kind":"質問・要望","question":"その一方で、先ほど冒頭でも話をさせてもらったのですけれども、やはり低所得世帯の方の中では電気代、光熱費が家計の支出の割合を占めるパーセンテージが大きいと出ているので、この辺りの考え方、高所得世帯の方も４,０００円、低所得世帯の方も４,０００円ということですので、その辺りをどのように検討されていたのか教えていただきたいと思います。","respondent":"今井しながわ生活応援担当課長","answer":"前段のご説明と重複してしまう部分がありますが、今回の事業につきましては国際情勢の不安定化によります燃料価格の高騰ですとか、６月頃から気温が上がってまいりまして。","voiceIndex":8,"id":"exchange-002"},{"speaker":"こしば委員","kind":"質問・要望","question":"夏の猛暑が予想されている中で、確かにホルムズ海峡の封鎖における燃料費の調整で電気代が高騰する、その影響もあります。当然に猛暑ですので、エアコンを使われると電気の使用量も３割か４割くらい増してくる。当然そうなると電気代も上がってくるのですけれども、それも一応日本での料金設定であるのかどうかを教えていただきたいです。","respondent":"今井しながわ生活応援担当課長","answer":"その場合、６％の上昇分は１か月当たり約１,０００円という金額になりますので、こちらに６月から９月までの暑い期間の４か月分を掛けまして、４,０００円という金額を算出させていただいてあります。","voiceIndex":10,"id":"exchange-003"},{"speaker":"こしば委員","kind":"質問・要望","question":"その１つは、セブン銀行をお使いになるということでして、セブン銀行で即日受け取ることも可能ということですけれども、高齢者に限った話ではないかもしれませんが、スマホの操作、またはＡＴＭの操作が不慣れな区民の方もいらっしゃると思います。これは、当然所轄の警察との連携も必要になってくると思いますけれども、今の時点でどのように検討されているのか教えていただきたいと思います。","respondent":"今井しながわ生活応援担当課長","answer":"いわゆる詐欺防止の対策につきましては、区内の４警察署および消費者センターと連携いたしまして、また、生活安全担当の青色防犯パトロール車による車両広報などにより、広く丁寧に実施することが前提としています。","voiceIndex":12,"id":"exchange-004"},{"speaker":"こしば委員","kind":"質問・要望","question":"店舗によっては、入り口の近くにあるところや結構奥まったところにあるところもありますので、その辺の周知をぜひ。店舗との関係性もあるかもしれませんけれども、ぜひ防犯にもつながる対策を進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問","question":"確かに燃料価格の高騰で電気代、ガス代が区民の生活に直撃するという面では、こういった素早い対応はとてもいいかと考えています。どういった申請方法になるのでしょうか。","respondent":"今井しながわ生活応援担当課長","answer":"現在、事業者とスキームの詳細な詰めを行っているところなので、今回はスキームの概要という形でご説明させていただければと思います。申請手段としては、委員会資料に記載させていただいているとおり、電子申請と紙の申請の２パターンがあります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"おぎの委員","kind":"確認","question":"紙のほうがあるということで、不慣れな方は紙申請ということは確認いたしました。デジタル申請ですけれども、区長の記者会見でＬＩＮＥというワードが出ておりましたが、ＬＩＮＥを携帯電話で使うということでよろしいでしょうか。","respondent":"今井しながわ生活応援担当課長","answer":"２５日の区長定例記者会見の資料に基づくご質問かと思いますけれども、電子申請の場合は区の公式ＬＩＮＥを用いた申請をしていただく形で、今現在スキームを組んでいるところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"おぎの委員","kind":"確認","question":"そのＬＩＮＥの使用は今回単会のみなのか、以前、防災の安否確認にＬＩＮＥを活用してといったお話も出てきたと思うのですけれども、そういったように今回の事業が今後品川区とつながるインフラというか、そういったものになる予定なのか、それとも今回は単純に配布のみの単会使用なのか。その辺はいかがでしょうか。","respondent":"今井しながわ生活応援担当課長","answer":"今回は、そこに給付事業の申請サービスを上乗せして、サービスを追加していく形になります。なので、今後も同様にＬＩＮＥを用いた電子申請サービス等を実施する際には、同様のスキームで継続して使っていくことができる可能性はあります。","voiceIndex":19,"id":"exchange-008"},{"speaker":"おぎの委員","kind":"質問","question":"ほかにも聞きたい方がいらっしゃると思いますので、最後に１点だけ。受け取りですけれども、セブン銀行ＡＴＭということはイトーヨーカドー等でも機械があれば受け取れるという認識で間違いないでしょうか。","respondent":"今井しながわ生活応援担当課長","answer":"お見込みのとおりでございまして、基本的にはセブン‐イレブン全店舗に設置されているものと、提携先のスーパーマーケットですとかそういったところにも設置されていますので、そういったところでも下ろしてしていただくことは可能です。","voiceIndex":21,"id":"exchange-009"},{"speaker":"こんの委員","kind":"質問・要望","question":"何点かお聞きしたいと思います。区民の皆さんから聞かれたときにお答えしたいと思うので、電気・ガス、こうした光熱費の補助は、国でもやっていますのでそれは初ではないだろうし、何が初なのかを教えていただきたいのが１点。２点目は、事業の概要のところです。今回は申請主義。なぜ今回は申請主義にされたのかという点。何点かあるのですが、まずはこの２点をお願いいたします。","respondent":"今井しながわ生活応援担当課長","answer":"プッシュ型で行わせていただいたものとの比較といたしまして、前提としてですけれども、うれしなカードについては国の地方創生臨時交付金を受けての事業になりまして、１２月に臨時交付金が可決された際の事務連絡として自治体向けに。","voiceIndex":24,"id":"exchange-010"},{"speaker":"こんの委員","kind":"質問・要望","question":"それぞれ、ありがとうあります。その辺のところを教えていただきたいのが１点。それから、申請のときに、給付要件の中に申請者の本人確認とありますけれども、いわゆる４か月分の光熱費の領収書といったところで、その契約をしている世帯主の本人確認なのか。いわゆるこの本人確認はどういう人を指して、何を申請するのか。その辺の細かいことはどのように考えているのか確認させてください。","respondent":"今井しながわ生活応援担当課長","answer":"そのほかですけれども、お話がありましたとおり広報紙ですとかコールセンター等で丁寧に対応を行っていくことはもちろんですが、町会、自治会ですとか、民生委員協議会の皆様への情報提供ですとか、申請へのご協力の依頼ですとか。","voiceIndex":26,"id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"サポートのことについては、地域センターでサポートを展開しているものを、既存のものを活用してやるという理解でよいのかの確認と、いわゆる申請のサポートは持っていらっしゃるスマホを職員の方が借りてやることはできないと思うのですが、目の前でそこをタップしてくださいと教えてあげるサポートをイメージしているのですけれども、そういうものでいいのでしょうか。それから、本人確認は分かりました。","respondent":"今井しながわ生活応援担当課長","answer":"地域センターでのサポート体制ですけれども、お見込みのとおり対面で操作方法等についてご支援することを前提に、どの程度の体制が組めるのかは今後調整させていただいてという形になります。世帯主を対象とさせていただいた考え方についても、お見込みのとおりです。","voiceIndex":28,"id":"exchange-012"},{"speaker":"こんの委員","kind":"質問・要望","question":"申請期限ですけれども、今お聞きしていて１０月３１日は短くないですかという気がしました。申請書類も一斉に８月下旬になのか、ばらばらというか少しタイムラグがあったりするのですか。１０月３１日までの２か月は少し短いかと思うのですが、その２か月の根拠なども確認させていただきたいです。できれば、年内いっぱいくらい申請できるような猶予ができたらと考えるわけですけれども、いかがでしょうか。","respondent":"今井しながわ生活応援担当課長","answer":"なので、例えば９月１日に申請を開始いたしまして、すぐに申請書を出していただいて、１２月頃ですと３か月くらい振込までにお時間を頂戴してしまうことになります。","voiceIndex":30,"id":"exchange-013"},{"speaker":"こんの委員","kind":"確認","question":"期限に関しては分かりました。あるいは、一人暮らしの方が多いかと想像すると、重複の確認作業は必要ですけれども１２月よりもっと早くならないのですかというところです。お知らせの中に、紙申請の場合は１２月頃に給付ですとか、そういうものが入るのですか。お知らせするのでしょうか。","respondent":"今井しながわ生活応援担当課長","answer":"紙申請の振込のタイミングにつきましては、所管としても努力いたしまして、１日でも早く振込ができるように今後努力してまいりたいと考えております。","voiceIndex":32,"id":"exchange-014"},{"speaker":"せらく委員","kind":"質問","question":"私からも、しながわ電気・ガス料金緊急支援事業について質問させていだきます。これまでもたくさん出ていたのでかぶらないようにですけれども、この目的として国際情勢の不安定化だったり熱中症リスクへの問題意識は必要だと考えますので、区民の不安への迅速な対応という点で理解しております。この制度趣旨をどのように区民へ周知していくのか伺います。","respondent":"今井しながわ生活応援担当課長","answer":"ご指摘のとおり、現金給付という形になりますので、入ってきたお金をその後どのように使っていただくかは区民の皆様の任意になるものですけれども、委員会資料にもお示しさせていただいたとおり。","voiceIndex":36,"id":"exchange-015"},{"speaker":"せらく委員","kind":"質問・要望","question":"分かりました。次に、申請方法です。先ほども出ていましたが、電子申請と紙申請を併用するということで、今回電子申請はＬＩＮＥから入るので区の電子申請サービスは使用しないのか確認させてください。ＬＩＮＥから入った際のセキュリティ、安全性はどのようになっているかも教えてください。","respondent":"今井しながわ生活応援担当課長","answer":"区としては、ＬＩＮＥに直接ということではないのですけれども、例えば申請書の入力内容につきましてはＬＧＷＡＮ端末、庁内のネットワークに接続される端末で管理させていただいたり情報セキュリティ面を徹底させていただきたいと考えておりますのと。","voiceIndex":38,"id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問","question":"質問が２点あります。先ほど、こしば委員からもご質疑があったと思うのですけれども、ＬＩＮＥ申請のときにコンビニのＡＴＭに行って、一人暮らしのスマホが苦手なお母様に息子なり親族が同伴して行ったとき、やはり怪しまれると思うのです。そこの対応をいま一度。青パトも分かるのだけれども、この対応方法を各警察署とも連携するとおっしゃっていましたが、改めてそこを詳しく聞きたいです。","respondent":"今井しながわ生活応援担当課長","answer":"まさに今回の事業においては、そこの対策が区としても非常に必要な部分だと思っておりまして、先ほど申し上げました区内４警察署との連携という部分で、品川区に生活安全担当課長として警視庁から出向している職員もおりますので。","voiceIndex":41,"id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そういった粗相があったら駄目ですから、ぜひそこはきちんと対応していただきたいと思います。もう１点ですけれども、エネルギー対策のことをお尋ねします。令和７年度もこの助成をやったかと思うのですけれども、令和８年度は４００件を対象としていると思うのですけれども、令和７年度も４００件だったと思うのですが、そこを確認させてください。","respondent":"吉岡地域産業振興課長","answer":"実績のところですけれども、昨年度も４００件の申請を見込んで予算を立てさせていただきました。実績といたしましては、３６３件の申込みということで、今回も４００件分の予算を提案させていただいたところです。","voiceIndex":43,"id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは、全業種ですよね。製造業、飲食、建設があって、医療系もあると思うのですけれども、お分かりになればでいいのですが、３６３件あった中で建設業はどのくらいの数だったのですか。ある程度のパーセンテージでもいいです。","respondent":"吉岡地域産業振興課長","answer":"その後に続きますのが生活関連サービス業、医療業、製造業で、それぞれ７％か６％の間というところでこういった申請がありました。今までの実績を見てみますと、飲食業の方から厨房設備ですとか空調、こういった申請が多かったと認識しています。","voiceIndex":45,"id":"exchange-019"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"周知方法は中小企業支援サイトとかいろいろあると思うのですけれども、特に建設業、一人親方の方は電動工具とかも対象になっているので、ぜひこれは建設組合３団体とかに周知をしていただくのが、やはり分からない方がいらっしゃると思うので、そういった団体にもやられるとは思うのですが、ぜひ建設業のほうにも力を入れていただくというか、投げかけをしていただきたいと思います。これは要望です。","respondent":"吉岡地域産業振興課長","answer":"ご要望ということだったのですが、事業周知としてこういった媒体を活用することもあるのですけれども、やはりこういった補助制度は周知というより割と口コミで広がるという話も聞いておりますので、各団体にどういったら伝わっていくかも含めて。","voiceIndex":47,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7423#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":17741,"voices":59}},{"id":"r08-20260527-7","meetingId":"r08-1r","date":"2026年5月27日","dateIso":"2026-05-27","committee":"厚生委員会","time":"午前１０時１０分～午前１０時４８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５６号議案、令和８年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第５６号議案、令和８年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"それと、この申出というのは、先ほどのご説明の中では受付開始が８月からという話ですけれども、いわゆる知らなかったよ問題といいますか、あれ、いつの間にか終わっていたとなることが一番恐ろしいのですが、申出の締切りというのは今のところどういう形で、本年度とか、何かそういったことは国から示されているのか、また、品川区としてお考えになっていることがあれば教えてください。それが３つ目です。","respondent":"豊嶋生活福祉課長","answer":"様々な手間を考えてのことで国がそのようなルールづくりをしたものと現場では考えてあります。８月から開始予定の廃止の方のお申出の終期、終わりですが、１月か２月の説明会では、複数年度という言い方を国はしておりました。少なくとも本年度、終わるものではございません。","voiceIndex":6,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それは他の自治体にいたとしても、その分も品川区が支給するということなのか確認させていただきたいということと、そうか、追いかけられないのか……。そこのところについてどのような周知をされるのか。","respondent":"豊嶋生活福祉課長","answer":"品川区に他自治体からいらっしゃってなお受給中の方であれば、当然品川区の生活福祉課で、その方が誰でうちのケースワーカーが誰というのは把握しておりますので、品川区に在籍期間中のものは品川区の責任において支給をするのは当然のこととして、転入前にどこにいたか。","voiceIndex":8,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"確認","question":"ありがとうございました。なかなかセンシティブな話もあるのだなということを再認識させていただきました。最後にもう一度だけ確認させてください。これは基本的には２３区もしくは全国で一律同じような運用をするという認識でいいかどうかだけ、最後、確認させてください。","respondent":"豊嶋生活福祉課長","answer":"なので、他自治体がどのようにするかというところまで必ずという言葉を使ってご説明はできないのですけれども、福祉的な立場から、この件に携わるケースワーカーは全て同じような対応をとるものだと認識しておりますので、そのような説明とさせていただければと思います。","voiceIndex":10,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問","question":"保護費の減額処分を取り消して、１０年以上前に遡って大量の当事者に対して多額の保護費の追加給付を行うことになったのは世界的にも初めてではないかと言われていまして、世界的見地からも本当に画期的で歴史的な意義あるものだということで、これはいのちのとりで裁判を中心的に行ってきた弁護士が述べられていることなのですけれども。","respondent":"豊嶋生活福祉課長","answer":"不服審査申立ての人数については、こちらでは承知しておりません。ゼロ人ではなかろうかと考えています。原告はいないと聞いております。","voiceIndex":14,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今、家賃が高くて５万３,７００円ではなかなか住宅が見つからないだったり、物価高騰に保護費が追いついていないなどの現状があると思うのですけれども、私はぜひ区としても改正意見として、改善につながるように出していっていただきたいと思うのですが、その点も１点伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"それは質問していないので大丈夫です。認識しておいてくださいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"意見","question":"転出された方というのは、区外に転出されてしまったというのは、住所を調べるというのも、追って追ってというのはなかなか難しいと思うのですけれども、区内に在住で、就労に伴う収入の増加ということで廃止になった方も令和６年度では１０.８％いるわけですよね。そういう方にも知らせないのかということを……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問","question":"そういうことだということなのですね。よっぽどいろいろと……。それと、ほかの自治体で受けていて品川区に移管された方は、受けていた自治体のほうに請求してくださいという、その期間というのは今年の３月までということなのですか。平成２５年のときにはほかの区だったけれども、３月の時点では品川区にいたという方は、品川区のほうから自動的に支給されると考えていいのか、その点も伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"もう１点、ゼロ円になる方なのですけれども、これは、すごく分かりやすい例をとれば、令和８年１月１日以降に生活保護を開始した人の中で、あらゆる加算がついていない方はゼロ円となります。","voiceIndex":27,"id":"exchange-008"},{"speaker":"鈴木委員","kind":"確認","question":"それは分かりました。財源なのですけれども、生活保護は国が４分の３で区が４分の１という仕組みになっていると思うのですが、それで４分の１というのは財政調整基金で算定されるという仕組みになっていると思うのですけれども、今回、東京都からのお金も入っていたと思うのですが、都支出金がどういうことで入るのか、その点について伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"そのうち、東京都の場合、東京都が持つものと区が持つものがございまして、東京都が持つものとしては、住所不定の方、つまり品川区に住民票がない方については東京都が持つことになっていますので、その分の４分の１です。","voiceIndex":30,"id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お伺いしたいのが、今の質疑を聞いておりまして、過去に生活保護を受けていたことを知られたくない方もいらっしゃるということで、こちらからのプッシュ型というのが難しいことは承知したのですけれども、ではその代わりに、やはり品川区から周知を強めなくてはいけないかなと考えます。","respondent":"豊嶋生活福祉課長","answer":"繰り返しになりますが、受給中の方はケースワーカーが責任を持ってお支払いをしますので、その辺りを、まずは一人ずつ計算の金額が違うので、そこを間違わないように、いち早く支給するということに全力で当たっていきたいと考えております。","voiceIndex":34,"id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"なるほど。ということは、区のホームページとか広報しながわ、あと区の各施設へのチラシの設置ということで、もともと今、区ができる体制の中でのみ行うということだと理解しました。国がやるものだということで、国がどういった周知活動をするのかというのを、もし区のほうで把握しているのであれば、ぜひお知らせしていただきたいのですが、いかがでしょうか。","respondent":"豊嶋生活福祉課長","answer":"チラシが各自治体にまかれておりまして、こういったものを各自治体が恐らくそういった方が利用されるであろう場所に置いて、ポスターだとやはり写真を撮らなければいけませんので、その方が、関係する方ということが分かってしまいますので、しれっと。","voiceIndex":36,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"その結果の肝炎の給付は、ちょっと年齢がばれてしまうのであれですけれども、ずっとニュースというか、政府広報で言われていますよね。私は対象年齢なのだけれども、肝炎と言われたこともないしと思って申請はしていないのですが、国のほうにそれぐらいの力は入れて広報してほしいということを品川区として要望していただきたいなと思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7421#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":12252,"voices":54}},{"id":"r08-20260527-5","meetingId":"r08-1r","date":"2026年5月27日","dateIso":"2026-05-27","committee":"総務委員会","time":"午前１０時１２分～午後 ０時４８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５７号議案、専決処分の承認を求めること","agenda":"第５７号議案、専決処分の承認を求めること","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"継続するものもある。品川区に対してどのような影響があるのか、例えば（１）大口株主だったら、このぐらいの該当者で、このぐらい影響あるということを、もし言えるのであれば、（１）から（５）まで、ざっとでよいので教えていただきたい。","respondent":"初貝税務課長","answer":"１から５まで大まかにご説明します。（１）大口株主に関しては、大口の株主はもともと総合課税の対象ですので、区民税の配当割の対象となりまして、特別徴収になります。ただ、税額は実際に課税をしてみないと、中身がどのぐらい変化があるか。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"分かりました。影響はあまり変わらないのかなと感じていますけれども、（１）の大口株主は品川区の中には結構いるのでしょうか。それと、（４）のグリーン化特例の延長です。要は、環境にいいと言っていても、環境に悪い部分もあるから、それを総合的にどう考えているのかと思っています。これは国が決めることで、品川区は関係ないので、むしろ知っていたら教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国の議論を見ると、アメリカのトランプ関税が影響を及ぼし、自動車産業が求めています。関税の問題なので、国のことだと思いますが、引き続き私たちも国に対して関税の改善等々を求めていきたいと思います。（１）に該当する方は数名いるということですけれども、これまでもともと総合課税方式をとられていて、これが区民税配当割の対象となることでどう変わるのか伺いたいと思います。","respondent":"初貝税務課長","answer":"環境性能割の補填ですけれども、実際に品川区の予算額で言いますと、令和７年度予算額ベースで７９０万円の環境性能割の予算組みをしていますので、そちらの部分に対しての補填であると思います。","voiceIndex":11,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"意見","question":"賛成ですけれども、国の地方税制の改正で今回このように変わってきたということで、物価高が続く中、生活に苦しむ区民へ地方税の面から抜本的な改善を図るべきということは、それは国の問題ですが、今回の区の条例改正は国の法改正を受けての条例改正ということで、区民への大きな負担増でもないですし、特例措置も継続される、延長されるものもありますので、賛成はいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-004"}]},{"id":"topic-02","title":"第５６号議案、令和８年度品川区一般会計補正予算","agenda":"第５６号議案、令和８年度品川区一般会計補正予算","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"しながわ電気・ガス料金緊急支援事業について幾つかお伺いしたいと考えています。大前提として、昨今の燃油料高騰や物価高騰により生活費が上がり、その影響に対する支援は必要であると考えていますし、現在の生活になくてはならない生活インフラである電気・ガス料金を補助することについて全く反対はしておりません。","respondent":"加島財政課長","answer":"ですので、見え方として急になったことは大変申し訳ないと思いますが、こちらの事業については年度当初から必要な検討を進めておりました。","voiceIndex":28,"id":"exchange-005"},{"speaker":"澤田委員","kind":"質問","question":"急いで見えたということですけれども、年度当初からお考えになっていらっしゃったということでした。補助金の考え方ですけれども、１世帯、月１,０００円となっています。この算定根拠が資料にあります。２人以上世帯の電気料金は月１万５,７６１円となりますが、単身世帯と多子世帯では使用料金が全然違うと思います。うまく伝えられていますか。分からないですか。すみません、伝わりましたでしょうか。","respondent":"加島財政課長","answer":"しかし、今回それをやろうとすると、公共料金の領収書を添付していただいたり、実際に同じ住所から４世帯分の申請があったけれども、この方のお宅の形態はどうなっているのかと、突き詰めれば実地調査も必要となってくるため、審査のコストや手間を考え。","voiceIndex":30,"id":"exchange-006"},{"speaker":"澤田委員","kind":"意見","question":"それと、高齢者の皆さんなどについて、デジタルデバイドの対応として、今回紙申請も併せて実施されると思います。これについては、しっかりとデジタルデバイドの皆さんについて届けようとしてくださっていることはありがたいと、大変評価しております。申請期限や、受け取れる日程や、紙での申請は何世帯ぐらいとお考えになっているのかお聞かせください。","respondent":"加島財政課長","answer":"紙申請ですけれども、申請書についてはご案内と同封する形で、８月下旬に世帯主宛てに全世帯に発送する予定です。封書で届きます。最初は紙で届きます。紙申請をされる方は、同封の申請書を用いて申請をしていただき、口座振込でお届けする形になります。","voiceIndex":32,"id":"exchange-007"},{"speaker":"澤田委員","kind":"質問","question":"すみません。聞き方が下手で申し訳ありません。今、届け方と申請期限をお伺いしましたが、申請期限は１０月末で、いつ頃に振込が行われるのか教えてください。","respondent":"加島財政課長","answer":"先ほど１点答弁漏れがございました。電子と紙の想定数ですが、電子が８割、紙が２割と考えております。それから、振込ですが、紙申請は９月１日から１０月末に申請をいただきまして、書類の不備がないかどうか審査等をして、支給の時期については１２月１日からを考えています。","voiceIndex":34,"id":"exchange-008"},{"speaker":"澤田委員","kind":"質問","question":"紙が１２月１日ということですが、デジタルのほうもやはり同じ１２月１日ですか。","respondent":"加島財政課長","answer":"デジタルについては、支給日は９月１日の申請開始で、即日受け取ることも可能な場合があります。","voiceIndex":36,"id":"exchange-009"},{"speaker":"澤田委員","kind":"質問","question":"全世帯に熱中症対策をすることはとても大事だと思います。そこもお考えになってくださっての今回だと思います。だとしたら、申請をチェックするなど、振込はいろいろ大変だと思いますが、高齢者の方こそ早めに対応しなければならないのではないか、そちらを優先してほしい思いがありますが、いかがでしょうか。お考えを聞かせください。","respondent":"加島財政課長","answer":"現在の制度設計上では、審査の過程で優先順位をつけることはしておりません。ただ、紙申請については、今後の予算を執行していく中で、少しでも早く振り込まれるように、所管課と工夫していきたいと考えております。","voiceIndex":38,"id":"exchange-010"},{"speaker":"澤田委員","kind":"質問","question":"優先順位は付けていないということで、理解いたしました。そうすると、経営が苦しい中、実際にこの助成を利用できる企業は限られてくるのではないかと思います。それらの企業への電気料金の補助や、原油価格高騰をダイレクトに受けるであろう物流だったり、本当に多岐にわたると思いますが、それら企業への支援策、例えばゼロゼロ融資などを行うことについて、区としてはどのようにお考えでしょうか。","respondent":"加島財政課長","answer":"ご質問の中にございました融資の関係は、今後経済団体や、それから窓口等で企業のニーズをつかみながら、所管と相談してまいりたいと考えております。","voiceIndex":40,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"今の答弁も含めて、なぜこの時期にこれをやるのかという理由がよく分からないです。中東問題と言いますけれども、それは分かっていたのではないですか。国も考えているというのは大分前から話がありました。皆さんは自覚していたのではないですか。なぜこれが今唐突に出てくるのですか。皆さんは理解していましたよね。これはいつから計画していたのですか、そこをきちんと教えてください。","respondent":"加島財政課長","answer":"本事業について検討を始めたのは４月以降になります。","voiceIndex":43,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"信じられないです。４月からですと言われればそれまでかもしれないけれども、問題が起きたのは２月でしょう。そして、区民はどうするのか、ガソリンが来ない、原油が来ないと大騒ぎになりました。それで、６月から４か月と言うけれども、今の話で、紙ベースの支給は１２月と言うではないですか。何をやっているのですか。なぜこの時期にこれをやるのですか。けれども、なぜ今なのかを教えていただきたいです。","respondent":"加島財政課長","answer":"お答え申し上げます。今でなければいつならいいのかというところですけれども。私どもは、先ほど本会議場でも申し上げたとおり、当初予算編成後における事情の変更を含んで、今回５月臨時会の場をお借りして補正予算を提案させていただきました。","voiceIndex":45,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"時期的にもずれているではないですか。何を言っているのですか。国の動きはもう既に話があったのではないですか。中東が問題になってから、大きな問題になったではないですか。その答弁はあまりにもひどいのではないですか。これとの兼ね合いはどうするのですか。どう考えればいいですか。１２億円使うのなら、ほかの方法で使えるのではないですか。どうするのですか。区民の人たちにどう説明するのですか。","respondent":"加島財政課長","answer":"こちらも報道ベースになりますけれども、一般家庭で考えれば、７月から９月の３か月分で、国の支援で大体５,０００円程度の負担軽減になると私どもも把握しています。","voiceIndex":47,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"支給するというのは、皆さん頂けるものは頂いていいのではないですか。なぜそのような行動を取るのか。そして、今回５月２５日に記者会見がありました。この赤字です。２２日以降、まだ抑えました。５月２３日が報道になっています。誰がどのような経緯でそうなるのですか。区長の記者会見は５月２５日です。今回に関しては、どうして読売新聞や朝日新聞が報道に至ったのか教えてもらえますか。","respondent":"加島財政課長、田口戦略広報課長","answer":"ただ、２０２４年夏から２０２５年夏にかけましても、２人以上世帯の電気・ガス料金は平均額でも１,０００円程度の上昇が見られますので、家計負担の軽減が実感できる額を届けたいというところが、区としての支援の趣旨です。今回の電気・ガス料金緊急支援事業については、５月２２日以降を情報解禁日と定めておりました。ですので、それ以降に、何かそのような支援などはあるかとメディアからお問合せがあったものについては、こちらで個別に対応しています。","voiceIndex":49,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"５月２２日まで抑えておいてくださいと、私たちは事前の説明をいただきました。２２日まで出すなと言っているから。けれども、５月２３日の読売新聞と朝日新聞に出ています。なぜですか。どうやってマスコミの人たちは気づいて、２３日にマスコミ報道するのですか。おかしくないですか。けれども、２３日にはもう既に公表されている。なぜですか。記者会見のことはいつアップしたのですか。どうですか。","respondent":"田口戦略広報課長、石田（秀）委員長","answer":"そのような関係でお尋ねがあった場合は、情報解禁日以降であれば個別に対応しています。待ってください。情報解禁日は２２日ですね。だから、２２日に問合せがあれば、答えたということですね。だから、２３日に出ても普通だということですね。","voiceIndex":52,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"まとめます。ただ一点、本当にこれは貴重な第一歩だと思っていますので、よろしくお願いしたいと思います。まとめとして、今まで質問しました。ほかの方も質問があると思うので繰り返したくないですが、今回のことに関しては熱中症対策になっていないというのが私の見解です。なぜなら、後で払うからです。それは理由になっていません。それをあたかも４月以降に分かったということで片づけないでほしいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これは令和５年も高い数字だったので、私たちはエアコンの設置助成を求めてきましたけれども、実現されてよかったと思っています。省エネ設備更新助成について、そもそも３年前ぐらいから実施されてきたものだと思いますけれども、この制度は期限があるので、終了するたびに私たち共産党は復活を求めて、一般質問でも取り上げたり、緊急要望をしたり、予算要望にも入れたりしてきました。","respondent":"加島財政課長","answer":"電気・ガス料金支援の本人確認書類ですけれども、公的個人認証の例としてマイナンバーカードを挙げておりますが、例えば運転免許証ですとか、パスポートですとか、住所、お名前、顔写真が載っている券面を画像として写真を撮り申請フォームからアップロードすることで。","voiceIndex":74,"id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"提案","question":"省エネ設備更新のほうでは、私たちも復活を求めてきましたので、よかったと思っていますが、やはり今回ホルムズ海峡の封鎖については、建設業や医療現場から悲鳴が上がっている状況ですので、ここにとどまらず、国に求めるものも含めて、区としてできるきめ細かな対応をぜひ求めたいと思いますし、私たちも今後提案していきたいと思っていますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"多くの委員が質問されたので、違う視点で質問したいと思います。これに書いてあるとおり、区民生活や地域経済への深刻な影響があって、それに対して迅速な対策が急務ということで今回始められる施策ですが、区民生活に深刻な影響を与えるのは、やはり収入の少ない方、年金受給者、それから非正規雇用で働いている方、その他年収が４００万円以下の方々が大変な状況にあると思います。それからお願いします。","respondent":"加島財政課長","answer":"ただ、私ども区といたしましては、ホルムズ海峡封鎖の影響による電気・ガス料金の上昇や、また熱中症のリスクを下げていく必要があるというところは、全世帯やっていく必要があるものだと考えています。","voiceIndex":77,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"先ほどほかの委員から出ていましたが、今回、支給日が最終的に９月から１２月にわたってしまう。みんなせっぱ詰まっているのではないですか。もうこれだけの状況が出ていたら、品川区として省エネルギーが見込める設備更新費用に対して助成する、支援をするというのはお門違いではないですか。それだったら小規模事業者に多くの支援をするべきではないですか。その辺についてご見解をお聞かせください。","respondent":"加島財政課長","answer":"中小企業支援についてお答えします。今回、省エネルギー対策・業務改善設備更新助成金を提案するに当たりまして、所管のほうでは、区内の経済団体ですとか、窓口でのお声を聞き取って検討を重ねてきたところです。","voiceIndex":79,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、ご答弁ありましたけれども、本来はもう分かっているのではないですか。国がこれから調査する云々ではなくて、これだけマスコミが毎日のように新聞やテレビで報道している。これだけみんな大変だ、パッケージでも何でも、町場を歩いてもみんな大変です。死活問題ではないですか。なぜそちらに目を向けないのか。私はそこの認識をもう一度見直していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-022"},{"speaker":"山本委員","kind":"質問・要望","question":"私からも質問します。私たちしながわ未来は、物価高騰が続いている状況を踏まえて、先日、区民生活と区内事業者を支えるための要望を区に提出しています。一方で、限られた財源を活用する以上、支援の目的、国の支援との関係、事務コスト、今後への活用については、丁寧な確認が必要だと考えておりますので、以下、質問と要望を申し上げたいと思います。お考えを改めてお聞きします。","respondent":"加島財政課長","answer":"私どもは、５月のゴールデンウイークのさなかに、国が今夏も電気・ガス料金の補助を行うことを検討していると報道で把握していました。ただその時点で、区としてこの支援の検討をやめるかというと、そのような考えはございませんでした。","voiceIndex":82,"id":"exchange-023"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。質問の意図は、去年もやっている中で、今年もやると予測を立てなかったのかということです。引き続きそのようにしていただきたいと要望してまいります。これは電気・ガス代だけではなく、区民の皆様に幅広く使ってもらえる、物価高対策としての支援ということなのかなと考えていますけれども、そのような認識でよろしいでしょうか。","respondent":"加島財政課長","answer":"昨年１２月の補正予算では、国の交付金を活用いたしまして、物価高騰という幅広い目的でうれしなカードの予算を取っていただきましたけれども、今回につきましては、真夏の暑い時期等を見据えた家計の負担の軽減と熱中症リスクの低減という目的を持って進めるものです。","voiceIndex":84,"id":"exchange-024"},{"speaker":"山本委員","kind":"質問","question":"１２月の支援は幅広い物価高騰支援ということですが、今回は電気・ガス料金に対しての支援に特定されているということです。というのは、間接費用がかかっているので、無駄があるとどうしても思ってしまうからです。その話で申し上げますと、今回の支援策は、区民委員会の資料によれば、事業予算は１２億５,０００万円余です。この手数料は多いと思うかどうか、区のご見解をお伺いします。","respondent":"加島財政課長","answer":"今回の事業における事務費の率としては１８.４％、しながわ生活応援事業の際は１６.０％となっております。ただ、仮に支援金を５,０００円と想定いたしました場合には、今回の電気・ガス料金の緊急支援事業に係る事務費の割合は１５.３％となっております。","voiceIndex":86,"id":"exchange-025"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。質問したのは、手数料が多いと思うかどうかという区のご見解でしたので、そこの高いと思うのかどうかというところのご見解がお聞きできなかったので、それは改めてお伺いしたいです。適正だということであれば、それで結構です。質問になりますけれども、事務手数料が多いと思うかどうかの区のご見解と、あと、今後の見通しですけれども、物価高が今ここまで続いています。","respondent":"加島財政課長","answer":"今後の見通しですけれども、今回の電気・ガス料金の支援につきましては、一過性の事業として考えております。今後の冬等の支援ですとか、また、その他の必要な支援等につきましては、区民や議会のお声を聞きながら考えていくことになろうと思います。","voiceIndex":88,"id":"exchange-026"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。今後先々どうなるか分からないからその都度判断しますと言ったら、その都度手数料も発生してくるし、割高になるというところもありますので、先々の見通しを持って、その見通しに対して効率的、効果的な支援策を考えておくことができるのではないかと思いますので、経済動向の予測を持って無駄のない効率的な区民支援を要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-027"},{"speaker":"松本委員","kind":"質問","question":"本来は所管にお伺いするべきことを、全部財政課長にいろいろ答えていただいているのは本当に申し訳ないと思いながらも、引き続き私からもお伺いします。今回の電気・ガスの支援ですけれども、申請書の発送が８月下旬ということですが、この事業自体の周知はいつ頃に行われる予定でしょうか。","respondent":"加島財政課長","answer":"事業の周知時期は、今回補正予算の議決をいただきました後、７月頃の広報で事業の周知をしていきたいと所管は考えていると聞き取っております。","voiceIndex":91,"id":"exchange-028"},{"speaker":"松本委員","kind":"質問","question":"私としては、むしろ８月になって真夏日が多くなった時期に、より効果的に、これは広報だと間に合わないかもしれないですけれども、ＳＮＳなどを使って、今すごく暑くなっていますけれども、エアコンを使っていただいても、この後、区から還元しますというような広報の在り方がとても大事ではないかと思いますが、財政課長に伺うのもあれですが、この点はいかがでしょうか。","respondent":"加島財政課長","answer":"一発目の周知ということで７月頃の広報と申し上げましたけれども、委員からございましたように、ホームページやＳＮＳ等を活用して、きちんと申請漏れがないように、それから、地域等にも説明に入っていく必要があると考えております。","voiceIndex":93,"id":"exchange-029"},{"speaker":"松本委員","kind":"質問","question":"これはどうかと思うのが、去年も同じ時期に補正予算が上がってきて、おととしも上がってきている。補正予算の額も去年とほぼ一緒です。そうすると、先ほど区内の団体からいろいろヒアリングという話がありましたけれども、そうなのかなと思うのと、逆に言ったら、区の認識としては、去年、おととしと中小企業が置かれている状況は変わっていないというご認識でしょうか、伺います。","respondent":"加島財政課長","answer":"ただ、今回省エネルギー対策・業務改善設備更新助成の補正予算で提案するに当たって、所管と話をしましたが、今回スキーム等は特に昨年と変更はないけれども、中小企業等のニーズに応じたメニューの必要性についても考えたところですが、団体からの要望を聞いて。","voiceIndex":95,"id":"exchange-030"},{"speaker":"松本委員","kind":"質問","question":"お伺いしたいのは、これも財政課が把握しているか分かりませんが、団体というのはどこの団体とそのような話をしたのでしょうか。","respondent":"加島財政課長","answer":"申し訳ございません。こちらについては所管課に確認をいただければと思います。","voiceIndex":97,"id":"exchange-031"},{"speaker":"松本委員","kind":"質問","question":"団体の関係で言いますと、先ほど申し上げたとおり、２年前も去年も同じ補正予算が上がっているということです。共産党からも少しそのようなお話がありましたが、本来は補正ではなく本予算に上げるのが財政として通常の考え方ではないかと思います。なので、本来的には、質問という形に戻すならば、この助成金については本予算で扱うべきだったのではないかと思いますが、いかがでしょうか。","respondent":"加島財政課長","answer":"その点につきましても、所管に意見を申し伝えます。","voiceIndex":99,"id":"exchange-032"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"中小企業の支援については、何ができるのか。区民生活ではいろいろなところに物価高の影響が出ている中で、我々としても電気・ガス、光熱費の要望をさせていただきましたけれども、区としても電気・ガスの補助を、現下の経済の厳しい状況の中で支援しようと判断された理由について、これまでも答弁の中で幾つか出ていると思いますけれども、その辺の議論の経過等も含めて教えていただければと思います。","respondent":"加島財政課長","answer":"先ほど国の統計等の関係でも、国の支援が入るかどうかは検討を始めた段階では定かではございませんけれども、国の総務省の家計調査等を参考に数値を集めてみますと、昨年２０２４年から２５年にかけて。","voiceIndex":101,"id":"exchange-033"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"支給のデジタルデバイドはどうしても対応しなければならないので、紙での申請もやっていただくことは必須だと思っています。紙というのは、やはり一定どうしても時間がかかるだろうと思います。今回の補正予算については、速やかに予算が成立するということが前提ですけれども、速やかに執行していただきたいと思いますので、よろしくお願いします。","respondent":"石田（秀）委員長","answer":"それをあえて住民票からスタートしているから、世帯分離の対応等はできないです。世帯主になっているかどうかという判断はそこしかないからです。そこはもうみんなやっているからよいが、経費もかかっているし、歩留まりをどれぐらいと考えていますか。","voiceIndex":103,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"要望があったからと。ただ、その要望というのも、今までの議論からすれば、毎回同じことをやっているにすぎないのではないか、本当に現場のこと知っているのか、調べているのかという指摘もありました。それはすごく重い指摘だと私は思います。今後、これを機会に、答弁にならない答弁をしないでほしいと思います。区民のほうに目を向けた施策をしていただきたいと強く求めて、賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7425#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":29971,"voices":115}},{"id":"r08-20260527-10","meetingId":"r08-1r","date":"2026年5月27日","dateIso":"2026-05-27","committee":"議会運営委員会","time":"午後 ２時２０分～午後 ２時２３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7419#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":1315,"voices":11}},{"id":"r08-20260608-6","meetingId":"r08-m06","date":"2026年6月8日","dateIso":"2026-06-08","committee":"区民委員会","time":"午後１時00分～午後２時46分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"令和８年度区民まつりの予定","agenda":"令和８年度区民まつりの予定","exchanges":[{"speaker":"まつざわ委員","kind":"質問・要望","question":"それぞれが大変だから一緒にしてやるというのはすごくいい取組で、こういったいい取組はぜひ広めていただきたいのです。そういった部分で、例えば防災地区祭りなどといった、ほかの地区への積極的な横展開というのですか、そして、区がこういうふうに、いい活動をしていますよ、などといった周知というものを区としてやっていく方向性があるのかを、まず、聞かせてください。","respondent":"平原地域活動課長","answer":"昨年度の区民まつりにおきまして、大井第２地区と荏原第３地区、それから大井第１地区のうち第三日野小学校地区で、これまでの区民まつりに加えまして防災的な要素を一緒に行うということが試行的に開始されたところです。","voiceIndex":43,"id":"exchange-001"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"要は、中止にしたいけれど、それだけのお金もかかっているし、なかなかもう難しい中で、区がある程度の判断の基準というのを、本来は区がやるというよりも、実行委員ですから実行委員で決めなければいけないのですけれど、それの後押しの部分で、この暑さ指数、熱中症対策の部分で区ができること、 どういうふうにしてほしいかなど、何かそういった思いがあれば教えてください。","respondent":"平原地域活動課長","answer":"暑さ対策は各地域において非常に重要視をして、時期をずらしてみたりなどいろいろな工夫をするところですが、例えば暑い時期に実施するところも、昼間の本当に酷暑期における取組については、体育館の中で行うなどといった工夫がされていると聞いているところです。","voiceIndex":45,"id":"exchange-002"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"私も知っていますけれど、アラートで中止というのがなかなかというのがあったりするので、分かりました。ぜひ、引き続きそういった基準、私たち現場のほうも、ある程度声を上げていかなければいけないのかなと思っています。いつもの要望ですけれど、本当に地区まつりなんかにはこうやって予算をつけていただいて、 すごく本当にありがたいと思っています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-003"},{"speaker":"新妻委員","kind":"質問","question":"特に今回、荏原地域については１０月ということで日にち変わっておりますけれども、それでもやはりどうしても夏祭りというそのイメージから、この夏の時期に開催をされているところが多いのかなと思うのですが、今あったとおり、開催については熱中症アラートが出ると、中止まではいかなくても気をつけてやるようにということとか、様々そういうことから、それは各区民まつりの開催においては。","respondent":"平原地域活動課長","answer":"仮に中止となった場合というようなところですけれども、例えばかかってしまった食材費のような、どうすることもできないようなものについては、一定程度の補填といいましょうか、そこについては見ることができるというものもありますので、そういったところを重ね合わせながら。","voiceIndex":48,"id":"exchange-004"},{"speaker":"新妻委員","kind":"質問","question":"やはり暑さに対しては、かなりもう年々激しくなってきていまして、それは区民の皆さんも留意をされているとは思うのですけれども、今年度、区として、シェードポリシーの策定ということで、その暑さについてはかなり区も力を入れて取り組んでいくというところが出てくるのかなと思っているのですが、今後この区民まつりの在り方とか、区が策定をしていく、このシェードポリシーの在り方とか。","respondent":"平原地域活動課長","answer":"そういったような自分たちでやれるような工夫といったもの、先ほどご紹介させていただきました、例えば暑い時間帯には室内で行う、日陰ができてきた時間から外を中心とした活動に変わるというような形、そういったところを組み合わせながら、まず。","voiceIndex":50,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"開催に当たって、やはり地元の実行委員をはじめ、区民まつりを盛り上げたい方は、 地域の活性化という思いで取り組んでいただいておりますので、何かその暑さに対してこういうことができたらいいのだけれど、助成されているものでは何か少し足りないということがあれば、何かここに少しかけるものがあれば暑さしのげるのだけれど、という具体的なところが出てきたときには。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-006"}]},{"id":"topic-02","title":"しながわシティラン開催報告および次回開催に向けた進捗","agenda":"しながわシティラン開催報告および次回開催に向けた進捗","exchanges":[{"speaker":"まつざわ委員","kind":"確認","question":"１件確認です。ボランティアの募集の中で、消防団の活用というのが、あるのか教えてください。","respondent":"山下スポーツ推進課長","answer":"消防団に関しましては、これまでも品川消防団、大井消防団に関しましては区域ですので、 警戒活動をしていただいております。こちらのほうからお申出がありましたので、毎回依頼文を差し上げまして、警戒の区域を指定いただいているところです。","voiceIndex":57,"id":"exchange-007"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ぜひ、荏原もやってください。障害者優先枠でしたか。これを新設したというのはすごくすばらしいかなと。すると多分、これで５０人などにしてしまうと、そのほかのサポーターが例えば何人か入ってきたときの、一緒に走る方の分まで参加料を無償にしていただきたいなみたいな感覚があるのです。そこら辺まだこれからだと思うのですけれど、感覚としてはどのような感じなのか教えてください。","respondent":"山下スポーツ推進課長","answer":"最初の、伴走者がつけられるかどうかという形なのですけれども、障害の有無をチェックしていただいた後に、伴走者が必要かどうかというチェック欄も設ける予定でございまして、そちらにチェックをつけていただきましたら、伴走者の方の。","voiceIndex":59,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"２点確認させてください。というのは、やはり参加できなかった人もいるわけで、そういう方たちが、一応２次の締切りまで設けられていると思うのですが、ここの、もしかしたらこんなに少ないのだったらもっと、自分も参加したかったよねと思う、外れてしまった方からの声もあったりするので、その辺りの考え方を教えていただきたいと思います。","respondent":"山下スポーツ推進課長","answer":"当選者なのですけれども、大変申し訳ございませんでした。令和７年度なのですけれども、 ２,５００名の定員なのですが、当選者を２,７３０名という形で、２３０名ほど、少し多めに出させていただいております。","voiceIndex":61,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問","question":"それでも当日の参加者が減っているということですよね。そうすると、もう少し、この９０.６％の参加率というのは、ほかの自治体でも大体これぐらいだということなので、そこら辺を見据えて、もう少しこの当選者数というのでしょうか、そこを多くしておくというのは、その検討の中では検討されているのでしょうか。","respondent":"山下スポーツ推進課長","answer":"参加人数より２３０名ほど、１０％ほど多めに出してはいるのですけれども、何分、この９０％にとどまっている要因といたしましては、前の週にやっている東京マラソンとの兼ね合いもあるのではないかという形なのですが、３月のこのような時期でございまして。","voiceIndex":65,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"分かりました。そこは区として、それは１００％を求める必要もないのかもしれませんけれども、走りたいと思っている方がしっかり走れる態勢ということを、しっかりまた、そこは考えていただきたいなと思います。","respondent":"山下スポーツ推進課長","answer":"委員お尋ねのとおり、どのようにお渡しすれば、事前に送付するものはあるのですけれども、そこの中に入れてしまうと持ってきていただけないねとか、その場でお渡ししたほうがいいのではないかとか、 でも、結局マラソンをするときは置いて帰ったりするので。","voiceIndex":67,"id":"exchange-011"},{"speaker":"横山委員","kind":"確認","question":"こちらの５番のところの、今、新妻委員からもあった、リバースメンターの部分なのですけれども、 こちらはリバースメンターの方から具体的にどういった提言があって、多分そのマップだけではなくてほかのことも提言があったような形で、ホームページの報告に書いてあったのですけれども、どういった経緯で今回、このシティランでマップという形になったのか、確認させてください。","respondent":"山下スポーツ推進課長","answer":"シティランのマップに関してなのですけれども、普通にランのマップだったのですが、せっかく旧東海道など見どころを走るということがあるので、そういうところの観光情報ですとか、あとはおいしいお店などをご紹介したほうが、その後立ち寄っていただけるとか。","voiceIndex":69,"id":"exchange-012"},{"speaker":"横山委員","kind":"提案","question":"とてもすばらしい提案内容であって、ぜひ実現していただくというのを楽しみにしているところなのですけれども、先ほどの話もあったのですが、事前に見ていただいたりとか、あとは、私も前回参加させていただいて、いろいろなものが送られてきて、事前にチェックするという時間もあったので、ゆっくり事前に見て、走り終わった後ここに行ってみたいなという方もいらっしゃるでしょうし、 また。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-013"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.08ku.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":29,"characters":36959,"voices":76}},{"id":"r08-20260608-7","meetingId":"r08-m06","date":"2026年6月8日","dateIso":"2026-06-08","committee":"厚生委員会","time":"午後１時00分～午後３時46分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"しながわ未来の筒井ようすけと申します。１年間、どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":4,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"職員配置で伺いたいのですけれども、電子６ページで、福祉部の障害者支援課は、去年に比べて５人増えています。その点も伺いたいと思います。これは共産党としてもずっと、このような大きな計画、主要な計画に対しては、説明会をしていただきたいと求め続けてきましたので、すごく大きく評価していますし大歓迎なのですけれども、いつ頃どのような形を考えているのか伺いたいと思います。","respondent":"石橋障害者施策推進課長、芝野障害者支援課長、崎村障害者施策推進担当部長","answer":"本年度初めての試みになりますので、今後、説明会の実施方法等は所管で検討にはなりますが、今回、１１月の中旬以降。相談支援担当は事務職が担っているのかですが、今回は事務職で配属はしていただいているところですが。施政方針で法的拡充ということをお示しさせていただいて、具体的にどのように進めていくのか。","voiceIndex":48,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから次に高齢者福祉を、介護保険も含めて伺いたいのですけれども、今年は第十期介護保険事業計画の策定の年になりますけれども、障害者福祉は、自立支援協議会とはまた別に策定委員会がつくられて検討されていますけれども、介護保険の事業計画は、介護保険制度推進委員会が策定委員会も兼ねて計画するということなのか、そこの点を改めて確認させていただきたいと思います。","respondent":"佐藤高齢者福祉課長","answer":"障害の計画と同様に、どういった形で区民にご説明するか、これからの検討ですけれども、説明する場を設けたいと考えております。","voiceIndex":52,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"説明会もやっていただける方向だということで、本当にすごく評価していきたいと思います。私も傍聴をできる限りやりたいと思っているのですけれども、傍聴者もすごく少ない状況なので、それは少し工夫していただけたらと要望させていただきたいと思います。認知症策定委員会のことは、言っていないですよね。では、認知症策定委員会のことについてもいいですか。前の質問への答弁が漏れてしまっていたので。","respondent":"樺島高齢者地域支援課長","answer":"計画策定に当たりまして、６回ほど委員会を開催する形になっておりまして、委員の構成も、学識経験者、医療関係者、福祉関係者だけではなくて、 認知症のご家族、ご本人、当事者の方もご参加いただく委員会となっております。","voiceIndex":54,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それは傍聴が可能なのかも教えていただけたらと思います。先日、実は結構いるという話を伺ったと思ったのですけれども、その辺の実態が、今、在宅介護支援センターに保健師またはそれに準ずる看護師の配置がどうなっているのか、お聞かせいただきたいです。それで、 これを見ると保健師は、非常勤を入れても５人しかいないことになっているのですけれども、その実態がどうなっているのかを伺います。","respondent":"樺島高齢者地域支援課長、冨田地域包括支援センター担当課長","answer":"認知症策定委員会につきましては、現状、公開というのはあまり想定はしていないですが、適宜、会議録等は適切に周知していきたいと考えているところです。もちろん、その予算措置はしておりませんけれども、形としては、 必要であればできると認識しておりますので、そういったものの必要性は検討してまいりたいと考えております。","voiceIndex":56,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"啓発の学習会の講師ですけれども、結構いろいろなことでの学習会の講演会なども、そういうことをやることで地域の意識が高くなることで、本当に健康や予防につながっていくのはすごく大きいと思っていまして、品川区の場合は地域に地域包括支援センターがなかったために本当に取り組まれてこなかったと思うのですけれども、実際、区の直営であるので、要望があったときには、そこで派遣できるという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"それから続けて高齢者部門の去年のお水を配った事業で、アンケートが６割前後から回答があったということなのですが、どういうアンケートの結果、こういう状況が分かったとか、それに対してどういう対策をこれから検討していくとか、そういうご報告はないのか伺いたいと思います。それと、６割前後からの回答というのは数としてどうなのか、評価を伺いたいです。","respondent":"芝野障害者支援課長、冨田地域包括支援センター担当課長","answer":"私からは、基幹相談支援センターの役割、位置づけという点について、ご説明します。品川区の相談支援事業関係は、基幹相談支援センターが１つ、拠点相談支援センターが６つです。その他地域の相談支援事業所が１８か所あります。６割程度の方にお答えいただいたアンケートですけれども、感想としては、６割は、比較的多い方にご回答いただいたと考えています。","voiceIndex":61,"id":"exchange-007"},{"speaker":"吉田委員","kind":"確認","question":"分かりました。基幹相談支援センターについては、今のだと、障害者支援課全体がということなのでしょうか。何回か私も質問で取り上げたと思うのですけれども、そのときに、基幹相談支援センターを名のっているけれども、基幹相談支援センターという看板はないのです。地域包括支援センターはそれぞれ看板を掲げていると思うのです。もし何かコメントがあったら伺いたいと思います。","respondent":"芝野障害者支援課長、冨田地域包括支援センター担当課長","answer":"引き続き説明しますが、地域にあります拠点相談支援センターとの連携を図るために、総合的な相談支援や相談支援体制の強化を目途に設置しているものでございまして、国の基本方針にも、設置は努力義務ですが。評価が分かれるというご指摘がありましたけれども、やはり区にも、２０通を超えるお礼のお手紙やお電話で、ありがたいというお話を頂いたと聞いておりますので、どのような施策を取ったとしても。","voiceIndex":64,"id":"exchange-008"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"この未配達分はどのようになっているのか、１つ確認。宅配件数は、９５％ぐらい宅配できているのですが、アンケートの回答が６０％前後で、３５％ ぐらいの乖離が、どういった原因なのかをお伺いしたいのが２点目です。熱中症予防のアンケートです。次は社会保険の概要ですけれども、国民健康保険ですが、外国人の方の国民健康保険についてお伺いいたします。健康衛生ですが、梅毒についてお伺いいたします。","respondent":"冨田地域包括支援センター担当課長、山下国保医療年金課長、菅野福祉部長、五十嵐保健予防課長","answer":"今、アンケートの回答が６割で、３割ぐらいの方は、やはり先ほど申し上げたように、アンケートしたくないと拒否されたり。これに対しまして、外国人の方の給付というのを特出しで分析は基本的には行っていないのですけれども、端的に令和６年度のレセプト全体から。先ほどの説明にもありましたけれども、もともと対象外としました特別養護老人ホームや介護老人保健施設。性風俗を利用されている方で少しやはり多かったものや、ＭＳＭの方などについても、やはりかなり増加している部分もありますので。","voiceIndex":68,"id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"提案","question":"アンケートの公表は、別に個人のプライバシーに抵触するものでもないと思うので、公表して、何かしら第三者が有効に使える可能性もあるものだと思うので、その辺も、それこそ私も見てみたいと思いますし、公表をぜひ、有意義なアンケートは公にしたほうがいいと思いますので、その辺はご提案させていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"外国人の国民健康保険のですけれども、私がなぜこの質問をしたのか、先にお伝えし忘れたのですけれども、やはり近年、外国人の方が国民健康保険にただ乗りしていて、ずるいという言説が非常に多くある現状があって、先ほど私も説明しました、外国人の被保険者率は４％で、医療費で占めるのが１.４％で、むしろ国民健康保険全体を支えているのは実は外国人の方だという数字が、実際はそうなっているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私はぜひとも、 東京都がそういう形で４分の３を出して、品川区の負担は４分の１になるわけですから、東京都の条件のように、品川区としても縛りを外していただきたい。そういう点では、本当に命を救う。ぜひ町会長や高齢者クラブ会長の会議や、民生委員の会議などにお知らせいただいて、 孤独死をなくす、救える命を救うということでも、増やしていただきたいのですけれども、その点についても伺います。","respondent":"豊嶋生活福祉課長、宮澤福祉計画課長","answer":"少なくとも品川区は、今年度はゼロを１にすることをまずは考えて、命を守るということで進めしていますので、 次の話はまた次の手として、今後検討すべきものと考えています。は今年度、ゼロを１にさせてください。事業をもっと知っていただくということで、民生委員協議会をはじめ、周知してはありますけれども、引き続き工夫しながら周知してまいります。","voiceIndex":76,"id":"exchange-012","title":"町会・自治会支援"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ゼロを１に、品川区から先に予算化したということで、それはよく分かりますけれども、東京都がこういう形で４分の３になりましたので、柔軟にご検討いただけたらと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-013"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.08ko.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":37,"characters":50937,"voices":87}},{"id":"r08-20260608-8","meetingId":"r08-m06","date":"2026年6月8日","dateIso":"2026-06-08","committee":"建設委員会","time":"午後１時００分～午後３時０４分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"えのした副委員長","kind":"意見","question":"副委員長を務めします、えのした正人です。１年間どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"私たちとしては、こちらの見直しが必要なのではないかということをたびたび発言させていただいているのですが、中間見直しの予定はあるのか、もしあるとしたらどれくらいを考えているのかというのをお伺いしたいのが１つです。併せて、４月から阿部部長が東京都から着任されたということなのですけれども、東京都ではどのような業務を経験してこられたのか、簡単に略歴等も伺えればと思います。","respondent":"髙梨都市計画課長、阿部都市整備推進担当部長","answer":"まちづくりマスタープランに基づいて品川区のまちづくりを進めているところですけれども、特に再開発事業であるとか、 立体交差事業等々、東京都等と非常に密に連携・協議をしていなければいけない業務であり。今回新しく品川区でお世話になるというところで、また何年か前、１０年ぐらい前になりますけれども、区画整理みたいな、まちづくり関係というところで、新しく来たです。","voiceIndex":56,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。最後にもう一つ、都市計画課にある空港環境担当が１名組織としてあるのですけれども、具体的にはどのような業務を行っているのか。昨年度も分科会４回、幹事会２回行われて、品川区も全て参加しているということなのですが、この関係区市連絡会というのはどのような場所なのか、品川区はどのようなスタンスで臨んで何を発言しているのか、そこについても併せて最後に伺わせていただきます。","respondent":"髙梨都市計画課長","answer":"改めて我々レベル、部長・課長級レベルにおいても、国に対してしっかりと区の要望事項を伝えられる場として認識しています。","voiceIndex":59,"id":"exchange-003"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"今回非常に早く対応していただきまして、小学校、中学校、区立学校、 幼稚園をはじめ、お休みの決定など周知も早かったので、混乱が少なかったのかなと考えています。人的被害もないということで、非常に安心しております。物的被害のところで１点お伺いしたいのですが、道路冠水とマンホールからの溢水は、どちらのエリアで、どういった状況なのかを簡単にお聞かせいただければと思います。","respondent":"森道路課長","answer":"下水道管の能力を超えた水があふれて、マンホールから水がばしゃばしゃと噴出したです。それから道路冠水につきましては、大井一丁目立会道路のところが１か所、もう一か所は確認して、 後ほどご答弁いたします。","voiceIndex":65,"id":"exchange-004"},{"speaker":"おぎの委員","kind":"質問","question":"マンホールからの溢水は東品川四丁目ということで、下水能力を超える雨量だったということ、今の計画でこのまま進めていけば、こういった問題は特に見直ししなくてもいいのかをお聞きしたいのが１点です。ごみ、落ち葉などが挟まっていたという部分です。１点、今の計画で大丈夫かという部分だけ見解をお願いいたします。","respondent":"関根河川下水道課長","answer":"ですので、能力的な問題以外にもそういったところもちょっと関係しているということで、何かできる対策があるかといったところは、今後下水道局と連携して取り組んでまいりたいと考えております。","voiceIndex":67,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"昼夜分かたぬ区民の安心のための対応に心より感謝申し上げます。質問なのですけれども、エレベーターの停止とありますけれども、こちらの原因というか、状況などはどうだったのかというのを伺いたいと思います。伺いたいと思います。１０名の方が避難ということなのですけれども、避難された時間というのは大体この時間でしたとか、そういうのはあるのでしょうか、伺いたいと思います。","respondent":"森道路課長、羽鳥防災課長","answer":"勝島歩道橋にくっついているものです。そちらのドアの開閉部分に雨の水が少し入って、不具合が生じたと聞いております。管理会社がすぐに駆けつけまして、部品等を交換して、夕方１９時には復旧して、運転を再開しているところです。避難指示を出すということは、ご自宅が安全であれば、避難場所に行く必要はありませんということ、また、大雨であれば、避難場所に立ち退き避難をすることなく、例えば上の階に避難できるのであれば、垂直避難も可能ですということは。","voiceIndex":69,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"今回台風が通過するのが結構早かったというのはあるのですけれども、スピードが速いといいますか、状況が急変するというか、避難指示を出すのはすごく大事な局面なのですけれども、出さないで、こちらが予想していた以上に風雨が激しくなったら大変なことになるわけですから、出す必要があるわけなのですけれども、実際避難指示が最初出ますと、区内全域への避難指示が出るわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"避難所についてです。確認からです。併せて、土砂災害による避難所が２か所追加ということで、この時点で２か所追加された意味というか、最初からそこら辺も想定されて避難所を開設されたほうが、後で「何もなくてよかったね」というぐらいの態勢というのはあっていいのかなと思うと、この時点で２か所を開設するよりは先にと考えるわけですが、その辺の避難所開設の考え方というところも確認させてください。","respondent":"羽鳥防災課長","answer":"雨の状況が、雨が降り始める前の１７時に災害対策本部を開設いたしまして、同時にコールセンターを設置して、自主避難施設を開設するご案内をさせていただきました。区民の皆様からの様々なお問合せに対応できるような態勢をまず一旦取ったということです。","voiceIndex":73,"id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"前日に避難された２名の方の状況は分かりました。それから、２０時の開設、分かりました。地震とは違って、台風は進路等でどういう態勢を取れるのかというのをあらかじめ見通せる災害でもあるかと思うと、そこら辺はできるだけ早く、明るいうちにというか、できれば夕方ぐらいの時間でというのがあってもいいのかなという思いで、２０時がなぜその時間だったのかというのを確認させていただきました。","respondent":"羽鳥防災課長","answer":"夕方の段階ですと、まだ雨も降っていない状況ですので、早いアナウンスがかえって誤解を呼ぶこともあるかもしれない。様々検討した結果、１７時に本部、２０時に開設ということでございました。今後この適切な時間帯というのは考えてまいりたいと考えています。","voiceIndex":75,"id":"exchange-009"},{"speaker":"こんの委員","kind":"質問・要望","question":"様々ありがとうございました。るる質問をいたしましたけれども、最初に言わなければいけなかったのですが、今回の対応も本当に素早くやっていただき、総合的には素早い対応でこのようにやっていただきました。細かい課題等々が見えたところは、次回そこを活かしていただきながら、引き続き対応していただきたいと思います。今回も本当にありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-010"},{"speaker":"高橋委員","kind":"質問・要望","question":"１点だけ質問なのですけれども、コールセンターを開設して、問合せが合計で８３件あって、課長のご説明だと、主なものは、防災無線が聞き取れないという声があったということなのですけれども、これは分かる範囲でいいのだけれども、合計８３件あって、防災無線の問合せというのは、かなり、半数ぐらいはあったのですか。今私の想像で話しているのだけれども、分かれば教えていただきたい。","respondent":"羽鳥防災課長","answer":"合計８３件のうち、情報発信に関するものが２７件、 そのうち、詳細まで取っておりませんが、その大半が防災行政無線についてです。２０件近くであるという認識です。同様に多かったお問合せといたしましては、避難に関するものが２４件のお問合せいただいたという状況です。","voiceIndex":78,"id":"exchange-011"},{"speaker":"高橋委員","kind":"質問","question":"分かりました。今回の対応以外でも、防災無線はすごく活用するではないですか。台風だったら風向きによったり、いろいろあるではないですか。それによって聞こえが悪いから、その都度、音量の調節とかというのは、常に通年通してではなくて、四季によって音量を変えたり、地域によって、今まで ５だったのを、夏になったら８にするとか、そういう対策があるのですか。","respondent":"遠藤防災体制整備担当課長","answer":"そういったところに関しましては、我々も防災行政無線の性能といったところを、新庁舎の移転に伴いまして、スピーカーも、音響に関しても今後検討していきます。こちらで改善できるところがあれば、改善していきたいと考えております。","voiceIndex":82,"id":"exchange-012"},{"speaker":"高橋委員","kind":"質問・要望","question":"ぜひ検討していただいて、聞こえないというのはもう本当に困っているから、それで防災無線を聞いてくださいと分かるのだけれども、特にご高齢の方とか、それぞれ、それは分からないですよ。高齢の方は多分本当に聞こえが悪いから、避難していいのかどうかというのも含めて、コールセンターにかかってくると思うので、ぜひ検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-013"},{"speaker":"えのした副委員長","kind":"質問","question":"私も１点だけ、先ほど防災課長からもご答弁いただいていますけれども、避難指示が出るということは、避難場所に行かなければならないのかという区民の誤解も多かった中で、こんの委員、また高橋委員からも、防災行政無線、避難に関することも２４件と結構多くて、私も、地域の方から一番お声が多かったのがここで、品川区はこんなに雨降っているのに、なぜ避難指示を出すのとか。","respondent":"羽鳥防災課長","answer":"今後出水期はまだ続きますので、事前の広報というところで、避難についてもしっかり周知してまいりたいと思ってあります。","voiceIndex":85,"id":"exchange-014"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"しっかり周知啓発をしていただければ、こちらは要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-015"},{"speaker":"安藤委員","kind":"提案","question":"所管事務調査、幾つか提案したいのですが、１つ目は住宅なのです。２つ目は再開発なのです。前区長が東京都からの意見照会に対して手を挙げたことで、特定整備路線に指定されたのがこれらの道路なのですけれども、今は区長も替わりましたので、ここは思い切って見直すべきときなのではないかと、特定整備路線整備と、まちや暮らしへの影響について、所管事務調査に入れていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-016"},{"speaker":"こんの委員","kind":"提案","question":"確認ですが、今の安藤委員のご提案の中の住宅という観点は、そちらは特別委員会で所管するものだったとすると、私も聞いていて、あれ、建設委員会での所管事務調査は、そこはできないのかなと私の中では思っていたのですが、その辺も含めて正副でということですか。確認です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-017"},{"speaker":"安藤委員","kind":"提案","question":"先ほど所管事務調査のところで、まちづくりというか、再開発について提案させていただいたのですが、住民参加といったところでまちづくりを積極的に進めている自治体という例で言うと、世田谷区とか練馬区とかは、まちづくり条例をつくっているわけです。そういったところは、非常に参考になると思うのです。意見を述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-018"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.08ke.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":30,"characters":38488,"voices":95}},{"id":"r08-20260608-9","meetingId":"r08-m06","date":"2026年6月8日","dateIso":"2026-06-08","committee":"文教委員会","time":"午後１時00分～午後３時40分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"山本副委員長","kind":"意見","question":"副委員長を務めしますしながわ未来の山本やすゆきです。１年間、どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"どのような手段で実現させようとしているのかお聞きしたいと思います。そういうウェルビーイングという観点からいえば、いじめや不登校は解決すべき大きな課題と品川区も思われていると思うのですけれども、直近の小中学校ごとの件数や推移が分かる形で数字を伺えたらと思うのですが、分かればでいいです。それで、この４月での担任の不在があったのかも分かれば伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"提案","question":"それと、やはり日よけの問題なのですけれども、暑い日にはプールや校庭で遊べなくなるというのがすごく子どもたちからも、保護者からも遊べなくなってしまったという声等を伺いますし、授業にも支障が出る状況ですので、そこら辺はぜひ、球技等、種目によっては制約がないようにしていかなければいけないとは思うのですが、やはりそうした日よけ対策をさらに進めていっていただきたいですし、議会からも。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-003"},{"speaker":"西本委員","kind":"確認","question":"４つほどお聞きします。確認したいと思います。それから、３つ目が４０ページに探究的な学習というのがあります。そうなってくると、責任の所在はどちら側にあるのだろうかというのが最近分かりづらくなっているというのがあるので、教育現場が福祉的な現場になっているというところに置いていくと、どういう関係を持ちながらやっていくのでしょうかということの全体の考え方をお聞きしたいと思います。","respondent":"荒木学校施設担当課長、石井学務課長、髙木教育施策推進担当課長、舩木庶務課長","answer":"今年度の検討内容につきましては、残りの２校を除いた１６校についても知見やノウハウといったことは反映してまいりたいと考えています。中学校につきましては、従前と変わらず、東京都が２分の１を見るという形になっております。どちらもまだ計画段階からの予算でしたので、今年度の試行を経て、実際に予算化していきたいと考えていますので、今は計画。それは緊急時の危機管理対策とか安全管理とかそういうところも含めて、一定程度の課題に対してどのような方法を考えるかということは。","voiceIndex":53,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"学校改築は、取りあえず２校という形なのですけれども、非常に周辺の、改築しにくいという条件は、 ほかの１６校も同じなのです。なので、そこはきちんと計画を示していただきたい。全校にそれを広げていただくということを、初年度、教育委員会として取り組むのは初めてになってくると思いますので、しっかりやっていただきたいと要望して、いろいろと報告をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"なかなか教育長や次長のお考えを伺える機会はないので、よろしくお願いしたいと思います。そしてもう１つは、学校教育や庶務や、今日も説明がありましたけれども、いろいろな学務、それぞれ課題が縦割りにならないように、事務局全体をどのようにまとめていくおつもりであるか、もちろん資質があるということで、次長という役職に就かれていると思いますので、当然ですが、その意気込みを伺います。","respondent":"伊﨑教育長、小林教育次長","answer":"昨年からウェルビーイング推進校、重点校等々進めておりますので、今年もそれを継続するとともに学校を拡大して進めていきたいと考えているところです。そういったことで、今、教育委員会として、こういうものが課題である、こういうことに取り組んでいかなければいけないというのは、教育委員会全体の管理職あるいは職員と共有しながら、その中でチー ムワークを高めて。","voiceIndex":60,"id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問","question":"なかなか１年の最初に教育長や次長の意気込みを聞く機会がないので、すみません、あえて伺いました。今、次長からチームワークでという言葉が２回も出てきたので、すごく大事だと思いますので、ぜひ、その意気込みでお願いしたいと思います。教育長からもお話を伺いました。そのようにしていただけるというそういった意欲も、言い方は失礼ですけれども、決意も伺えたので、ぜひお願いします。","respondent":"伊﨑教育長","answer":"小学校、中学校につきましては、それぞれ小学校の課題、中学校の課題は学校ごとに様々な課題がありますので、学校長がきちんとそれに対して自分の学校の特徴をつかんで、課題をつかんで。","voiceIndex":63,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問","question":"ありがとうございました。今回はそういった意気込みをお伺いしたので、また別の機会にお尋ねしていきたいと思います。ぜひ、１年間、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問","question":"子どもの施策等、この分野においてもウェルビーイングシティしながわを基本理念に掲げていることで、ウェルビーイングが掲げられておりまして、そういったところでも、こどもの権利条例は大変大事なところだと思っているのですが、２年間かけて令和１０年に策定されるということで、令和８年、令和９年で様々ワークショップやらこども会議やらをやられていくことですけれども、今現在はどういう状況なのか。","respondent":"柴田子ども施策連携担当課長","answer":"ユースヘルスケアしながわほけんしつの取組なのですけれども、委員から今、ご指摘いただきました、他課との協力、連携というところなのですが、現在も健康課ですとか人権・ジェンダー平等推進課とそれぞれ実施事業を共有しておりまして、重なるところは。","voiceIndex":77,"id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"提案","question":"こどもの権利条例のところは、本当に今後、品川区内でみんなが知っていくことも大事になると思うので、今、ご説明があったように、様々なところで知らせていく、目につく形でアンケート等もやっていくのがすごく必要になってくると思いますので、引き続き、見守りつつ、提案もさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか確認をさせていただきたいと思います。あなたは幸せですかといっても、何が幸せなのかどうか分からないというのがあるので、それで、間違ってほしくないのは、こどもの権利条例ですから、親ではありませんので、子育て支援になると、今、品川区でやっている主なものは親支援です。経済支援が中心ですから。この間、どうされるのですか。この実態をどうされているのですかというのを教えてください。","respondent":"柴田子ども施策連携担当課長、柏木子育て応援課長、佐藤保育入園調整課長","answer":"そのような視点を持って実施しています。ただ、昨今の高校生の授業料無償化等もありますので、今後、制度につきましては、機会があるときに改めて検討するべきものと考えています。利用されている方の状況等を踏まえて、利用状況、 利用率といったところを確認しながら、そこの整理を進めていくというところで、現在。","voiceIndex":81,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"その足がけを今年度からやっていただきたいと。保育料、それから幼稚園の、これは確認だけです。施設に通っている方々の子どもたちは全て無償という感覚でいいですか。なので、具体的なことはこれからなのでしょうが、やはり単独幼稚園であっても希望者が多いということを考えるとなかなか廃園は難しいのではないかと思うのですが、当面、廃園はないという認識でいいのかどうかを確認したいと思います。","respondent":"佐藤保育入園調整課長","answer":"幼稚園のところですが、委員のおっしゃるとおり、ニーズ等を見ながら、今後の検討の部分については、時期等を見定めながら進めていくです。","voiceIndex":85,"id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこでまず第一に、子ども未来部として、最も今年度、重点的に取り組みたい課題はどのようなものとお考えでしょうか。３番目には、家庭です。最後になりますけれども、教育行政を経験した部長として、子ども未来部をどのように運営して、子どもたちの育ちを支えていくのが、大変幅広い事業を行わないといけないということで、大変さは認識しておりますが、今年度にかける意気込みを伺います。","respondent":"米田子ども未来部長","answer":"やはり一番重点的に、今、思っておりますのは、先ほど来、ご質問にも出ておりますように、２か年はかけるのですけれども、こどもの権利条例の制定について、しっかりと、まず子どもの権利というものについては、先ほど大人という話もありましたけれども、大人も、それから品川区。","voiceIndex":88,"id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"子ども施策のプロとして、必要な場合は子どもを真ん中に置いてという考え方で意見を述べていって、施策に反映していっていただきたいと思います。様々な提案がトップおよびその周辺から出てくると思うのですけれども、子どもを真ん中にという考えの子ども施策のプロとして、子ども未来部の部長として物申していっていただきたいと思うのですが、その点についてのご見解を伺います。","respondent":"米田子ども未来部長","answer":"こういうものを模索していくことが重要だと考えていますので、その辺を念頭に置き、自らのところだけの利益を決して最重要視することなく、子どもたち全体の最善の利益について、家庭もそうですが、そちらを念頭に置いて注力していければと思っています。","voiceIndex":90,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"この人材の確保と育成というところでもご説明がありましたけれども、やはりここが大事になってくるのかと思うのですが、ここでの人材の確保と育成での課題は今の時点であれば伺いたいと思います。","respondent":"阿部児童相談課長","answer":"こちらにつきましては、現在、対応策としまして、 性虐待に遭った子どもに対する、日本でそういった面接技法を教えていただいている外部講師から学ぶ被害確認面接など専門性の高い研修メニューを所としては用意しまして、職員の心理的負担を減らしながら。","voiceIndex":98,"id":"exchange-015"},{"speaker":"西本委員","kind":"確認","question":"確認をさせてください。きちんと区分けができているのかと、補助金は解決したのでしょうか。なので、もう少し詳しく教えてください。それから一時保護所は品川景徳学園のことですか。それともこの一時保護所というのは、ほかの施設もあるのですか。分かりました。この一時保護所というのは、言えないと思うのですけれども、どんなところに何か所ぐらいあるのかを少し教えてください。","respondent":"阿部児童相談課長","answer":"その際には、オンラインの会議をしながら、こういった地域で見守りが必要な子どもがいらっしゃるのですが、子ども家庭支援センターのほうで協力といいますか、主に担当して、今後この世帯を見守ってくださいますかということを相談しながら、両方で役割分担をして。","voiceIndex":101,"id":"exchange-016"},{"speaker":"西本委員","kind":"意見","question":"要するに、東京都品川児童相談所は大田区の業務だけで、品川区は全部移管されたということでよろしいですね。品川景徳学園ではなかった。品川区の中に１か所あるのですね。これもないと困るので、本当に多くなればやはり別途考えていかなければいけないことなのかと思いますので、また今後、動向を調査等々しているのであれば、その報告もお願いしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問","question":"本当はもっと大変なことがたくさんあるのだと思います。２つ目に、これは本当にやることがたくさんあるので、どれを重点的にというお聞きの仕方が失礼かもしれませんが、令和８年度は重点的に取り組む課題はどのようなことになるのでしょうか。虐待対応、 家庭支援あるいは今、ほかの委員からのご質問もありましたれども、職員体制などを含め、どこに力を入れていこうかとお考えになっているか伺います。","respondent":"原品川区児童相談所長","answer":"子ども家庭支援センターもそうですが、子ども未来部あるいは教育委員会、いずれも同じ品川区というくくりの中で、それぞれの機能を活かしているというところでは、お互いの機能を持ち寄って、子どものために何ができるかを、非常にスピーディーに検討できる、話し合える。","voiceIndex":105,"id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"意見","question":"ありがとうございました。１年間、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-019"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"これから委員から要望が出てくるとは思いますけれども、ぜひとも探究的な学習を柱に私はやりたいのです。なので、皆さんも少し深く今年度から始まる事業でもあるので、また先行的にやっていることもあるので、そこは少し入れたいという。一応、要望は出しますけれども、ご理解を求めたいと思って発言させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-020"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.08bu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":38,"characters":50732,"voices":114}},{"id":"r08-20260608-5","meetingId":"r08-m06","date":"2026年6月8日","dateIso":"2026-06-08","committee":"総務委員会","time":"午後１時00分～午後２時47分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"２件ずつとなると、いつまでに全てが完了するのかを伺いたいと思います。それと、３３ページの公契約条例について。件数も令和５年度とは桁違いに上がって１万２,０００件となって増えているということで、これはどういった理由なのかを伺えればと思いますし、この間、返礼品競争にはくみしないという姿勢だったと思うのですけれども、そういった姿勢が変わったのかどうかも伺いたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"脱炭素については、２件ずつで令和１２年度までということでした。今年度を入れてあと５年ですか。なかなか設置できていない。５年たつと、２０３０年を越えることになってしまいます。２０３０年までカーボン・オフということだと思いますので、ぜひこれを早く進めて、カーボンは ６０％ですか。公契約条例については、会計年度とか区の給料表を参考にされているということでよろしいですか。","respondent":"廣瀬経理課長","answer":"失礼いたしました。そちらは委託の金額でございまして、工事の部門については工事の設計単価を出すときの公共工事設計労務単価を参考にしております。","voiceIndex":94,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"労務単価を参考にされているということで、これは労務単価と同額ということでよろしいかを確認させていただきたいと思います。なので、伺いたいと思います。続けて、区長室について。これは大変重要だと思うのですけれども、主流化はどう進めていこうと考えているのかを伺いたいと思います。参加者なども伺えればと思います。まだ届いていなければ、どう推進していこうと考えているのかを伺いたいと思います。","respondent":"廣瀬経理課長、木村人権・ジェンダー平等推進課長、横田人事課長","answer":"最初の労働報酬下限額の話ですけれども、公共工事設計労務単価と同額ではなくて、そちらを参考にして９０％を目安として算出しております。今のところ、計画を推進するというところで昨年の計画策定のところから相談を各課としておりますので、そちらのほうで進めていく予定です。令和７年４月１日採用は正規職員で５名採用しておりまして、令和８年４月につきましては５名の採用を予定をしていたのですが、２名辞退がありまして。","voiceIndex":96,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"障害者の法定雇用率のところでは、まだ達成されていないということで、現状の数字が分かれば伺いたいと思います。ジェンダー平等について。ジェンダー平等推進行政連絡会議というのは、実務的な会議というよりは大きな政策を決めるときに開くような会議ということですか。そこを確認させていただきたいです。何年やったら熟練なのかが分かれば伺いたいです。実際に見習だと１,６３７円だと……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-004"},{"speaker":"石田（秀）委員長","kind":"質問","question":"のだて委員に申し上げますが、事務事業概要なので先ほどの９０％のところは全体のあれでいいけれども、それを幾らでどうとか細かいことに入るのは、ここでやるべきではないと私は委員長として思っています。それを踏まえて質問してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"つまりは、公契約の労働者が熟練となるのは、何年くらいになるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれご説明、ありがとうございました。併せて、冒頭に委員長から説明があったとおり、特別委員会の関係は特別委員会でやっていただきたいと思いますので、特別委員会ではないところの課長のところで、行政計画だったり各種プランだったり、現在策定して準備しているものがあれば、今年の特徴は何かという質問の中でご説明いただけたらと思いますけれども、いかがでしょうか。","respondent":"藤村企画課長","answer":"そういった計画に基づいて、今年度どういった事業を策定するか、計画を策定するかというのは、どの所管のほうでというのは出てきませんけれども、令和７年度から総合実施計画を始めてまいりまして。","voiceIndex":112,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん総合実施計画の具体化と言えばそれは一言に過ぎてしまうのでしょうが、例えば具体的に今年策定するプランや計画というものがもしあれば、 所管の課長からご説明いただきたいと思います。それとも、今年から１年やって来年もう１年なのか、そこは私の勉強不足で認識していないのですけれども、いずれにしても新しい行政計画や各プランについて、改めてご説明いただけたらと思います。","respondent":"木村人権・ジェンダー平等推進課長、藤村企画課長","answer":"必要に応じて社会や国や都などの政策等に何か新しいことあれば、そちらも含めて検討していくというような会議体になっておりますので、そちらも内容に応じて実施をしてまいります。そういった枠組みの中でどういった事業を進めていくかというところを踏まえて、例えば今年度から障害者の担当部署も組織のほうでつくらせていただいたりというところもありますので、様々個別の計画がありますが。","voiceIndex":114,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろと新しい動きが始まっていることでしょう。ぜひ、それぞれの委員会に、当然ですけれども報告をしていただきたいと思います。年に３回くらいの開催なのでしょうか。この１年間のどこかで、切りのいいところと言いますか、 方向性が見えたところと言いますか、ぜひ総務委員会に報告をしていただきたいと、これは要望で結構です。要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"今説明を受けましたけれども、自治体には、様々な事業が存在していて、それらの事業を今職員の方が推進したり計画したり、また、変更、修正したりして、話し合って区民サービスの向上や庁舎内の事業の効率化に私は取り組んでいると思うのですが、各事業部において今お話しした企画、それから修正、 そして変更等に対して。","respondent":"西澤ＤＸ戦略担当部長","answer":"ただ、利用のほうがまだ使い方が分からないとか、そういった職員も多くいますので、今年はもう少し教育といったところも含めて実施して普及に努めていきたいと思っています。そして、やはり行政の効率化を目指していきたいと考えております。","voiceIndex":119,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"ＣｈａｔＧＰＴはそんなに難しい話ではなくて、チャットのやり取りだけでこちらで文書を出して、 こういうことを疑問に思うのですけれどもこれはどうしたらいいですかと言うと、それなりに返事が返ってきて、でも私が今質問している内容はその回答と違いますと言うと、またそれなりに回答してくれる。これは議論をしても仕方がないので、意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-011"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"もう１つは、先ほどジェンダー平等推進のところで、２年間かけて計画が策定され、また、新しく今後２年かけてつくるということなので、取りあえず策定された計画をどういうものかしっかり見ていきたいのと、今後どういう計画が必要なのか、その方向性についても意見を交わしていけたらと思いますので、この２つを提案したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"毎年行っているので行き過ぎている人は置いておいて、行っていない人を主体に行かれたらどうかと思います。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":137,"id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"これだけやはり大都市が近隣にある。横浜も千葉も群馬も埼玉も茨城もそうですけれども、大変な時期を迎えていると思います。高齢化が進んで、そしてどんどん少なくとも東京には人が集まってくる。そして皆さんで何か意見を出し合って共有できるところは共有して、何かいい試案があったらそこを皆さんで議論して、この品川区にとっても活かしていくという考え方がそろそろ必要ではないかと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":140,"id":"exchange-014"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.08so.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":29,"characters":33788,"voices":141}},{"id":"r08-20260609-21","meetingId":"r08-m06","date":"2026年6月9日","dateIso":"2026-06-09","committee":"子ども若者支援・共生社会推進特別委員会","time":"午後１時00分～午後１時46分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"松本委員","kind":"意見","question":"あまり細かいところには入りたくはないのですが、ただ１個だけ、こども誰でも通園制度が始まったということで、先ほど５７園というお話があったと思います。まだ大半が準備中という状況と思いますが、今後の動向といいますか、どうなっていくのかということをお願いできればと思います。","respondent":"佐藤保育事業担当課長","answer":"今後についてですけれども、職員配置ですとか、あとはシステム等の関連もそうですが、事業者に対する支援を継続して行うことによって、実施していく施設を当然増やしていくことが必要であると認識しています。","voiceIndex":33,"id":"exchange-001"},{"speaker":"せお委員","kind":"質問","question":"これが細かい内容になるのかが分からなくて、今後取り上げるかどうか分からないので、お聞かせいただきたい。２点あって、特別支援保育の巡回相談ですけれども、巡回相談に関連して５歳児健診が始まっていて、ここの関わりは私も前から質問していますが、巡回相談で、今までの目的だったりとか、 やり方、手法だったりとか、そういったことが変化したなどあるのか、まず聞かせてください。","respondent":"佐藤保育事業担当課長","answer":"巡回相談についてのお尋ねですけれども、従来と行っていること自体は変化はなく、まず巡回相談においては、保育園の先生の皆さんに対して、特別支援児に対する対応方法等の研修という意味合いを持って実施をしています。","voiceIndex":36,"id":"exchange-002"},{"speaker":"せお委員","kind":"質問・要望","question":"それと、もう１点だけ、すみません。だから、こういったところを見ると、計画にある城南・浜川は閉園すると言ってきたところとか、そういった方針は、昨年聞いていたら、定数より半分を切ったらとか、いろいろ考えていらっしゃると思うのですけれども、そういったところも現在、どう考えていらっしゃるかお聞かせください。","respondent":"佐藤保育入園調整課長","answer":"これにつきましては、もともと幼稚園の人数の減少等も鑑みながら検討を進めるということで、具体的なこちらの園につきましても、こういった入園の状況がありますので、また今後進めていくそこの時期等も含めまして、引き続き、入園の状況ですとか。","voiceIndex":38,"id":"exchange-003"},{"speaker":"せお委員","kind":"質問・要望","question":"検討は必要だと思うのですけれども、どちらにしても決めていかないと、それは区でしっかり早急に決めていかないと、最初にもある行政経営資源を有効活用する観点からといったところがどんどん薄れていってしまうと昨年から見ていると感じていたので、そこは早急に検討していただきたいと要望して、 終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-004"},{"speaker":"おぎの委員","kind":"質問","question":"私からも１点だけお願いいたします。保育園ですけれども、待機児童は一度ゼロになったと思いますが、令和７年６月より第１子無償化が始まりまして、それ以降の希望申込み等の全体的な流れは今までどんな感じでしょうか。","respondent":"佐藤保育入園調整課長","answer":"保育園の入園申込みの状況ですけれども、４月の入園のお申込みの状況につきましては、昨年と比べまして若干の増があった状況もあります。委員おっしゃっていただいたとおり、そこの要因に関しては、無償化等の部分についても一定の要因になったと認識をしております。","voiceIndex":42,"id":"exchange-005"},{"speaker":"おぎの委員","kind":"意見","question":"無償化とか、そういったことがあると、かなりお母さんたちの意識も変わると思います。大きな流れの変化があった場合は、またこちらでもご報告いただけたらと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-006"},{"speaker":"つる委員","kind":"質問","question":"これは委員長に聞くのですけれども、議運でどうだったか、自分も今、覚えていないのですが、概要説明でひとり親も含めて説明いただいたのですけれども、この委員会の質疑、審査項目の中で、今後ここでそれに関わることになるのですが、ひとり親について取り上げるタイミングはどうなるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-007"},{"speaker":"つる委員","kind":"確認","question":"そうなのですけれども、質疑の機会がある調査項目として、委員会の日程の中であるかないかという確認です。","respondent":"西本委員長","answer":"分かりました。後ほど皆様方にお願いをいたしますけれども、これから項目に関しましてはご要望をいただきまして、そこで正副で調整していきたいと考えています。","voiceIndex":52,"id":"exchange-008"},{"speaker":"つる委員","kind":"確認","question":"分かりました。それで、そのときに確認します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-009"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.09kw.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":14,"characters":13905,"voices":56}},{"id":"r08-20260609-20","meetingId":"r08-m06","date":"2026年6月9日","dateIso":"2026-06-09","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午後１時00分～午後２時00分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"ゆきた副委員長","kind":"意見","question":"副委員長の公明党のゆきた政春です。１年間、どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"これは昨年も同じような資料もいただいたかと思うのですが、その中で、昨年、４月１５日の当委員会の中で、中高生リバースメンター事業についてのご報告を受けたのですが、結論から言えば、区長への政策提言のプレゼンテーションが９月２７日に行われていて、それ以降、そのプレゼンテーションの内容については、 １回、特別委員会の中でご報告があったのですけれども、どういったものを区長に報告して。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"その後、予算審議後の３月下旬、３０日を予定していますが、３月３０日にリバースメンターに向けた事業化報告会、区長からのリバースメンターへの報告会を実施する予定です。","voiceIndex":38,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"提案","question":"分かりました。今、確認をさせていただいて、できれば、この資料にも今のスケジュールを入れていただきたかったなと思いますけれども、繰り返しになってしまいますが、あのときにも申し上げましたけれども、そもそもこの事業自体が、中高生自ら政策提言をして社会を変える実感を持つということが１つの目的になっている。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ＳＤＧｓの推進事業について伺いたいのですけれども、私、このＳＤＧｓの関係する委員会に所属したことがないので、初めて議論するということで、少し基本的なところが分からないところを教えていただきたいと思います。策定委員会とか何かがつくられるのか。誰がどういう形で策定をしていくのかということを教えていただきたい。それが１点です。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"その作成につきましては、ＳＤＧｓ推進本部を経まして、本委員会への報告と内閣府への素案提出を行いまして、１２月から１月にかけてパブリックコメントも実施する予定です。","voiceIndex":41,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"その地域課題、行政課題というのは、まだ、しながわシティラボのところで見きれていないかもしれないのですけれども、各所管から出していただいたものが課題ということで、行政とか地域の課題が各所管から出されたものというふうなことで、それは本部としても、それが課題だよねとなったということで、例えば、こういうＳＤＧｓ未来都市計画をつくるに当たって。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"１点目の計画策定で、推進本部のほうでやるのかというご質問なのですが、こちらにつきましては、中心はＳＤＧｓ推進本部、区長を本部長とした推進本部で……。","voiceIndex":43,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほど、計画改定案はパブリックコメントもされるということでご説明いただいたのですけれども、パブリックコメントをするに当たっての住民説明会とかも、この間、厚生委員会の中でもその問題が出たのですけれども、障害者だったりとか、介護だったりとかの計画が今年策定の年で、それぞれ説明会がされるということになって、すごくよかったなと思っているのですけれども。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"もう１点、パブリックコメントを実施する際の住民説明会の実施ですが、こちらにつきましては、現在、検討中ではありますが、現段階といたしましては、映像でのオンラインでの説明を、動画を流す設定です。そちらにつきましては、引き続き検討させていただければと思っております。","voiceIndex":47,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問","question":"もう１つ伺いたかったのが、次のページのところで、環境と熱中症のところで専門部会がつくられているのですけれども、この専門部会の環境と熱中症だけかというか、どういう選び方でこういうふうなテーマでなったのか、この専門部会は、どういう形で実際に活動が、されているのか、メンバーも含めて教えていただけたらと思います。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"こちらは年４回程度実施されまして、３回検討会を行って、４回目でまとめというか、そこの考え方でまとめを行うような形でスケジュールを考えてまいります。","voiceIndex":49,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"すみません、あともう１つ、公有地のところで伺いたいのですけれども、２番の東品川清掃作業所のところのスケジュールを教えていただきたいのです。跡地の活用というところで、地域から、ぜひ公園にしてほしいということは議会でも取り上げてきたところなのですけれども、そこら辺のスケジュール、いつ頃、どういうふうに決まっていくのかというスケジュールも含めてお聞かせいただけたらと思います。","respondent":"井添政策推進担当課長","answer":"東品川清掃作業所のところと関連して、中延四丁目の中野中継所の案件ですので、私のほうから回答します。こちらは公有地の資料の２番目の旧品川清掃作業所のことではなくて、恐らく北品川の……。","voiceIndex":51,"id":"exchange-008"},{"speaker":"山本委員","kind":"質問・要望","question":"あくつ委員とともに、昨年に続き出席します。よろしくお願いします。それぞれの調査事項においては、特定事件調査の機会にお伺いして意見を申し上げたいと思っておりますけれども、この機会に１点、財政計画に関してお聞きしたいと考えています。足元では人口増による増収基調があり、様々積極的に新規施策にて財源を使っておりますが、財源は限られているところです。","respondent":"加島財政課長","answer":"区におきましても、長期計画をはじめ総合実施計画、公共施設等総合計画、様々存在しております計画の中でこれらを踏まえまして公表に耐え得る枠組みは、現在、整理をしているところでございます。","voiceIndex":58,"id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"アジャイルという言葉が、 昨年度ですか、よく行政の進め方でもお使いになられたと思いますので、つくりながら、状況の変化に応じて柔軟に変えていくという姿勢も必要かなと思いますので、そういうことも踏まえて、ご検討を前に進めていただきたいと思います。今年度の特定事件調査で扱われるときには、何らかの進捗やアウトプットがなされることを要望し、 期待し、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-010"},{"speaker":"まつざわ委員","kind":"質問","question":"そういった中で、例えば、今、４つぐらい出ていますけれども、例えば、旧荏原第四中学校がああいう形であったときに、図書館の在り方があるわけではないですか。ゆたか図書館もなくなっていきますというと、そうすると、では、二葉の図書館はどうだとか、要は、点ではなくて、もっと面でこうやって考えていくような考え方が私はすごく必要かなと思っています。","respondent":"中川公有地活用担当課長","answer":"今、委員からご提案ありました、まず、点でなくエリアで、エリアだったり、周辺公共施設で考えていく、大変重要なお話です。エリアで考える必要は確かにあるかと思います。その中で所管とも協議しながら総合的な検討を進めてまいりたいと考えています。","voiceIndex":61,"id":"exchange-011"},{"speaker":"まつざわ委員","kind":"意見","question":"そうですね、総合的に検討して、ぜひこの委員会でも何かそういったことを、これから会議の中であると思うのですけれども、その課題の１つにしていただければいいかなと思っています。意見でございます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-012"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"参考にさせていただいたような、また今回も、もしよろしければ、こういったところを視察したらどうですかというようなご提案をさせていただきたいと思いますし、できるだけ早くから先方の自治体と調整をしていただいて、できるだけ受け入れていただけるような形でお願いしたいと思っています。お願いです。この場でよかったですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-013"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.09sd.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":18,"characters":19475,"voices":70}},{"id":"r08-20260610-22","meetingId":"r08-m06","date":"2026年6月10日","dateIso":"2026-06-10","committee":"まちづくり・公共交通推進特別委員会","time":"午後１時00分～午後２時36分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"石田（秀）副委員長","kind":"意見","question":"昨年に引き続いて副委員長を拝命いたしました、自民党・無所属の会、石田秀男です。どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"「新庁舎および大井町駅周辺地区に関すること」のところで、今、新庁舎建設が進められていると思うのですけれども、ホルムズ海峡封鎖によっての影響、資材不足や高騰の影響がないのかどうか伺いたいのと、現庁舎解体基礎調査に４月から着手するということですけれども、これはどのような調査をするのかを伺いたいと思います。","respondent":"小林新庁舎建設担当課長、泉広町事業調整担当課長","answer":"ただ、やはりこのような状況が今後も続くという話になりますと、当然、新庁舎の工事にも影響が出てくるかと思ってございまして、当然、動向は注視していますが、そのようなことになった場合につきましては。こちらは今回、解体調査ということで、まず現状、現庁舎の既往の資料にどういったものがあるのかといった調べを進めるとか、また今回、前面道路、補助１６３号線との近接が予想されてございますので、そういった近接性を踏まえた上での。","voiceIndex":41,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったバス事業者への、やはり運転士の確保や育成への支援をぜひやっていただきたいと思うのですが、家賃助成や運転士採用強化支援などの実施を今考えていらっしゃるのかどうか、伺いたいと思います。トラックスは経由して、元の終点に戻してほしいという声が寄せられましたので、どうにかできないかと思うのですが、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"基本的にバス事業者は様々な区で運行しておりますので、区単独での支援がなかなか難しいという状況ではありますが、東京都で今、総合的なバス事業者支援のパッケージを予算化もしくは計画として検討していますので、そちらを踏まえた上で考えていきたいと考えています。","voiceIndex":44,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした状況の中で、やはり区営住宅というのが１つ、重要になってくるのかなと思いますので、建て替え時には増設したりといったことも、ぜひ検討していっていただきたいと思うのですが、やはり今の状況でいくと、民間任せではもう立ち行かないというところまで来ているのではないかと思いますが、 いかがでしょうか。","respondent":"川原住宅課長","answer":"委員がおっしゃるとおり、区営住宅ならびに都営住宅の適切な維持管理というところは、引き続き、 続けていくところで、さらに建て替えといったところは、その年数が来たら当然、検討が必要だと認識しています。","voiceIndex":46,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろおっしゃいましたけれども、やはり今、低所得者の方の物件がないということなのです。長年住み続けてきた人も出ていかなくてはいけないという状況になっておりますので、そういったところでしっかり支援していっていただきたいと思いますし、今、セーフティネットの話もありましたけれども、実際、区内には専用住宅は２戸しかない。これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"個別の質疑は今後の委員会の中でしてくださいという委員長のご指示に従いまして、総論的なところで１点だけ確認したいのですが、自転車の関係なのですけれども、青切符制度が始まったということですが、これまで自転車の交通安全等々に対しても、ここの表記もそうなのですが、「交通ルール」や 「マナー」など、少し緩い表現で書かれているのですけれども、やはりマナーというのも要は法律違反ということで。","respondent":"原交通安全担当課長","answer":"青切符制度の周知・啓発の中にありましても、まず警視庁のスタンスといたしましては、まず指導・警告を優先して、その後に青切符での反則告知をするという大きな方針がございまして、かつその中で危険性の高いものに関しては、即時。","voiceIndex":50,"id":"exchange-006"},{"speaker":"田中委員","kind":"意見","question":"マナーというのは、例えば食事をするときのマナーなど、社会人としてあるべきルールに基づくことが、評価に値するといいますか。違反したら青切符制度もあって、厳しく罰せられます」と言うことのほうが、交通安全の実効性が高まるのではないかと考えていますので、そういった視点も踏まえて今後の安全対策に臨んでいただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"全部行きますけれども、地域公共交通のほうでは、東京都が地域公共交通の基本方針の見直しを今年度やるというところで、結構その中で２３区というか、基礎自治体に対していろいろなタスクみたいなことが盛り込まれてくるように、中間報告の中を見ると言われているので、それを受けて品川区としての令和２年に策定した地域公共交通の基本方針が、どのようなスケジュール感で、一応。","respondent":"三井新庁舎整備課長、櫻木地域交通政策課長、川原住宅課長","answer":"なので、新庁舎に向けて、そういった窓口を整備していますというのは、こちらで目指しているところになるのですが、現実問題。いわゆる地域公共交通計画や方針などの前倒しでの見直し等のお尋ねですが、ご指摘いただいているとおり。除却された空き家の件数も、前年度比１０件増となっているのと、あとは財産管理人制度で、最終的に土地建物を売買するという流れになったときに。","voiceIndex":54,"id":"exchange-008"}]},{"id":"topic-03","title":"子育て世帯への住まいの支援","agenda":"子育て世帯への住まいの支援","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これは、引っ越し費用と仲介手数料、登記費用か礼金ということで、それぞれの相場が幾らぐらいなのかを伺いたいと思います。これを利用する際に、地域住民との調和を図ることということで出ておりますが、いろいろな中から選んで「これをやる」という感じになるのか、町会加入は義務だ、防災訓練に参加することが義務になるなどということがあるのかどうかを伺いたいと思います。","respondent":"川原住宅課長","answer":"特に賃貸物件については、もう礼金がもともとないものがあったり、今回、敷金は、戻ってくることも考えて対象経費から外してはいるのですけれども、仲介手数料は、物件の家賃金額の約１か月分というところが相当なのかなと考えております。","voiceIndex":62,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこを確認させていただきたいのと、毎日問合せがあるということで、反響があるということでよかったとは思うのですけれども、実際、ファミリー世帯が、仲介手数料１か月分、転居費、引っ越し代でいくと最低でも１０万円ぐらい、１０万円以上かかるのではないかと思うのですけれども、そうすると家賃も、 ファミリーですから１５万円とか、品川区は今、上がっていますので。","respondent":"川原住宅課長","answer":"１点目にご質問いただいたことについてお答えします。","voiceIndex":64,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"何点かお伺いしたいのですが、まず子育てファミリー世帯転居費用の助成についてですが、ここに、 いわゆる明確な目的というのが記載されていないのですけれども、まず対象となる方は、品川区内に ２年以上住んでいる方が対象であって、１８歳以下の子どもを養育されている。それで、区内で転居しないと、この対象にならないのですけれども、なぜ転居しないといけないのか。","respondent":"川原住宅課長","answer":"横型の資料には書き切れずに入れていないのですけれども、Ａ４縦の資料の「子育て世帯への住まいの支援について」というところでは、何行か背景と目的といったところを記載させていただいておりまして、区の人口推移を見たときに、子育て世帯だと思われる。","voiceIndex":66,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"併せて、２つ目のアキヤテラスの関係でいうと、一方でまちづくり、防災木密対策など、いろいろな意味で災害に強いまちづくりを進めていく上では、旧耐震の建物も可能にするということと、新しい、 要は木密対策や災害対策という、災害に強いまちづくりという視点でいうと少し逆行するようなことも考えられるのですが、何ゆえ旧耐震もオーケーにしたのかというのを、もう一回、改めてお伺いしたいのと、今回。","respondent":"川原住宅課長","answer":"そして２点目は、単年度なのか、来年度の予算状況といったところですが、まずはこれは初年度で新規事業といったところで、７月１日予定で始めて、どのくらい反応等、区民の方からの反響、 意見が頂けるかといったところも加味させていただきたいと思いまして。","voiceIndex":68,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"同時に、一石何鳥なのか分かりませんけれども、ここでは「子育て」とついていますけれども、区民の方々のいわゆる住まいの問題も、いよいよ品川区は本格的に空き家バンクを立ち上げて前に進めていくというところを、やっぱりぜひ進めていただきたいというのが、私どもの考え方、これまでの質疑・一般質問等も含めて感じていただいていると思うので、ぜひこれをしっかりリンクさせる。","respondent":"川原住宅課長","answer":"今後も引き続き、子育て世帯への住まいの支援というところは、どういった形で区民の方によりよく使っていただけるかというのを、引き続き検討してまいりたいと考えています。","voiceIndex":71,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"前後してしまったのですけれども、最初の空き家バンク事業開始式と、先ほど内容についての説明があったかどうか。もしあったら、聞き漏らしたので、どういう開始式か、日時、場所、内容などを確認させていただきたいのが１つ。","respondent":"川原住宅課長","answer":"先ほどは日付のみを申し上げておりましたので、改めて詳細を申し上げしますと、こちらは意味合いとしましては、７月１０日にバンクが開始される、その前の事前のプレスリリースのような目的、 役割を果たしたいと考えてございまして、今のところ、午後２時から３時までの予定で。","voiceIndex":73,"id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"でも、区民がどう受け取るかというのもあるので、また発信の力も、それは当然、組織ですので、違うと思いますので、その辺は、ぜひ今からでも考慮できるのであれば、検討していただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-015"},{"speaker":"塚本委員","kind":"確認","question":"子育て世帯の転居費用のところで、これまでの質疑で、要件として町会加入や防災訓練といったところがあって、一応これは最初のご説明で、上限件数に達した段階でもう締め切りますということなので、 原則、申請順、申請の早いもの順なのだろうと思うのですけれども、例えば５年住む予定などというのは、実際、どこまで担保するというか、なかなか実際問題、５年後どうだったのですかというところまで。","respondent":"川原住宅課長","answer":"２点目は、電子申請のほかに窓口も行う形です。住宅課の窓口になります。ただ、７月１日から開始予定ですので、当然、電子申請のオープンの時間も、窓口の開始時間にも合わせたいと考えています。","voiceIndex":77,"id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"公共交通では、今本当に減ってきてしまっているので、利便性を向上していきたいというところで、そういう姿勢でやっていきたいと思うのですけれども、バス事業者への支援がどういうことができるのかということで、他区での支援状況といったところの資料があると、議論が深まるのかなと思いますので、要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"庁舎跡地活用で、今年度、品川区庁舎跡地活用プラン策定委員会というのが資料にも出ていますけれども、区議会議員もそこには入ってということ、あと学識経験者が５人ぐらいいましたか、その委員会があって、そちらはいろいろな議論や策定などを進めていくのと、そこでの議論等は、この委員会でも当然、報告事項としてされていくのだろうと思うのですが、そこで、「もっとこうしたほうがいい」。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-018"},{"speaker":"塚本委員","kind":"意見","question":"そうですね。その辺がどういうふうに受け止められているのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-019"},{"speaker":"若林委員","kind":"質問","question":"今、説明を聞いて、本当にボリュームが、前期もそうですが今期も、まちづくり・公共交通推進特別委員会は非常にボリュームがあるということで、資料も含めて、また事務局を通じて提出するというやり方ですか。","respondent":"石田（ち）委員長","answer":"今言いましたように、６月１７日水曜日までに、具体的調査内容がございましたら、事務局へ書面にてご提出いただきたいと思います。ただいま頂きました意見と併せて、正副委員長で十分調整させていただいて、可能な限り、今後の委員会運営に活かしてまいりたいと考えています。","voiceIndex":91,"id":"exchange-020"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.10ma.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":25,"characters":30999,"voices":93}},{"id":"r08-20260612-10","meetingId":"r08-m06","date":"2026年6月12日","dateIso":"2026-06-12","committee":"議会運営委員会","time":"午後１時00分～午後１時17分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２番目の報告のところで、一般質問の原稿のところなのですが、締切りが決まっているので、それは原則そのようなことで理解はするのですけれども、やはり私たちとしても、かなり最後の最後まで原稿を推敲するという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-001","title":"一般質問原稿の差し替え"},{"speaker":"西本委員","kind":"質問","question":"議員研修の亀井会長のほうは所要１時間という形でよろしいのですか。","respondent":"渡辺議長","answer":"１時間です。","voiceIndex":16,"id":"exchange-002","title":"議員研修会の内容と所要時間"},{"speaker":"西本委員","kind":"意見","question":"できれば、大井町トラックスの件については、この間、高輪ゲートウェイシティとか、いろいろ東日本のＪＲのほうでまちづくりという形で何かやっていると思うのですが、そこの全体像というか、それをおさらいも含めてやってもらいたいと。","respondent":"渡辺議長","answer":"テーマ的には品川圏という感じですかね。","voiceIndex":18,"id":"exchange-003","title":"議員研修会の内容"},{"speaker":"西本委員","kind":"意見","question":"かなり違いを鮮明に出していると思うのです。その中での大井町という特徴というのを少しクローズアップしていただくことによって、さらに品川区のよさというものを踏まえた上で議論ができるとありがたいと思っているので、そこも含めて全体の流れもぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-004"},{"speaker":"西村委員","kind":"質問・要望","question":"議員バッジの仕様の変更についてなのですけれども、経費負担の軽減等のために、議員バッジの仕様の変更についてと。現在、予備分としているレプリカの金メッキを検討するといったようなお話があったかと思うのですけれども、これ、ぜひ進めていただいて、検討していただきたいと思うのですが、その辺はいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-005","title":"議員バッジの価格"},{"speaker":"西本委員","kind":"質問","question":"すみません。内容を少し教えていただいてもよろしいですか。経緯というのを教えていただいて。すみません、意味が分からなくて。","respondent":"渡辺議長","answer":"それに対して見直しを検討している。全国的に、県議会も含めて、県議会だ、市町村の議会だという記事がありました。そういう中で、個々にどういうお話をされたか分からないですが、議長会では、ちなみに紹介すると、 各区で見直しを検討しようという機運が高まっていました。","voiceIndex":32,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"現状を教えてほしいのですが、改選期の後、議員バッジを頂くことになると思うのです。そのときは純金という形……。そのことを言っています。その後、例えば、なくなったりとか、壊れてしまったとかという場合は、注文される方によるとは思うのですけれども、合金を頼まれる方もいらっしゃると思うしという、いろいろ選択肢があって、ただ、今のお話はどこの時点の話をされているのかと。","respondent":"渡辺議長","answer":"ここはコストを抑えるべきだと。今、西本委員おっしゃられるように、個々の実費弁償は自由でいいと思うと、今お話を聞いていて感じています。ですから、一番は私たちがすべきことは、改選の後、議会費で購入するものはなるべく価格を抑えるスタイルがいいのかという捉え方です。","voiceIndex":34,"id":"exchange-007","title":"議員バッジの仕様見直し"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.12gu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":8,"characters":5875,"voices":41}},{"id":"r08-20260624-10","meetingId":"r08-m0708","date":"2026年6月24日","dateIso":"2026-06-24","committee":"議会運営委員会","time":"午前10時30分～午前11時00分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"令和８年第２回定例会","agenda":"令和８年第２回定例会","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"請願・陳情の件なのですけれども、陳情第２７号の付託先の委員会は総務委員会ということですけれども、介護制度の中身に踏み込んだ審査も必要なこともあるかと思いますので、介護制度の担当課の理事者の出席を求めるなど、運営上の配慮が必要なのではないかと思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"区民と議会の交流会議からの報告事項","agenda":"区民と議会の交流会議からの報告事項","exchanges":[{"speaker":"こんの副委員長","kind":"質問・要望","question":"実施後のアンケート結果から、生徒の政治や社会への関心の高まりなど、一定の効果が確認された。学校でも、校長先生からも、また生徒からも大変高い評価をいただきまして、次どうぞ、やりたい学校をというふうに校長会等でお声をかけさせていただいたところ、今回は、戸越台中学校が手を挙げてくださいまして、８年生３クラス、約９０人の生徒と意見交換を行わせていただきます。２番目です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-002"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"しながわ子ども議会なのですけれども、予算にもあったということもありますけれども、改めて、このイベントの参加者数の目標とか、目的とか、あと、開催に至るまでの経緯を簡単に改めて教えていただきたいということと、それと、小学校３・４年生ということなので、あまり長時間は難しい面はあるとは思うのですが、全体１時間で、メインの質疑応答が３０分ということで、４０組の方が来るということなので。","respondent":"渡辺議長","answer":"時間については、これまでやはり前年までの学校単位で行ってきた実績をベースとして設定したところですが、今やはり安藤委員の指摘で、若干の幅は持たせたいと、今のご質疑も踏まえて検討していきたいと思います。","voiceIndex":23,"id":"exchange-003"},{"speaker":"つる委員","kind":"質問","question":"今のしながわ子ども議会ですけれども、渡辺議長のほうから、広報に関して、区議会だより、それから広報しながわとあったのですけれども、区議会だよりは、多分、８月末になるので、恐らく広報しながわによるのかなと思います。今年度から月２回になって、１日号と１５日号。編集関係でいろいろその辺、教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-004"},{"speaker":"つる委員","kind":"質問","question":"チラシなどを作るのかということも併せて教えてください。","respondent":"大澤区議会事務局長","answer":"広報しながわは、７月１日号に囲み記事で載ります。区議会だよりのほうは、臨時会号が明日から配布になるので、裏面に案内が入ります。","voiceIndex":27,"id":"exchange-005"},{"speaker":"つる委員","kind":"意見","question":"大変良い取組だと思うので、確実に児童に届く、ないしは保護者に届くようにというのは、教育委員会や学校現場に協力いただいて、チラシベースでも、データで送って、配布を依頼するなどがいいのかなと思いました。この間、行政側の子ども関係の議会は、しっかりしたチラシで保護者の手元に届いてきているので、 ぜひ議会側の取組としても、確実に届くように、お願いをぜひしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-006"},{"speaker":"田中委員","kind":"確認","question":"そういう中で、先ほどの渡辺議長のお話、増村先生のお話を踏まえてということなのですが、そこは我々の思いも踏まえて対応してもいいということなのかどうか、確認だけ。","respondent":"渡辺議長","answer":"それと同時に、説明がすごく上手だったので、どちら寄りということも、その都度、指摘しながら、要は、議会側を守る立場の発言も多々あったかと思います。やはりここまで徹底しないと、危機管理上、必要ですよというところは響いたかと思います。","voiceIndex":30,"id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"今後、これから私も議会改革推進会議の政務活動費あり方検討会の一員なので、それぞれの立場でのお考えもあって、リスク管理ということは、やはり非常に大事だなということは、私としては感じるところですので、今後、増村さんにいろいろなご意見を、都度、伺うようなことは、議長の立場で、いいとか悪いとか言えるのかどうか分からないですけれども、可能なのですか。","respondent":"渡辺議長","answer":"当然ながら、今、立ち位置が議会アドバイザーということで正式に依頼をしているので、やはりそういう場が増えることが一番有意義だと考えています。手続上は、また経費のこともありますが、事務局とともに前向きに捉えていきたいと考えています。","voiceIndex":33,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"すみません。多分、答えを求めてしまう場合もあるのですよね。なので、もう少し広がりのある議論にしていくために、別の方に講義していただく機会を、ぜひお願いしたいなと思います。これは予算の関係もあるので、ほかの弁護士はどうですかというのは難しいかと思いますけれども、 ぜひそういうことも検討に入れていただきたいと思います。","respondent":"渡辺議長","answer":"１つだけ誤解のないように。第一歩というところで、増村先生お一人ということはまずないと、 フラットに考えていきたい。ただ、議会アドバイザーにご就任いただいている方だったので、そういう意味がまず１つあります。","voiceIndex":35,"id":"exchange-009"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.24gu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":11,"characters":10102,"voices":43}},{"id":"r08-20260629-6","meetingId":"r08-m0708","date":"2026年6月29日","dateIso":"2026-06-29","committee":"区民委員会","time":"午前10時00分～午前11時54分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"令和８年陳情第２２号、自衛官募集事務に係る個人情報提供","agenda":"令和８年陳情第２２号、自衛官募集事務に係る個人情報提供","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。私、住民基本台帳の閲覧を経験したことがありませんので、少し一般論として、このやり方についてお聞きしたいと思います。区民の方がこの閲覧をしたいと思った場合には、どのような手続で、そして、この閲覧がどのような形でできるのか、教えていただきたいと思います。","respondent":"築山戸籍住民課長","answer":"閲覧についてですが、まず、１点は、方法として、国や地方公共団体の場合につきましては、法に基づいて必要な場合に閲覧ができるというものがあります。","voiceIndex":6,"id":"exchange-001"},{"speaker":"大倉委員","kind":"質問・要望","question":"情報提供がされるという、自衛隊法でのっとって実施する際に、事前通知ということがセットになっているというお話であったと思いますので、この陳情の要旨にある１についても、そもそも今、自衛隊法に基づく提供についてはしていないで、住民基本台帳法による閲覧の許可ということなので、そもそも前提が違うというところでは、まず１番もそうですし、２番のところもやっていないということ、また。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-002"},{"speaker":"まつざわ委員","kind":"意見","question":"結論を出すで、不採択です。お話のとおり、課長がおっしゃったとおり、陳情の要旨の１、２、３もそうですけれども、そもそもの前提で、住民基本台帳の提出を品川区は行っていないということですので、不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-003"},{"speaker":"せらく委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。ご説明もいただきました。個人情報の取扱いに対しては関心が高まっている中だと思いますので、陳情者の思いというものは伝わっておりますが、自衛隊の通知文についても、個人情報提供を品川区は行っていないという説明と、あと、除外申請もそのため制度がないということでしたので、今回、こちらの陳情については不採択という判断をいたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-004"},{"speaker":"横山委員","kind":"質問","question":"本日結論を出すで、先ほどの前提に関するご説明と議論を踏まえまして、不採択でお願いします。もしお子さんご本人ですとか保護者の方からのお問合せがあった際には、丁寧なご対応をお願いいたします。今後も、住民基本台帳法の事務として、適切な取扱いをお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"}]},{"id":"topic-02","title":"令和８年度防犯支援事業","agenda":"令和８年度防犯支援事業","exchanges":[{"speaker":"まつざわ委員","kind":"質問","question":"防犯カメラの町会の助成、これは本当にありがたいと思っていて、２４分の ２３、本当にぜひ継続していってほしいと思っています。この防犯カメラですけれども、最近、大きな事件があって、被害者が刺されて殺されてしまって、犯人が捕まったという。地域は忘れてしまったのですけれども、最近もあったのですが、あれで私がすごく気になるのが、下見というのが非常に出てくるではないですか。","respondent":"澤邉生活安全担当課長","answer":"しかしながら、なかなか広い地域ですので、警察単独ではそこのところを把握することはできないと考えています。","voiceIndex":23,"id":"exchange-006"},{"speaker":"まつざわ委員","kind":"質問","question":"そうですね。やはり難しいというのは私も認識しているのです。不審者というのは、別に犯罪するだけではなくて、下見もするわけですから、 例えば、そういったときに消防団を活用してパトロールしてもらうとか、何かあったときに防犯協会にパトロールしてもらうとか、それにはやはり地域と消防と警察と一緒に一体化できる、そういった共有のプラットフォームが絶対必要だと思っているのです。","respondent":"澤邉生活安全担当課長","answer":"警察としましては、そういったいろいろなチャネル、こういったものを活用して、いろいろな地域、 いろいろな階層の方々が情報を入手して、それを犯罪の抑止ということに役立てていきたいと考えております。","voiceIndex":25,"id":"exchange-007"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"例えば、３万円が出せないから大変だから、そういうのはできるのかは別に置いておいて、初めから補助額を割り引いた金額をこちらが出すような、そういった形にしていくほうが、契約している団体ならばそういうのができるのでしょうけれども、そういうのがないから難しいのかもしれないのですが、そういったお金の配慮というのもあっていいのかと思うのですけれども、いかがでしょうか。","respondent":"澤邉生活安全担当課長","answer":"これは住宅課のほうですけれども、そうしたところですと、上限が２０万円ということになっておりますので、そうしたところをうまく使っていただくと、いわゆるカメラ的なものはこちら。","voiceIndex":27,"id":"exchange-008"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"窓口案内というのは、すみません、知りませんでした。大変すばらしいと思うので、ぜひやっていただきたいと思います。私が少し聞いた話だと、防犯カメラも、東京都が来年はやらなそうな感じをしているので、またこれでお金が減ってしまうと思うので、ぜひ品川区はやめずに継続していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。少し確認をします。それと、住まいの防犯対策助成につきましては、今、まつざわ委員のやり取りの中で、東京都の予算を活用してということが確認できました。東京都がたしか３年計画でこの予算をつけていたかと思います。今も要望がありましたとおり、今後の品川区の考え方を少し教えていただきたいと思います。都の予算が終わった後の品川区の考え方を教えてください。","respondent":"澤邉生活安全担当課長","answer":"来年度、都の方針についてはまだ確定はしておりませんが、区としては、その方向性については注視してまいりたいと思います。２点目です。","voiceIndex":30,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問","question":"最近もある方が、実は詐欺に遭ってしまったのだというお話を伺ったのですが、その方も本当にしっかりしている方で、自ら詐欺に気をつけようと言っているようなお立場の方が、自分が詐欺に遭ってしまったというお話を伺って、こちらの考えの上を行く詐欺の手口が巧妙になってきているというのは、本当にひどいと思うのですが、常にそういう様々なところでの意識啓発の声かけが大事だと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-011"},{"speaker":"せらく委員","kind":"質問","question":"防犯対策ミラーについてお聞きしていきたいと思うのですが、区として６００枚購入するというご説明があったと思います。被害の多発場所へ設置予定とのことですが、お話、ご説明を聞いていると、屋内が多いのかということで思っているのですが、もう少し具体的に屋内の、例えば公共施設内なのか、 それとも、民間の施設にも貼っていくのかというところもお聞かせいただければと思います。","respondent":"澤邉生活安全担当課長","answer":"区としましては、そういった、この夏が始まる前にぜひとも警察と連携して、女子学校の通学路を中心とした、通学路、駅、それから歩道橋だとかがあるのですけれども、そういったところの設置を急いで対策を取ってまいりたいと考えております。","voiceIndex":33,"id":"exchange-012"},{"speaker":"横山委員","kind":"確認","question":"私からも、シールミラーの設置場所について詳しくお聞きしたかったのですけれども、こちらの １００枚、盗撮を防止するためのミラーについては、せらく委員の質疑でご説明があったと思うのですけれども、１,０００枚のほう、ブルーの色のミラーについては、エレベーターであったり、エントランスというところの共連れの対策というところだと思うのですが。","respondent":"澤邉生活安全担当課長","answer":"今、ご質問いただきました、いわゆる共連れ事案対策のシールミラー、こちらについてですけれども、委員ご指摘のとおり、オートロックのエントランスやエレベーター、こういったところに設置というのを検討しております。","voiceIndex":36,"id":"exchange-013"},{"speaker":"横山委員","kind":"確認","question":"確認だけなのですけれども、住まいの防犯対策助成のほう、こちら、補助の上限額が昨年は ４万円だったと思います。１,２８３件だったと思うのですけれども、今年に関しては何件ぐらいを想定されているのでしょうか。３万円という補助上限に変わったので、その分、多くの方にご利用いただきたいという意図があるのか、どういった形で分析がされているのか、確認させてください。","respondent":"澤邉生活安全担当課長","answer":"昨年度は１,６００件を予算として計上しています。これまでも、２年目となりますけれども、非常に反応が、反響が大きくて、申請も多く受け付けているところです。今後ともこの制度、非常に補助率も高いので、区民の皆様に引き続き周知してまいりたいと思っています。","voiceIndex":38,"id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"いろいろご説明いただいたので、少しだけ確認を。両方やるほうがいいかと思いますけれども、そういった今まで実施してきた防災課の事業とかもうまく連携して、情報を使ってやっていくほうが、より周知と設置が進むのではないかと思いますので、その辺について教えていただければと思います。","respondent":"澤邉生活安全担当課長","answer":"３点目の周知方法ですけれども、確かにおっしゃるとおりでございまして、防犯協力団体に対しての広報、周知というのは当然ですけれども、区としましては、一般の区民の方、 来庁される方でもお気軽に生活安全担当を呼んでいただいて、設置必要な場所であれば。","voiceIndex":40,"id":"exchange-015"},{"speaker":"大倉委員","kind":"意見","question":"分かりました。女子学校のほうでも既に設置されていて、効果があるということなので、今、共連れ対策のほうなどもなかなかどうやって効果を計っていくのかというのが少し気になったところであったので、当然、通報の数が激減しましたとかとなるのかとも思ったのですが、まずは買ってみて、安心して利用できるというところも大事かと思いましたので、ぜひ進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-016"},{"speaker":"まつざわ委員","kind":"質問","question":"賃貸は賃貸でも、そのマンションのパッケージで、防犯パッケージみたいな感じでオーナーに、これだけ安くするからどうですかとか、例えば、個人で進まない場合は、そういった賃貸に関してはハードルを下げて、マンション自体のパッケージで売り込むというのか、申請させるというのですかね。何かそういったこともやってもいいのかと思うのですけれども、それを教えてください。","respondent":"澤邉生活安全担当課長","answer":"区としましては、ベストプラクティスといいますか、そういった成功事例についても、併せてこの事業について周知してまいりたいと思います。","voiceIndex":43,"id":"exchange-017"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"本当にいい、本当にすばらしい助成金だと思うので、ぜひ知らせて、また拡充して、みんなで使っていただきたいと思います。最後、多分、自動通話録音機というのは、自分で欲しい人が窓口に行って申請するのですよね。それだけ教えてください。","respondent":"澤邉生活安全担当課長","answer":"そういったことで、品川区としては、 ４警察署の防犯係にそれぞれ台数を置かせていただいていますので、区役所が遠いという方は、各警察署に来署をしていただくような形で周知をしています。","voiceIndex":45,"id":"exchange-018"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"だからこそそうやって、なかなか申請に行くというのは、ハードルがあったり、 情報がそもそも届かないと行けないではないですか。そうすると、携帯電話にかかってくるのです。そういったときに、そういった録音のやり方であったりとか、 携帯電話の対応の仕方、そういったのも並行してやっていく必要があるのではないかと思うのですけれども、そこら辺はいかがでしょうか。","respondent":"澤邉生活安全担当課長","answer":"一部警察署によりますと、高齢者の方がこれを設置ができないといったときに、事件等々の間に時間がある場合については、ご自宅まで行って設置をするということもやっていると聞いております。","voiceIndex":47,"id":"exchange-019"}]},{"id":"topic-03","title":"スポーツ×エンタメ 多彩カイギの実施","agenda":"スポーツ×エンタメ 多彩カイギの実施","exchanges":[{"speaker":"まつざわ委員","kind":"質問・要望","question":"そうすると、今年、スタートアップというので、所管の課長もいらっしゃるので、例えば、そういったスタートアップの事業の方もこういうのに巻き込んでいって、だから、そういった会議体で新しい、 化学反応ではないですけれども、そういう融合させて新しいものを生み出す手法というのはすごく大事だと思うので、ぜひスタートアップのそういったものと一緒にやっていくみたいな。","respondent":"大森文化観光戦略課長","answer":"スタートアップ事業のほう、まず、１回目ということで、我々からお声がけさせていただいた数でいうと、１４団体ぐらいの方々ということで、その辺りの方々は思い浮かぶ方になってしまうかというところで、合致してしまうところはあると思うのですけれども。","voiceIndex":55,"id":"exchange-020"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。今も質疑がありましたが、もう少しイメージを膨らませたいと思っていまして、もし差し支えなければ、この１４団体の団体名をご紹介いただきたいというところと、あと、年に２回これを開催して、どういう形に持っていくのか。何かイベントを開催することが目的になっていくのか、区民の方がどのようにここに関わっていけるのか、少し教えていただければと思います。","respondent":"大森文化観光戦略課長","answer":"そういったところに関しましては、スポーツは難しいかもしれないのですけれども、新庁舎とか、あとは競馬場のアリーナ構想とか、そういったものが数年後に控えておりますので、そういったところで、 区が旗振りをしていくのではなくて、地域の方々のほうからつながりを持って。","voiceIndex":57,"id":"exchange-021"},{"speaker":"新妻委員","kind":"質問・要望","question":"ボトムアップで、団体の方とか、そういう声が上がってきたものを、こういう形でやりたいという意見をぜひまた集約をしていただきたいと思いますし、東京都競馬のアリーナも構想があるということなので、まだ少し先の話だと思いますけれども、あそこができた暁には、すごく大きなそこが集客の場にもなるのだろうとも思っていますので、そこもぜひ活用していただくような。","respondent":"大森文化観光戦略課長","answer":"なので、今回はインクルーシブスポーツという分野の代表ということでお声がけをさせていただいているところでございます。","voiceIndex":59,"id":"exchange-022"},{"speaker":"大倉委員","kind":"確認","question":"そこが確認できればと思うのと、聞いていると、やはり既に大きなことをやっている団体が多い、イベントをやっているところが多いので、それなりに多分アイデアもたくさんあって、進んでいくことはあるのだろうと思う反面、先ほども少し委員のほうからあった、スタートアップとか、いろいろなさらにＤＸとか、そういうＩＴとかも含めた発想を持っているところもいるので。","respondent":"大森文化観光戦略課長","answer":"今のお話でいきますと、今回、１４団体の方にお声がけしたのが、私のほうでピックアップさせていただいた１４団体なのです。","voiceIndex":61,"id":"exchange-023"},{"speaker":"大倉委員","kind":"意見","question":"課長がいろいろなところへ行って、いろいろなイベントを見て、直接関わりながらやられているのはすごく認識しているので、それはそういう団体でこれから進めていくというところでは何の異論もないのですが、今言ったようなスタートアップに出てもらうだけだと、多分、宣伝するだけだと、あまりなかなか広がっていかないのではないかというところの視点で今お話しさせていただいたので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"そういったファシリテーションとか場のつくり方によって、また意見というのがいろいろ出てきたり、 出にくかったりとか、長年品川でやってくださっている方と、また、新しいそういうＩＴ企業であったり、スタートアップだったりみたいなところの場づくりが上手な方みたいな方が入っていただくことによって、さらに交流が活発になっていくのかと私は思っていますので。","respondent":"大森文化観光戦略課長","answer":"それで、全体のファシリテーターを考えていくというのは確かにあるのかというところと、あと、今後、何人か講師の方を呼ぶというような形になったときに、やはり大きなイベントだけをやっている方たちを呼んでも萎縮してしまったりとかという。","voiceIndex":66,"id":"exchange-025"},{"speaker":"新妻委員","kind":"質問・要望","question":"オリンピックの競技の中で、品川区はレガシーがかなりほかの区よりも進んでいただけていると思っているのですが、例えば、ホッケーチームのフリークスとかヴェルディとか、あとはデフサッカーとかも引き続き体験をやっていたりとかされているので、そういう方たちも今後またぜひお声がけをいただきたいというところとか、また、今いろいろな世代でボッチャとかがはやって、やっていらっしゃる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-026"}]},{"id":"topic-04","title":"令和８年度文化センター他工事等による休室・休館予定","agenda":"令和８年度文化センター他工事等による休室・休館予定","exchanges":[{"speaker":"まつざわ委員","kind":"意見","question":"文化センターの改修工事で、五反田文化センターで、多分、こうやって工事の期間をずらすということは、全部を一斉に休館ではなくて、ある程度施設を機動させながらやっていこうと考えたのかと思っているのです。それなのか、本当にそこだけが壊れているのか、いろいろあると思うのですけれども、荏原文化センターにも関わってくるのですが、そういった分割工事というのですかね。そうですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-027"},{"speaker":"まつざわ委員","kind":"質問","question":"そうすると、よくこういう施設改修工事というのは、施設改修工事だから使えませんで終わってしまうイメージがあるので、例えば、こういったところというのは結構特殊なところなので、やはりそういったよく利用する団体にはいろいろともう少し気を遣って、例えば、ほかのところで使う部分の差額を返還してあげるとか、何かそういった措置があってもいいのかと思っているのが１点と、あと。","respondent":"大森文化観光戦略課長","answer":"そうです。","voiceIndex":76,"id":"exchange-028"},{"speaker":"まつざわ委員","kind":"質問","question":"そうすると、あそこは大ホールがあったり、障害のある方が駐車場をすごく利用すると思うのですけれども、そうすると、半年、利用できないというと、どうなるのか。あるのかと思っていたので、例えば、駐車場が半年ないところの、 そういった部分での気の遣い方というのはあってもいいのかと思っていますが、どうでしょうか。","respondent":"大森文化観光戦略課長","answer":"駐車場に関しましては、工事のほうとも連携しまして、裏の駐車場、搬入口の駐車場と、あと、表のお客様が各団体１台でというような、そういうところで止めていただける駐車場もございまして、駐輪場も裏手にありますので。","voiceIndex":78,"id":"exchange-029"},{"speaker":"まつざわ委員","kind":"質問","question":"そうすると、例えば小規模の改修をしている、例えば大きな金額というのはある程度積算で出るわけではないですか。同じようなものが建てることができないというのは分かっていますけれども、やはり小規模でお金をこうやってどんどん工事をしていくのだったら、どこかで大規模改修というのは、品川区の考え方として絶対に持っていかなければいけないのかと思っていますので、意見として言わせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-030"},{"speaker":"新妻委員","kind":"質問","question":"１点だけ。こんな活用の仕方ができるのですかというところなのですが、今、五反田文化センターの音楽ホールは、音がするために貸出しができないというお話がありました。中にはもしかして音がしても、この音楽ホールを使ってみたいとか、スクエア荏原でホールの貸出しをして、ピアノの体験をされているケースがあると思いますが、例えば、こういう機会にそういう活用の仕方というのはどうなのでしょうか。","respondent":"大森文化観光戦略課長","answer":"いろいろ考えていかないといけないかというところはあるのですけれども、なるべくそういった使える機会には開けていくような形は考えていきたいと思います。","voiceIndex":81,"id":"exchange-031"}]},{"id":"topic-05","title":"夏季屋外プールの開放","agenda":"夏季屋外プールの開放","exchanges":[{"speaker":"新妻委員","kind":"確認","question":"ご説明ありがとうございました。１点だけ確認します。（２）の学校プールの一般開放ですが、５校ということなのですけれども、この数というのは、これまでの経過として、もともと５校だったのか、少し数が減ってきたのか、あと、利用状況も含めて現状をお聞きしたいと思います。","respondent":"山下スポーツ推進課長","answer":"実施校ですけれども、平成２２年度のときには９校だったのですが、少し飛びまして、昨年度は６校だったのですが、具体的には、芳水小学校のほうから今年度は協力ができないというお申出がございまして、私どものほうも。","voiceIndex":87,"id":"exchange-032"},{"speaker":"新妻委員","kind":"確認","question":"もっと過去は多かったのではないかという印象がありましたので、確認をさせていただきました。学校の授業の確保というところが第一かと思うのですが、今後、これ以上減ることがないように、また教育委員会部門との連携も協力も要請をしていただきながら、維持をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-033"},{"speaker":"まつざわ委員","kind":"質問","question":"例えば、こういったものをいいきっかけにして、地域部活動の移行のポイントという形で考えれば、こういうところに例えばプロのスイマーを呼んで、地域の資源を活用したりして、水泳の勉強会というのを、ふだんできないことをやってあげるとか、何かそういったきっかけの一つにしてほしいと私も思っているので、新妻委員がおっしゃいましたけれども、教育委員会と連携して。","respondent":"山下スポーツ推進課長","answer":"ですので、今後も部活動の地域移行に関しましては展開があるかと思いますので、必要に応じて教育委員会と協議してまいりたいと思います。キャンセルに関しましては、取りあえずこちら、夏季限定でやっておりますので、キャンセル機能は特にないかと思います。","voiceIndex":90,"id":"exchange-034"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ぜひしなかカードができて、無料でできるようになったので、そういったシステムも改修できるチャンスがあるなら、そういうのもきっかけとして、予約システムというのは、ごめんなさい、不勉強でどういうのか分からないのですけれども、ぜひそういった予約、少しでも多くの方にやっていただきたいので、キャンセルのやり方というのもいずれ検討していただきたいのと、あと、このしなかカード。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-035"},{"speaker":"せらく委員","kind":"質問・要望","question":"私からは、学校プールについて、先ほどからも出ていましたが、少し聞いておきたいと思います。もし重なっている部分があったら申し訳ないですけれども、先ほど利用者数についてもしかしたら質問されていたと思うのですが、年代だとか、例えば、親子での利用が多いとか、子ども同士での利用が多い、 そういった実態をもし把握されていれば、教えていただきたいと思います。","respondent":"山下スポーツ推進課長","answer":"利用者数ですけれども、令和５年が約１,６００人、令和６年と７年が約１,３００人で推移しています。","voiceIndex":93,"id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"小学校、中学校でやっているので、もしかしたら子どもたちが多いかと思ったのですが、年代もそれなりの方がいらっしゃるということで、分かりました。現場の運営体制についてもお聞きしたいのですが、学校プールの一般開放時には、どのような職種のスタッフの方が何名程度配置されているのかというのを把握されていたら教えてください。安全管理体制というところでお聞きしたいと思います。","respondent":"山下スポーツ推進課長","answer":"１つのプールに関しまして、申し訳ございません、人数までは分からないのですけれども、そのような形で二重の体制で開放は行ってあります。","voiceIndex":95,"id":"exchange-037"},{"speaker":"せらく委員","kind":"質問","question":"分かりました。状況を教えてくださって、ありがとうあります。利用人数については、推移、少し減っているか、維持しているかという状況だと思います。まだまだ利用する方もたくさんいるのだということが分かりましたので、今回は学校が１校減ってしまったということですが、計画して、区民の皆さんの余暇の充実というところを引き続きお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-038"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.29ku.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":30,"characters":37293,"voices":106}},{"id":"r08-20260629-7","meetingId":"r08-m0708","date":"2026年6月29日","dateIso":"2026-06-29","committee":"厚生委員会","time":"午前10時00分～午後４時38分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を103件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"第６４号議案、品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第６４号議案、品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"今回は、給与所得控除が６５万円になったにもかかわらず、介護保険は５５万円で計算するので、課税とみなされてしまう人を６５万円で計算をして非課税にするということだと思うのです。教えていただきたいのが、何人くらいの方がこの対象になるのか、非課税のぎりぎりの人が対象になると思うのですけれども、介護保険段階では何段階の人が対象になるのか、その２点を教えていただきたいと思います。","respondent":"佐藤高齢者福祉課長","answer":"保険料段階ですけれども、こちらにつきましては、ご本人が課税になるのが７段階以上になりますので、みなしでそちらになることが２から４の本人非課税に戻るといいますか、減免されるというのが今回の内容になります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今回のこういったことに関して、何かホームページとかで周知は区でお考えでしょうか。","respondent":"佐藤高齢者福祉課長","answer":"今回の特例措置の周知についてですけれども、委員ご指摘のとおり、ホームページに掲載することと、 あと、７月になりましたら、今回の保険料の算定について通知を皆さんに差し上げるのですけれども、 それでこの特例措置に該当する方については。","voiceIndex":8,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"確認","question":"そういうほかのところは、基本、それぞれの事業所が東京都に直接請求をして受けることになるのか、その確認をお願いします。１か所当たり１０万円ぐらいになってしまうと思うのですが、なぜ３２８万円なのか、計算の仕方ですか、たしか２.３％ぐらいの報酬の加算の引上げになると思うのですけれども、それとはまた別なのか、そこら辺をもう少し分かるように教えていただけたらと思います。","respondent":"佐藤高齢者福祉課長","answer":"３点ご質問いただいたかと思います。１点目ですけれども、ご質問のとおりでして、品川区の地域包括支援センターが高齢者福祉課を中心として直営でやっているので、区役所が１事業者として東京都に申請する分ということで補正予算を計上させていただきました。","voiceIndex":29,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１.９５％ということで、では２.０３％は今回は関係ないのか、そこら辺と、これが実際に何人分くらいになって、賃上げにつながるものなのか、教えていただきたい。このことによってどの程度賃上げになるのか、あったら、そこら辺の賃上げの額とかも、想定されるものがあったら教えてください。","respondent":"佐藤高齢者福祉課長","answer":"これが賃上げにつながるかどうかですけれども、今回計算したところ、在宅介護支援センターは、先ほど申し上げたとおり、介護の職員と予防の職員に分かれておりますので、予防の職員で、それもそれぞれ事業所ごとに人数は違いますが。","voiceIndex":31,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"意見","question":"だから、そういうのと合わせて多分賃上げになるのだろうと思いました。賃上げという点では、７,０００円だけだととても足りなくて、実際に一般の全産業平均から比べても、厚生労働省のつい最近の発表でも８万２,０００円の差があるという発表でした。まだまだ足りないので、もっと大幅にやることが必要だと思いますけれども、これはこれでプラスではあるので、それを活かしていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-005"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今の質疑の続きで、少しお伺いしたいのですが、先ほど月７,０００円の分配になる、計算したらということですけれども、すみません、私の理解が追いついていないだけかもしれないのですが、今回の医療・介護等支援パッケージの報酬改定で、最大１万９,０００円で、恐らく基本的に１万円という額が出ていたと思うのですけれども、それに比べて月に７,０００円というのは。","respondent":"佐藤高齢者福祉課長","answer":"今後、６月以降、介護報酬の改定がされておりますので、実績を見つつ、国も次の令和９年度の介護報酬改定について、現在検討されると考えております。","voiceIndex":34,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういう方たちへも分配されると考えてよいのでしょうか。今まで品川区も個別にヘルパーへの支援は割と具体的にできてたと思うのですけれども、事業所の中にはいろいろなお仕事をしておられる方がいるので、マネジメント的なお仕事の方たちにはそういう支援があまりないとご要望をいただいているので、その方たちにも、自由度を持った使い方ができると判断してよろしいのか、伺いたいと思います。","respondent":"佐藤高齢者福祉課長","answer":"今回、国は、委員ご指摘のとおり、介護職員のみならず、介護従業者を対象にして賃上げを実現する措置を行ったと言っておりますので、それぞれの事業者で給与体系ですとかお支払いの仕方はそれぞれだと思いますけれども、趣旨としましては。","voiceIndex":38,"id":"exchange-007"},{"speaker":"若林委員","kind":"質問","question":"そもそも職場環境改善が何を意味するのかという議論になると思うのですが、そこも含めて、今の私の表現の仕方に対して、何か国が考えていることはどういうことなのでしょうか。","respondent":"佐藤高齢者福祉課長","answer":"ただ、加算がもらえる要件としましては、職場環境としてキャリアアップのための道筋をきちんと整理するですとか、実際の賃上げに一定程度配分するですとか、そういったものを要件にしていることから、今回、名前は国から来ていますのでこういった名前ですけれども。","voiceIndex":41,"id":"exchange-008"},{"speaker":"若林委員","kind":"確認","question":"例えば７,０００円という数字が、ひとり歩き、変な言い方、押し並べて１人、マネジャーは少し違うかもしれませんけれども、一般的なヘルパーも含めた職員の方に平均で７,０００円上乗せされるという、そういうざくっとした言い方はあまり適切ではない。一応そこは数字で、また言い方もありますので、そこは確認させてください。","respondent":"佐藤高齢者福祉課長","answer":"失礼いたしました。補助金を単純に割り返すというご説明でしたけれども、委員ご指摘のとおり、今回の趣旨としましては、それぞれの職員の方に一定の賃上げを促すものですので、今後も表現については注意していきたいと考えています。","voiceIndex":43,"id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問","question":"高齢者スマートフォン購入支援について伺います。その前提で、事業自体は大賛成なものだとして、ほかの施策も含めて、基準の情報が欲しいのですが、まず、ここで言う助成額の３ 万円、スマートフォン購入といっても、私たちが販売店に行っても、機種の幅がかなりある。どういう想定で、東京都も含めて、この値段になっているのか。どういうものの購入を想定してこの補助額なのか教えてください。","respondent":"樺島高齢者地域支援課長","answer":"中には一定程度、高いものもあるとは思いますが、中には３万円の上限の中で買える機種もあるとは思いますので、３万円を超えた場合には、その超過分は自己負担になります。１人につき１台３万円までを補助するという形で今回はするものになります。","voiceIndex":46,"id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問","question":"それも含めて、次の質問ですが、スマートフォンの所持率は、細かい統計はなくても、どのぐらい把握できているのか。それによってデジタルデバイド解消の展開、また力の入れ具合も変わってくると思うので、まずその辺をどう、品川区自体は他の施策も含めた中で把握されているか。それとは別で、今回、補助金申請審査事業委託で、審査事業は、どういうところを想定して、どういう内容なのかも教えてください。","respondent":"樺島高齢者地域支援課長","answer":"併せて今回、この事業を行うに当たりまして、先行的に昨年度からほかの自治体でやっている部分の申請率、そういったものを含めて、最終的に今回、区としましては、助成対象人数としては２００人ぐらいを想定しております。","voiceIndex":48,"id":"exchange-011"},{"speaker":"渡辺委員","kind":"質問","question":"すみません、今の１.８万人というのは不保持率ですか。","respondent":"樺島高齢者地域支援課長","answer":"大変失礼いたしました。今のは不保持率、持っていない方の率が、以前試算した際には １万８,０００人ぐらいいるだろうというところから、この事業を検討しております。今回の委託内容のご質問についてお答えします。予算の中で委託予算も計上させていただいております。","voiceIndex":50,"id":"exchange-012"},{"speaker":"渡辺委員","kind":"質問・要望","question":"細かいところはともかく、この案件は一番分かりやすいというか、非常に高齢者の方が悩む相談事業です。相談事業の必要なものと捉えています。というのは、まずこれから販売店等に行ったときにも、 現状で、私たちの感覚だと、予約もとりづらい、思うように予約がとれないとか、あと、行った先で機種変更だけでも数時間かかります。本当に３時間や５時間かかる。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-013"},{"speaker":"若林委員","kind":"確認","question":"今、資料を見ながら、事業予算で、助成金委託が６００万円で、先ほどちらっとありましたけれども、 委託がそれを上回る６６０万円余。助成金は２００人で決まってくるのですが、それに対してこの委託事業の６００万円余の中身をまず確認したほうがいいですね。お願いします。","respondent":"樺島高齢者地域支援課長","answer":"委託そのものにつきましては、 内容が、申請審査および事務処理を適切に効率的に実施するため、ある程度専門的な業務を委託する内容となっております。事務の正確性や迅速性を担保するために必要な経費になりますので、必要な審査を適切に行い計上しています。","voiceIndex":54,"id":"exchange-014"},{"speaker":"若林委員","kind":"確認","question":"そうするとその方はお友達がいて、持っていない方がいらっしゃるのでしょう、今度３万円でスマホが買えると喜びの報告をされたと思うのですが、３万円しか出ないという反応が一部あった。そこは確認、幾ら安いのがあるといっても、そこで買ってしまうといわゆるこの流れには乗っからない。例えばスマホよろず相談とか地域センターに改めて行って、要するに自分では申請できないわけですから。","respondent":"樺島高齢者地域支援課長","answer":"そのスマホ教室が、いわゆる教室というよりも、ふだんショップに行って、ショップの店員と１対１ の場合が多いと思いますけれども、いろいろな説明を受けることが多々あると思います。","voiceIndex":56,"id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"私も高齢者スマートフォン購入支援事業についてなのですけれども、やはりデジタルデバイド解消は本当に重要でして、今後、ＡＩなどの進展でますます必要になってくると思うのです。１万８,０００人の不保持者がいらっしゃるということですけれども、８０代とか、年齢の幅があると思うのですが、その辺り、不保持者の年齢別の把握とかはされていますでしょうか。","respondent":"樺島高齢者地域支援課長","answer":"もちろん６５歳から６９歳の方、７０歳から７９歳の方でも一定の数はいると思いますが、圧倒的に多いのは８０歳以上の方であろうと、我々の認識として持っております。","voiceIndex":60,"id":"exchange-016"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。財源の問題もあると思うのですけれども、やはりデジタルデバイド解消ということで、 今回の事業をきっかけとして、２００人が助成を受けると想定されているわけです。もう１点質問で、なぜ今まで不所持だったのか、理由の分析も必要だと思います。毎月のお金がかかってくると理解していただくのがいいと思いますが、その点、いかがお考えでしょうか。","respondent":"樺島高齢者地域支援課長","answer":"特に高齢者の方ですと、やはりいろいろな部分をきちんと説明するのが必要と思います。そこの事前の購入時の丁寧な説明は、今回の事業におきまして、各ショップ・各キャリアにしっかり求めていきたいと考えています。","voiceIndex":64,"id":"exchange-017"},{"speaker":"筒井委員","kind":"質問・要望","question":"あまり後ろ向きなことを言ってもしようがないのですけれども、ぜひ今回、きっかけとしてデジタルデバイドの解消を進めていただきたいと思います。それであと、日中一時支援事業と生活介護延長受入運営費助成について、予算書で、一般財源がマイナス１,７００万円になっているのですが、国庫支出金と都支出金の分で十分だから、一般財源は持ち出ししなくていいからマイナスにしたということでいいですか。","respondent":"芝野障害者支援課長","answer":"日中一時支援は、もともとございました国の地域生活支援事業費等補助金を活用する。合わせて１,７００万円の一般財源の削減につながってあります。","voiceIndex":66,"id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問","question":"１つ戻って、またスマホの購入支援で、いろいろご説明いただいて大分見えてきた中で、この事業を品川区でどうやって昇華させるのか、ブラッシュアップするのかというので、１つ、渋谷区が以前行った高齢者向けのデジタルデバイド解消事業が参考になると思っています。今ご紹介しました渋谷区の事例とかを踏まえて、何かお考えのことはありますでしょうか。","respondent":"樺島高齢者地域支援課長","answer":"今、委員がおっしゃったように、使い続けるための支援、サポートはすごく重要だと思っております。区におきましては、先ほど委員のご紹介もありましたとおり、スマホよろず相談、スマホ体験教室、こういった事業を数年前から実施しています。","voiceIndex":69,"id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"提案","question":"我々としても教えてあげたいけれども、本当に仕事、業務で忙しくて、あと、１人の方に教えてしまうと、いろいろな人が私も私もとなってしまって、それでてんてこ舞いになるので、お断りするしかない状況があるのです。設定を少し変えるとか、この画面を開くとかなので、正直、我々でもできることではあるので、ぜひそういったことも検討していただきたいと思うのですが、いかがでしょうか。","respondent":"樺島高齢者地域支援課長、菅野福祉部長","answer":"ただ、現在、そういった方でも既にスマホを持っていらっしゃる方への支援は、介護職員の方がふだんからやられていると我々も認識しています。ただ、そういったところへさらに支援が可能かは、今後検証しなければならないと思います。今後も費用対効果の部分とか、介護事業所の今のお話もありましたが、それ以外に、ボランティアで教えられる方が、例えばゆうゆうプラザ等で自主事業の中で教室を開いて教えていただいたりとか。","voiceIndex":71,"id":"exchange-020"},{"speaker":"やなぎさわ委員","kind":"意見","question":"渋谷区の件を事例に出したのは、同じようなスキームでやってほしいのではなくて、調査結果で導き出されたものが、端末を手にさせるよりは、使い続けられる支援と、必要性を実感してもらう体験、そういったものが大事だと出てきているので、これをどのように品川区で活かしていくかをご検討いただければです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"マイナンバーカードを持っていない人も、住民票でスマホを購入できると思うのですが、マイナンバーカードがないと買えませんとお店で言われて買えなかったと聞いたのですけれども、住民票で購入できるのかを確認させていただきたいのと、マイナンバーカードを読み取る機能ということが書かれているのですけれども、区としては別にマイナンバーカードを持っているかは問わないのか、確認させていただいて。","respondent":"樺島高齢者地域支援課長","answer":"併せて、スマートフォンを住民票で購入できるかにおいては、定かではございませんが、住所の確認で、いわゆる本人確認の１つに当たると考えております。マイナンバーカードがなければスマートフォンを購入できないものではないと認識しております。","voiceIndex":76,"id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、電子申請はきっとお店の人にやってもらうわけですよね。本人は電子申請はできないと思うので、お店にまず行って、お店の人に申請してもらうと思うのですが、そういうときにも住民票でもやってくださいということ、それからマイナンバーカードがない人にも、住民票でできますという周知もぜひしていただきたいと思いますが、いかがでしょうか。","respondent":"樺島高齢者地域支援課長","answer":"今のご質問にお答えします。補助金の申請そのものは、やはりあくまでもご本人に申請していただくものになります。","voiceIndex":78,"id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問・要望","question":"３.補正予算額のところで、１ページ目の一番下の歳入で、基本額・専門職配置加算・送迎加算で、補助率が東京都４分の３の助成なので、品川区は４分の１の負担でよくなったのか、その点についても確認させてください。それから、生活介護延長受入事業所と日中一時の延長受入れの施設数と、１施設当たりの受入れ人数をそれぞれ教えていただきたいと思います。","respondent":"芝野障害者支援課長","answer":"３つ目の生活介護と日中一時支援の受入れの状況ですが、施設によってかなりばらつきがございまして、職員体制とかその辺もしっかりと検討しなければいけない中で、現状では、一、二名の受入れや、 最大１０名程度受け入れられるというお話をいただいている事業所もあります。","voiceIndex":80,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問","question":"専門職配置加算が今回つくことになって、実際にこれがつくことを検討されているところがあるのか、つくことになっていくのか、そこも伺いたいです。日中一時は、支援区分６と５は３人掛ける６施設、支援区分４は２人掛ける５施設で事項別説明資料には書かれていたのですけれども、今、日中一時は３か所だと思うのですが、これは何で６か所と５か所となっているのか、ここの箇所数の試算理由も伺います。","respondent":"芝野障害者支援課長","answer":"生活介護と日中一時支援の数の話ですが、生活介護は、委員おっしゃるとおり、平均にしておりますので８事業所掛ける３人になっておりまして、日中一時も、一応試算的には、４までが５で、５、６が６という形になっているのですが、この事業を開始するに当たって。","voiceIndex":82,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"確認","question":"ということは、今、にじのひろば２か所とぐるっぽの３か所だと思うのですけれども、それがさらに増える可能性があると考えていいのか、その確認だけお願いします。","respondent":"芝野障害者支援課長","answer":"そうですね、お話をさせていただいている例えば就労継続支援Ｂ型の事業所とか、いろいろな事業所があるのですが、今の３か所以上に増える可能性はあります。","voiceIndex":84,"id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問","question":"日中一時をもっと増やしてほしいというのがありましたので、ぜひ増える方向で取組を進めていただけたらと思います。この増額分は全額東京都から来るのか、改めて伺います。それから、３倍に値上げした基準、額の３倍は、なぜ３倍になったのか、東京都は何と説明しているのかも伺います。","respondent":"宮澤福祉計画課長","answer":"３点質問いただきました。１つ目です。民生・児童委員の今回上がる金額につきましては、全額、都から来ます。先ほど説明させていただきました協力員につきましては、２４０万円は一般財源となっております。","voiceIndex":86,"id":"exchange-027"},{"speaker":"鈴木委員","kind":"意見","question":"民生委員の方が対応される相談も、複雑化した様々な問題を抱えている人が増えているので、本当に大変な中、丸々ボランティアという、今の３万円でもボランティアという状況だとは思うのですけれども、そういう中で、負担がなるべく少なくなるようにと、研修なども、いろいろと研修をすることによって対応もスムーズになっていくと思いますので、区としても、そういう点では。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"質問","question":"民生委員の件、続きですみません、お聞きしたいのですけれども、民生・児童委員、定数が３２５名で、実際に３０８名と書かれて、差の１７名は、要は欠員、足りていないという認識でよろしいのでしょうか。","respondent":"宮澤福祉計画課長","answer":"民生・児童委員の定数は、記載のとおり、３２５名で、この３０８という数字は、予算上の数字になっています。実際に活動されている実人数になりますと、最新ですと、６月現在で２７６名、つまり、 その差に関しては、欠員が生じてあります。","voiceIndex":89,"id":"exchange-029"},{"speaker":"やなぎさわ委員","kind":"確認","question":"実数でいうと、思った以上に足りていないと実感しました。確認ですけれども、民生委員は、基本的には無給であって、今回上がる活動費は、いわゆる実費、通信費とか交通費とか研修費とか、そういったかかった費用に対して支払われるのか、確認です。","respondent":"宮澤福祉計画課長","answer":"民生・児童委員の活動費は、実費弁償になっております。ただ、東京都の通知等もございまして、一つ一つの領収書等で出していただくのではなくて、民生委員の活動報告というのを１人ずついただいておりますので、それで代えしています。","voiceIndex":91,"id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問","question":"というと、今回活動費が３万円になるのですけれども、毎月３万円は満額支払われて、ある程度、正直、多少余る分は、民生委員の活動としてあとは自由に使うような考え方でよろしいでしょうか。","respondent":"宮澤福祉計画課長","answer":"認識としては、委員ご指摘のとおりです。それぞれの民生委員の方々、個々に活動されておりますし、また、それぞれ民生委員協議会としての活動も行っております。そういった経費に充てられているところです。","voiceIndex":93,"id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"意見","question":"それを踏まえて、例えば今、実働で２７６名というお話もあって、民生委員が足りていない原因として、例えば活動費が少ないからやれないのだという声があるのか、また別の要素があるのか、その辺の区としての受け止めはどのようにお考えでいらっしゃいますか。","respondent":"宮澤福祉計画課長","answer":"そこら辺の原因、理由につきましては、活動費だけではなくて、推薦をいただいている町会・自治会の高齢化等も原因にあると認識しています。","voiceIndex":95,"id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"提案","question":"当然、今回活動費が増えるのは非常にいいことではありつつ、やはりまだまだ人員をカバーするための課題は多いと認識しましたので、これは今後の課題として、厚生委員として私も提案を考えたいと思いますけれども、区としてもそういった認識は引き続き持って取り組んでいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-033"},{"speaker":"吉田委員","kind":"確認","question":"もちろん親の就労支援も、実際、１８歳の壁で、その後、早く帰ってきてしまうお子さんのために仕事を諦めざるを得ないということがあってはならないと思いますので、それはそれでいいと思うのですけれども、その辺の日中一時支援の品川区の認識、あくまでやはり障害児にとっても居場所なわけで、 その居場所についての事業の拡充とか、そういうお考えはどうなのか、改めて伺います。","respondent":"芝野障害者支援課長","answer":"日中一時支援の品川区の考え方ですが、委員おっしゃるとおり、２面あると思います。障害者の居場所の確保が１つ。もう１つが、親の就労の継続支援です。こちらの２つの面でこの事業を進めていきたいと考えております。","voiceIndex":99,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"一方で、障害児への、１８歳を超えると障害者になる、障害者の居場所が、ただいればいいというわけではなく、やはりせっかくそういう施策をやる以上、障害者にとって、就労までいかなくても、でも一種の就労であってほしいということなのだろうと思います。働く、社会参加ということの施策もこれから進められるべきと思うのですけれども、 その点についてお考えを伺いたいと思います。","respondent":"芝野障害者支援課長","answer":"今は、要は放課後デイとかで夕方まで預かってもらっていた方が、今度、生活介護等に移りますので、大人になりましたら、そちらは４時ぐらいまでしかサービスをやっておりませんので、そちらをカバーする形で、日中一時支援を何とか活用できないかと事業を始めておりますが。","voiceIndex":101,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"これはいろいろなところから声を聞きますし、実際にＮＰＯでできているのになぜ区ができないのかという思いがあって、本当にいろいろなお仕事、それも細分化して、これならできるというお仕事で細分化する、民間でもできるのだから行政もできるでしょうと少し思ってしまうので、ぜひそういうことも今後考えていただきたいと思います。これは本当に強く要望しておきます。それから民生委員のこと、いいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"民生委員のお仕事はすごく大変だと思います。なぜなら、うちの両親が民生委員に大変お世話になりました。高齢者だけで暮らしていると、本当に民生委員の支えがないと難しい状況がありますので、介護全体のことになるかもしれませんけれども、介護を社会化した２０年前の考え方の中に、やはり民生委員の待遇などもぜひ検討していただきたいと思うのです。もしお考えがあれば承りたいと思います。","respondent":"宮澤福祉計画課長","answer":"民生委員の方、今回は活動費が増額されますので、ご自身で負担されていたところはなくなるだろうという見込みであります。","voiceIndex":105,"id":"exchange-037"},{"speaker":"やなぎさわ委員","kind":"意見","question":"１つ戻って、生活介護延長受入運営費助成事業について、補正予算額で素朴な疑問なのですが、歳出が約２,５００万円で、一方、歳入が約４,６００万円です。歳入が２,０００万円ぐらい多いのであれば、さらに単価の引上げとかサービスの拡充ができると思ってしまうのですが、その辺はいかがでしょうか。","respondent":"芝野障害者支援課長","answer":"一方、歳入は、当初予算、区の一般財源で支出する予定でしたので、１円もありませんでしたので０ 円で、今回補正予算反映後で４,６７２万４,０００円ですので、金額的には一定程度、区が持ち出している状況になっております。","voiceIndex":108,"id":"exchange-038"},{"speaker":"鈴木委員","kind":"質問・要望","question":"麻しん対策事業について伺います。１つは、麻しんがすごく増えてきているのですけれども、５月に東京都で２３９人というのはニュースで見たのですが、品川区でどれくらいか分かったら教えていただきたいです。それから、ワクチンの接種費用は５,０００円と３,０００円の助成ですけれども、これを除いた自己負担は幾らぐらいになるのか、その点についても伺えたらと思います。","respondent":"五十嵐保健予防課長","answer":"想定人数の件ですが、どのぐらいの方が実施されるかは正直あまり分からない部分でして、何とも言えないのですけれども、一応想定を出させていただいて、抗体検査をした方の８割程度が接種するだろうと組ませていただいている額になってあります。","voiceIndex":113,"id":"exchange-039"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１９歳以上の区民ということですが、どのようなところにこのワクチン接種をより受けてほしいか、例えば医療機関だったり、教育機関だったり、接客業だったりとか、そういう人と接する機会が多いところにワクチンをより受けてほしいという、そういう区としての考え方、海外渡航予定のある人とかも含めて、特にワクチンを接種していただきたいとの考え方はあるのか、また。","respondent":"五十嵐保健予防課長","answer":"医療機関ですが、医療機関につきましても、実施していただける医療機関を広報やホームペー ジでお知らせさせていただいて、そちらに行って検査をしていただいて、その後また予防接種をしていただくことで想定しています。","voiceIndex":115,"id":"exchange-040"},{"speaker":"鈴木委員","kind":"確認","question":"ということは、広報やホームページとかで、ここの病院だったら抗体検査とワクチンを受けられるので、そこに行って、区に申請して抗体検査無料券をもらうとかではなくて、病院に行って直接やりたいということでできる仕組みでいいのか、確認だけ、お願いします。","respondent":"五十嵐保健予防課長","answer":"希望される方は、契約させていただいている医療機関に予約していただいて、それで行っていただければできる状況になってあります。","voiceIndex":117,"id":"exchange-041"},{"speaker":"若林委員","kind":"確認","question":"簡潔に確認です。生活介護、日中一時支援の確認で、表がありまして、区分ごとに現行１人当たりの助成額が出ています。これは、区の考え方と都の考え方との比較、金額が今までは区分ごとに、 区は違っていたのに、都は区分の５と６をフラットにしているのは、どういう意図なのでしょうかという質問、確認です。","respondent":"芝野障害者支援課長","answer":"今回の区分の金額の都の考え方ですが、申し訳ございません、都からの通知等には記載がされていないのですが、想定では、重度の方が区分の５と６と東京都では考えておりまして、この方についてはより手厚く金額を、同じ金額で補助していこうという考えだろうと、推測になりますが。","voiceIndex":119,"id":"exchange-042"},{"speaker":"若林委員","kind":"意見","question":"東京都の考え方ということで、つまびらかではないのですが、区分の５と６は重度なのですが、５ と６という、当然数字が違うので、より重度ということもあるので、これを事業所がどのように、確かに２倍、３倍となっているのですが、現場は区分の５と６でフラットなのかというのが出てくるという懸念はありますので、そこら辺はまた事業所の意見を聞きながら、途中で、区として。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":121,"id":"exchange-043"}]},{"id":"topic-02","title":"令和８年陳情第１７号、住宅宿泊 事業における「家主同居型」の営業制限緩和に関する陳情","agenda":"令和８年陳情第１７号、住宅宿泊 事業における「家主同居型」の営業制限緩和に関する陳情","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"民泊については年間１８０日という規定がありますけれども、商業地域・近隣商業地域は曜日に関係なく１８０日で、それ以外は土曜日の正午から月曜日の正午までが原則となっているということですけれども、この民泊に対しての苦情がどれぐらいあるのか、そのうち家主同居型の苦情はあるのか、その点を伺います。私はそちらのほうが苦情が多いと思っているのですけれども、その苦情の件数も併せて伺います。","respondent":"赤木生活衛生課長","answer":"その差引の数につきましては、先ほどの６月１５日の数とは多少差異がありますけれども、その差引の数が現在営業している住宅数であるとご認識いただければと思います。","voiceIndex":136,"id":"exchange-044"},{"speaker":"鈴木委員","kind":"質問・要望","question":"民泊に登録しても１７０件も廃業している、その理由が分かったら教えていただきたいのと、その苦情は、１７０件が旅館業法で管理人がいない施設が１７０件ということでよいのでしょうか。それで、１７０件で２１件ということであれば、先ほどの民泊の２３９件で１５件よりもこちらのほうが多い感じがするのです。","respondent":"赤木生活衛生課長","answer":"そういった中でお知らせをすることによって、先ほど委員がおっしゃっていただいたような知らない間にできていたですとか、何も言う機会が与えられなかったという声もこちらに一定数いただいておりましたので、その声に少しでもお答えできればという思いで。","voiceIndex":138,"id":"exchange-045"},{"speaker":"鈴木委員","kind":"質問・要望","question":"町会長にお知らせしていただくのは、すごくよかったと思います。２４件しかないわけですから、区としても、実際その家主同居型のオーナー の皆さんがどのような実態だとか思いでされているのか、困っていることはないのかとか、そういう課題も含めて把握をしていただいて、陳情者の要望も含めて検討してもよいと思うのですけれども、その点についてもいかがでしょうか。","respondent":"赤木生活衛生課長","answer":"そういった中で、やはり営業されている中のお困りなことであったりとか、近隣のお声であったりとか、様々なお声をこちらに寄せられていて、その状況に基づいて我々としても、現行法の中でのお話にはなりますけれども。","voiceIndex":140,"id":"exchange-046"},{"speaker":"鈴木委員","kind":"意見","question":"最後にもう１つ、品川区における住宅宿泊事業の実施運営に関するガイドラインがあります。これは平成３０年３月９日に最初にできたと思うのですけれども、それが令和６年７月２５日に最終改定になっていて、これはホームページに公開されていますけれども、その平成３０年のガイドラインからこの令和６年の最終改定で、変わった部分があるのか、お聞かせいただけたらと思います。","respondent":"赤木生活衛生課長","answer":"制定された平成３０年の段階から、基本的にはこのやり方で続けておりまして、あとは細かい部分の修正につきましては、申し訳ありません、今すぐに回答が難しいですけれども、大枠については基本的には変更していないとご理解いただければと思います。","voiceIndex":142,"id":"exchange-047"},{"speaker":"やなぎさわ委員","kind":"質問","question":"基本的な区のお考えとしてお伺いしたいのが、家主同居型と家主不在型で、苦情は今回１５件あるうちの家主同居型はゼロ件と思うのですが、やはりこの２つのタイプによって、生じる問題は違うという認識はもともとあるのか、伺います。","respondent":"赤木生活衛生課長","answer":"家主同居型と、あとは家主不在型による区の考え方の違いですが、先ほど冒頭の説明でも申し上げましたとおり、基本的には住宅宿泊事業法ないし、条例に基づいて届出をしていただく業態になりますので。","voiceIndex":144,"id":"exchange-048"},{"speaker":"やなぎさわ委員","kind":"質問","question":"少し質問を変えて、今回１５件苦情があった。これは１年間なのか、今までのトータルなのか。その辺は１年間でということで、直近の１年間だと思うのですけれども、ではもう少し広げて、３年とか５年とかの範囲で言うといかがでしょうか。","respondent":"赤木生活衛生課長","answer":"住宅宿泊事業に対する苦情の件数ですが、先ほど令和７年度につきましては１５件と申し上げましたけれども、令和６年度につきましては７件、令和５年度につきましては８件です。もう一年遡りますと、令和４年度につきましては１件です。","voiceIndex":146,"id":"exchange-049"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私も少し民泊のトラブルをこの目で見たり、相談を受けたりとかはないのですけれども、一般的によく報道されている民泊トラブルから勘案すると、品川区は非常に少ないと思うのですけれども、区としてもこれぐらいの件数は、正直それほど民泊に対して区がいろいろ何か制限をかけるほど、重大な事態、 近隣トラブルになっていないという考え方でよろしいですか。","respondent":"赤木生活衛生課長","answer":"そういった中で、いろいろ先ほども鈴木委員からのご指摘もございましたとおり、区民の方から、あとは営業者の方から様々なご意見を聞きながら、必要な規制のあり方、品川区にそぐう形のあり方については、引き続き検討をしてまいりたいと存じます。","voiceIndex":148,"id":"exchange-050"},{"speaker":"筒井委員","kind":"意見","question":"苦情について、令和７年度は、苦情は全体で１５件あったうち、家主同居型はゼロ件ですけれども、 これも過去この条例制定当初から見て、ずっと家主同居型は苦情がなかったのか、その状況を聞きたいです。","respondent":"赤木生活衛生課長","answer":"家主同居型に対する苦情があったかのお問合せかと存じますが、大変申し訳ありません、令和７年度の集計はさせていただいてはおったのですが、令和６年度以前に家主居住型に対する苦情があったかについては集計できておりません。","voiceIndex":150,"id":"exchange-051"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。この陳情者の方は、２ページ目に、ほかの特別区の各区の情報を掲載されているのですけれども、品川区では現在このような苦情が出ているとか、その運営の状況というのは入ってきていますでしょうか。","respondent":"赤木生活衛生課長","answer":"こちらの規制内容につきましても、台東区は、これまではスタッフが常駐していれば平日営業可能としておったのですけれども、それを改正案については、１０月以降に届け出た事業者につきましては、平日の営業を一律禁止するという旨の改正をすると。","voiceIndex":152,"id":"exchange-052"},{"speaker":"筒井委員","kind":"意見","question":"今おっしゃられた台東区でも逆に規制を強化する流れもあり、非常に何か今、民泊に対する懐疑、全体的な見直し、それが必要と思っています。いわゆる区としても、そういった他区の状況とか昨今の報道とか、当然区民からのいろいろなご意見を踏まえて、規制緩和することは、やはり一定の何かハードルがあるとお考えなのでしょうか。","respondent":"赤木生活衛生課長","answer":"やはり規制緩和という表現だけ、中身をしっかり見ていただければ、確かに家主居住型に限定したような形の規制緩和だと読み込んでいただければご理解いただけると思うのですが、やはりその言葉の頭だけを取ってしまうと、規制緩和ということになってしまったときに。","voiceIndex":154,"id":"exchange-053"},{"speaker":"筒井委員","kind":"質問","question":"ですので、今後情勢の変化もあるので、慎重に他区の状況等々を見ながら、研究・検討はしていくということでよろしいのでしょうか。","respondent":"赤木生活衛生課長","answer":"委員のおっしゃるとおり、基本的には先ほどの繰り返しにもなりますけれども、区民であすとかその営業者の方々の様々な声を真摯に受け止めながら、品川区に合った規制のあり方についての検討は引き続き継続していきたいと考えています。","voiceIndex":156,"id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"オリンピックだけではなくてショパンコンクールとか、 そういう世界の人たちが集まってくるようなところでは、そういう宿泊費まで大変だからどこかの家でホームステイをさせてというのがあったのですけれども、そういうのはもう今は、だから私は家主同居型はそういう民泊をイメージしてしまうので、そういうものなのか、それとも全然違う、よく観光地とかである、自分たちの自宅の一部で民宿をやっている。","respondent":"赤木生活衛生課長","answer":"今回、陳情として寄せられてあります家主同居型の住宅宿泊事業につきましては、こちらは我々の認識としましては、住宅宿泊事業法に基づく届出住宅のうち、こちら宿泊者が宿泊をしているときにつきましては常時家主。","voiceIndex":158,"id":"exchange-055"},{"speaker":"吉田委員","kind":"質問","question":"もう１つ、先ほどのご答弁の中で少し出てきたのですけれども、誤訪問は結構あるものなのでしょうか。たまたまそのときはうまく対応できましたけれども、誤訪問というのは、こういうことがあるのだとそのときすごくびっくりしたのですけれども、私たちも民泊でこのようなことがあったと苦情として区に出していませんので、何か把握されていることがあったら伺いたいのですけれども、いかがでしょう。","respondent":"赤木生活衛生課長","answer":"誤訪問につきましては、直近の令和７年度の集計ですが、住宅宿泊事業では誤訪問に関する苦情相談というのは受け付けておりませんが、旅館業に関することとして２件、定義としては不法侵入という言い方にはなっているのですけれども、住宅宿泊営業施設かと誤認をして。","voiceIndex":160,"id":"exchange-056"},{"speaker":"吉田委員","kind":"質問","question":"その誤訪問は、別に民泊だからではないということでしょうか。でも、基本的に旅館とかホテルとなったら、それなりの見た目でもないですか。たまたまかもしれませんけれども、地域の中で話しかけてこられ、ご意見を伺うときには、やはり民泊に対する苦情は結構直接伺うところです。もう少し実態を把握するようなことはできないものか、難しいのでしょうか。","respondent":"赤木生活衛生課長","answer":"そういった中で、町会長様はその地域の住民の方々のお声であるとか、そういうのはよく存じ上げている方々だと我々としては認識しておりますので、町会長の皆様方とそういった形でコミュニケーションを取りながら、その地域の中のお困り事であったり、お考えであったり。","voiceIndex":162,"id":"exchange-057"},{"speaker":"若林委員","kind":"質問","question":"もう大分議論も煮詰まっているので、この品川区のいわゆる民泊の条例ができて、できた当初から現在までは特に改正等、手は入っていないと認識した上で、当初からこの土・日、いわゆる家主同居・不在型一緒くたで住宅地の規制について、土・日のみとした理由、品川区らしい規制を考えて今の条例の形があるということなので、そもそもの出発点の土・日のみとした。","respondent":"赤木生活衛生課長","answer":"冒頭のご説明と一部重複をしてしまう部分もありますけれども、住居専用地域もしくは住居地域、 逆の言い方をしますと商業地域・近隣商業地域は、基本的には何かしらの商いをされることを目的とした地域で。","voiceIndex":164,"id":"exchange-058"},{"speaker":"若林委員","kind":"質問","question":"最初に陳情者側にとってはそういうハードルの高い、あえて品川区の考え方を反映させた条例を当然つくったということで、当時全会一致だったのかどうか私は覚えていませんけれども、当然議会の議決を経て今の形がある。そのほかの２３件には違ったコミュニティがあって、近隣の方の考え方も、当然また見る目も違う。素直にゼロだからいいとは、議員として私はならない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-059"},{"speaker":"筒井委員","kind":"意見","question":"この民泊が始まってから約１０年ほどたったと思います。家主居住型かそれ以外か、そのめり張りをつけた規制のあり方をやっていくべきだと考えていますけれども、現時点ではやはりその規制緩和というこの言葉、この打ち出し方も、やはり昨今の民泊に対する不安がある情勢の中、慎重にやらなくてはいけないと思います。現時点では直ちに規制緩和することは認められないのが理由です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":169,"id":"exchange-060"},{"speaker":"渡辺委員","kind":"意見","question":"結論を出すで、不採択です。会派の考えとして、今ご説明があったように地域別の状況、あるいはさっき理事者の説明にありましたようにまだ懸念が多々ある中で、現状を維持しながら難しい見解というのがポイントと思います。それと、あとやはりトラブルや不足事業者の排除等を重要視した仕組みを早急に、議会も含めて行政と連携して、条例をはじめ対応すべきというような思いで会派としてはおります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":170,"id":"exchange-061"},{"speaker":"若林委員","kind":"意見","question":"さっきの質疑のとおりですが、今後、実態もしっかり、また地域の声もしっかりとキャッチしながら、緩和することによって区とか地域にとってよいことであれば、それは逆に緩和してしかるべき、何でしないのだという議論になると思いますので、そこまで議論をやはり積み重ねていかないと、初めてこういう陳情が出た今の段階ではいけない段階だと、重ねて感想を述べながら。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":171,"id":"exchange-062"},{"speaker":"鈴木委員","kind":"意見","question":"本日結論を出すで、不採択でお願いしたいと思います。現状では民泊や旅館業法に対して、多くのまちの皆さんからは不安の声が多くて、そういう相談ばかりが寄せられている状況です。だからそういう点で言えば、家主居住型の近隣住民の方々の感情とかも含めて、それからそのオーナーの方々の実態とかも含めて、ぜひ区としても把握していただいてご検討もいただくということで、お願いはしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-063"},{"speaker":"吉田委員","kind":"質問・要望","question":"本日結論を出すで、不採択とさせていただきたいと思います。この方の思いは分かりますけれども、その現実を無視して、ここで一気に規制緩和を区に求める決断はできないと判断をいたしまして、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-064"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。理由は、今回の陳情の趣旨が土・日の制限の撤廃で、緩和だけを求める内容になっているからです。今後やっていくのはやはりめり張りだと思います。その上で、めり張りをつけたルールの見直しは今後議論をされていくべきと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問・要望","question":"６月上旬に委託業者も決まったとのことですけれども、どういう事業者なのか教えていただきたいのと、検討の結論は今年度いっぱいかけて出すことになるのでしょうか。それから、それをやることによって、陳情者が心配されているように、心身障害者福祉会館の建て替えまたは大規模修繕を遅らせる要因になることはないと考えていいのか、その点についても伺えたらと思います。","respondent":"石橋障害者施策推進課長、芝野障害者支援課長","answer":"受変電設備については後ほどご説明はしますが、最後に受変電設備工事をすることで遅らせる要因になるかというご質問がありましたが、先ほどの説明の中でもさせていただいたとおり、今回特定の設備の状況のみで判断するものではなくて。今残っている資料の中で２０１９年まであるのですが、そちらの資料につきまして確認したところ、受変電設備についてはおおむね良好に稼働しており、特に問題がないということでございましたが、２０１９年１０月の通知の辺りから。","voiceIndex":182,"id":"exchange-066"},{"speaker":"吉田委員","kind":"質問","question":"今の質疑で大分あれでしたけれども、何でこの受変電設備をここまで放置したのか、その判断はどういうことだったのでしょうか。私たちも受変電設備はどうなっているのですかと質問もしなかったし、気づかなかったのもあるのですけれども、でも何でここまで、幸いにしてトラブルが起きなかったのでしょうか。その辺全然詳しくないので、ご説明いただけるとありがたいのですけれども、いかがでしょうか。","respondent":"芝野障害者支援課長","answer":"２０１９年１０月の報告のときに更新の推奨という形で通知をいただきまして、更新時期が来ているのとその時点で判断をさせていただいて、それで検討した結果が今の更新という形に結びついてございます。","voiceIndex":187,"id":"exchange-067"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはりその辺の議論の経過とかをもう少し、ずっとしっかり点検はしてきたからというのはもう本当に当然であって、もう絶対に替えなくてはいけないとなって放置することはあり得ないわけですから、 点検は当然だと思うし、その結果が大丈夫と判断する範囲だったのでこのままで来たのは当たり前のことだと思うのですが。","respondent":"芝野障害者支援課長","answer":"あくまでも利用者への影響というのを第一に考えまして、今後の計画につきましてもそれを第一に考えまして検討していくという形になるかと思います。","voiceIndex":189,"id":"exchange-068"},{"speaker":"吉田委員","kind":"質問・要望","question":"利用者への影響を配慮されるというのは本当に当然のことだと思いますし、それはぜひやっていただきたい。ですので、これは要望にとどめておきますけれども、やはり受変電設備の更新というのは必要だからするということと併せて、建て替えについては継続して検討していきますということを、利用者の方たちにまず説明していただきたいと思います。それは要望として求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-069"},{"speaker":"筒井委員","kind":"意見","question":"本日結論を出すでお願いします。結論といたしましては、不採択でお願いいたします。受変電設備の更新時期について若干問題があったにせよ、今回の受変電設備の更新と、心身障害者福祉会館の建て替え計画には影響がない、関連しないということが分かりましたので、不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":196,"id":"exchange-070"},{"speaker":"渡辺委員","kind":"質問・要望","question":"不採択で。理由に関しては今と同様の説明です。受変電設備工事が前提になっての不安の内容の趣旨だと思いますので、その辺の不安が説明によって解消されること、それとあとは心身障害者福祉会館の整備は、我が会派としても迅速な整備を変わらず求めていきたいと思います。その点はもう前提としてやっていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-071"},{"speaker":"若林委員","kind":"確認","question":"本日結論を出す。いずれにしても影響し合わないことが確認をされました。適切で的確な設備更新と改築計画を進めていただければと思います。ということで、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":198,"id":"exchange-072"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択でお願いしたいと思います。今の説明で、今回の受変電設備更新工事が、建て替えや大規模修繕の遠近には関わらないとご答弁はいただきましたが、心身障害者福祉会館の整備を迅速に進めてほしいというこの陳情者の思いはよく分かりますし、ぜひそういう形で進めていただきたいと思いますので、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":199,"id":"exchange-073"},{"speaker":"吉田委員","kind":"意見","question":"本日結論を出すで、採択でお願いしたいと思います。今、それをとどめることはないというご答弁はいただきましたけれども、やはりこの陳情者の思いをちゃんと議会として受け止めて、採択にしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":200,"id":"exchange-074"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"本日結論を出す。趣旨採択でお願いします。理事者の説明によって、今回の受変電設備の工事が改修・建て替え等の延期につながらないものということは理解できました。一方で、やはり今回の要旨にあるように、整備を迅速に進めるように品川区に強く求める趣旨には賛同いたしますので、趣旨採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":201,"id":"exchange-075"}]},{"id":"topic-03","title":"令和８年度陳情第２８号、犬のふん尿被害に対する生活衛生課の実効性ある対応および相談 対応の改善を求める陳情","agenda":"令和８年度陳情第２８号、犬のふん尿被害に対する生活衛生課の実効性ある対応および相談 対応の改善を求める陳情","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"今、区が行っていることをご報告いただきましたけれども、今回、この方の被害に対して品川区としてできること、取った対応、そしてまたこの方が求めているけれども、これはこういう理由でできないということをご説明いただけたらと思います。","respondent":"赤木生活衛生課長","answer":"陳情者の申出、ご要望に対して、陳情者に対する対応で、区としてでき得る対応、できない対応の部分に関するご質問についてお答えをします。この陳情者からのご相談につきましては、一つ一つ何にお困りなのかお電話が中心になりますけれども、ご相談を受け付けてあります。","voiceIndex":211,"id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２枚目で、生活衛生課において被害件数、発生場所、発生日時、被害対象物等を適切に記録することなど書かれているのですけれども、こういうことはなかなか難しいと読んでいて思ったのですけれども、区としてはこういうのはどう考えられているのかについても伺えたらと思います。","respondent":"赤木生活衛生課長","answer":"３点目ですけれども、注意喚起に関する文書の投函は、特定の地域に絞ってもできないのかというご質問と思いますが、現状の区の対応としましては、特定された場合につきましては当然そういったところ。","voiceIndex":213,"id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問","question":"私も実際にここの場所に行ってみたのですけれども、もう電柱に、すごくこちら側からもこちら側からも犬の排せつしないでくださいというのが書かれて貼りつけられているし、家にもすごくたくさん貼り付けられているし、そしてその電柱に向かって本当にもうすぐそばにありありという感じで、見ているぞと防犯カメラが設置されているし、その下にはとがったぎざぎざしたシートがだあっと敷き詰められていて。","respondent":"赤木生活衛生課長","answer":"最近の被害状況、区としての状況の把握ですけれども、陳情者の方からご連絡等も引き続き、 メールになりますけれども、こちらにいただいておりまして、直近で申し上げますと、６月１７日と６ 月２３日に白線付近のほぼ同じ車道上の場所に２回にわたり。","voiceIndex":215,"id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本人もすごく追い詰められている感じだと現場を見て思ったので、そういう状況に対して何かやりようはないだろうかと思ったのですけれども、いろいろ精神的にも追い込まれると資料もいただいてそういうところもありますので、そこは救われる手立てが何かないのか、そういうところは区として今後も含めてどのように対応しようとしているのか伺います。","respondent":"赤木生活衛生課長","answer":"生活衛生課の相談体制の改善です。陳情者の方への対応につきましては、至らぬ点もあったとは思ってありますし、当然ながら全ての区民の方に対してしっかりと寄り添った対応を徹底することにつきましては、課一丸となってそれは引き続き取り組んでまいりたいと考えています。","voiceIndex":217,"id":"exchange-079"},{"speaker":"鈴木委員","kind":"確認","question":"令和７年ということなので、また改めてふれあい掲示板や町会の掲示板とかに出していただく、それから出していただいたときには、本人に直接このようにしましたとお知らせいただくとか、道路の清掃とかも連絡をして、実際に清掃とかをやったのかまで確認をしていただくとか、そのように区ができることをこうやっていることを、本人にも分かる形で示していただく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-080"},{"speaker":"吉田委員","kind":"確認","question":"これは９月２２日品川区議会厚生委員会の発言で、尿に関する被害というのは私の発言だと思うのですけれども、そういうことの啓発とかもあって、予防接種には絶対に行きます。そういうところでされているのか、改めて確認したいのですけれども、いかがでしょうか。","respondent":"赤木生活衛生課長","answer":"そういった家でさせるための具体的な内容についてですが、具体的に紙面として何かこう周知をしているものではないのですが、犬のしつけ方教室を年に２回ほど実施をさせていただいておりまして、こちらはドッグトレーナーの方に講師をお願いしておるのですけれども。","voiceIndex":221,"id":"exchange-081"},{"speaker":"吉田委員","kind":"質問","question":"ということは、私は予防接種のときしか思いつかないので言っているのですけれども、例えばそのような一人一人への対面の具体的な啓発の場は、今はない理解でよろしいでしょうか。","respondent":"赤木生活衛生課長","answer":"ただ、文書、チラシなど、そのしつけ方教室への参加の呼びかけ等を通じて、１人でも多くの飼い主の方にマナーとして知っていただくことは、今後も引き続き様々な機会を捉えてやっていきたいと思ってあります。","voiceIndex":223,"id":"exchange-082"},{"speaker":"吉田委員","kind":"質問・要望","question":"幸いにして私がニュースで聞いたのは、木造の電柱が倒れてしまった事例を一例聞いただけすけれども、やはりそういうこともあると踏まえて、もう少し一人一人に啓発するようなことも考えていただきたいと思うのですけれども、現在検討されていることがあったら伺いたいと思います。","respondent":"赤木生活衛生課長","answer":"トイレマットを持ち歩いていただいて、そこで拭き取っていただくことを周知をしておるのですが、こちらがなかなかまだ浸透してないと区としても認識しておりますので、例えばその辺りの周知の方法ですとか。","voiceIndex":225,"id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"確認","question":"１点だけ確認ですけれども、先ほどご答弁の中で、この陳情者の方の対応に若干不備があった的な話もあったと思ったのですが、この陳情では割と区の対応で結構じゃけんにされてひどかったみたいなことが中心に、これ以上連絡しないようにとかいろいろ結構厳しい対応を取られたと書いてあるのですけれども、この辺の事実関係はどのように捉えていらっしゃいますでしょうか。","respondent":"赤木生活衛生課長","answer":"ただ、道路の清掃の部分であったり、あとは電柱の補修の部分であったり、そういったところになりますと、生活衛生課では対応ができない部分にはなりますので、そちらについてはそれぞれの所管について適切につないでいくことが我々としての役割だとは認識しています。","voiceIndex":227,"id":"exchange-084"},{"speaker":"筒井委員","kind":"質問","question":"それでやはり一定の効果があったと思うので、引き続きこれを再度、区の掲示板、町会掲示板に注意喚起をやっていただけるのか、またある程度先ほどご答弁があったと思うのですが、時間帯の特定等ができたら、やはり職員の方にはお手数ですけれども、個別にふん尿をさせている方に直接対応していただくのがよいと思いますが、その点、今後のご対応について伺います。","respondent":"赤木生活衛生課長","answer":"２点目ですけれども、実際に個別の対応についてですが、職員が実際に時間帯を常にずっと一日中そちらに立っていることはなかなか現実的には難しいですけれども、例えば散歩が多い時間帯など、そういった中で可能な限り。","voiceIndex":229,"id":"exchange-085"},{"speaker":"筒井委員","kind":"意見","question":"ぜひ対応をお願い申し上げます。今後品川区では常設のドッグランができると思いますけれども、やはり今後そうしたものができると、トラブルも起きかねないので、より周知啓発を徹底していただけたらと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":231,"id":"exchange-086"},{"speaker":"筒井委員","kind":"質問","question":"本日結論を出します。結論といたしましては不採択でお願いします。理由としては、先ほどご答弁にあったとおり、周知啓発の強化をしていただけるということと、状況によっては個別に丁寧に対応していただけるということで、そうした理由で不採択とさせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":234,"id":"exchange-087"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今回の陳情にしても１０ページくらいありますし、それから資料を付けていただいたのも１０枚以上の資料が付いている、本当に切実な思いで出されてきているので、いろいろと対応しているのですけれども、それでもふん尿をするということであれば、何かもっと大きな、これでもかというぐらい大きな看板を出すとか、何かそのようなことも含めて寄り添った対応をぜひしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-088"},{"speaker":"吉田委員","kind":"質問・要望","question":"姿勢としては昨年９月２２日のときと変わっておらず、やはりこれはあくまで啓発の中で、飼い主さんの意識の中で解決すべき問題と思いますし、これも昨年も申しましたが、品川区ではかつては本当にあちらこちらに犬の落とし物がたくさんある時代もあった中で、啓発でここまで来たわけですから、もう一歩踏み込んでマナー向上ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":238,"id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"特に私も犬を飼ったことがないので初めて今回知りましたけれども、散歩の位置づけが今、排せつを促すことから、運動とか気分転換とか社会性を身につけることに代わってきているとお伺いして、そういったこともやはり飼い主の方の中でどこまで広がっているのだろうという疑問もありますので、その辺は本当にしっかりと、特に犬の場合は予防接種の機会があるので、しっかりとそういう機会を捉えて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":239,"id":"exchange-090"}]},{"id":"topic-04","title":"令和８年請願第３号、ヘルパーの警鐘を国に伝えてください～介護報酬大幅引き上げの意見 書を国に提出するよう求める請願","agenda":"令和８年請願第３号、ヘルパーの警鐘を国に伝えてください～介護報酬大幅引き上げの意見 書を国に提出するよう求める請願","exchanges":[{"speaker":"やなぎさわ委員","kind":"意見","question":"倒産件数も、２０２５年、過去最高を更新しておりますし、他産業との賃金格差も是正はされていないと認識しています。介護職員全体も上がってはいるのですけれども、他産業もそれ以上賃上げが行われていて、追いついていない数字、 他産業は大体５％ぐらいの賃上げに対して、介護業界は２.５％から３％ぐらいだったと認識しておりますし、依然として非常に厳しい状況にあると考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":248,"id":"exchange-091"},{"speaker":"鈴木委員","kind":"質問","question":"現場の声を伺う機会がたくさんあるのですけれども、ヘルパーステーションにしても、それから居宅介護支援事業所が特に今大変だという話を聞いていまして、ヘルパーステーションとかは賃上げの対象になってきたのですけれども、今回は居宅介護支援事業所、ケアマネジャーもやっと賃上げの対象になったのですが、午前中の審議でも月７,０００円という状況にとどめられていて、今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":250,"id":"exchange-092"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ここでも何度も申し上げているのですけれども、自民党にしても公明党にしても、２０１５年ぐらいだと思うのですが、国の負担割合を現在の２５％から３５％に引き上げることを選挙の公約に掲げていましたので、ぜひそういうところで一致して出す、意見書にそういうのを入れろということではないのですけれども、一致できていくと思いますし、先ほど申し上げたように、優先すべき財源対策では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"つまり、これは何かというと、介護報酬は３年に１回しか変わらない。それを踏まえて、６月９日に自民党の地域の介護と福祉を考える参議院議員の会、有志の会が、来年度の介護報酬改定に関する要望書を小林政調会長に提出しております。その要望書の中に、物価や人件費が毎年上がっていくことを前提とした構造的な施策を講じるべきと書いてあるのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":255,"id":"exchange-094"},{"speaker":"吉田委員","kind":"質問・要望","question":"しかもコロナのときはマスクの着用を求められつつ、暑い浴室の中で労働を続けることは、さすがに介護の仕事が好きな娘でも大変だったと言っていました。公定価格が低いがゆえに、区の中でいろいろ考えても、元のところの報酬が低くなる、ならざるを得ないことがありますので、ぜひこれは国に、この場合は介護ですけれども、介護報酬の引上げを区として求めていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":257,"id":"exchange-095"},{"speaker":"筒井委員","kind":"質問","question":"介護をやられている方の待遇改善、報酬のアップは本当に必要だと思います。課題などあると思いますけれども、つまり、介護報酬改定を毎年行うべきことや介護報酬の国庫負担を引き上げること、そういった話合いはされているのか、また、それに対する国の、できないとする課題、そうした情報は入っているのでしょうか。","respondent":"佐藤高齢者福祉課長","answer":"課長会の中での議論のお話かと思いますけれども、そういったことを踏まえて、最終的には区長会で取りまとめて国へ要望したいというところですが、直近で要望している部分については、介護分野の人材確保ですとか、そういったところ、介護報酬とは言っていなかったと思いますが。","voiceIndex":259,"id":"exchange-096"},{"speaker":"筒井委員","kind":"質問・要望","question":"やはりこうした問題は、１つの自治体というよりは、その下、課長会で話されて、特別区長会で、ある程度、束になってまとめて介護報酬の改善を求めていくべきと考えておりますので、引き続きそうした課長会や区長会で取り上げていただきたいと思いますので、ぜひよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":261,"id":"exchange-097"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すでお願いします。結論は不採択でお願い申し上げます。国でそうした改善が期待できないのならば、区で必要な支援、できることはぜひやっていただきたいということと、特別区の課長会、ひいては区長会でこの介護報酬の問題はぜひ取り上げていただきたいと思いますので、区単独で意見書を出すということについては、不採択でお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":263,"id":"exchange-098"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すです。介護報酬引上げについては、国の制度の問題で、国会の中でも私どもから要望なり、また、議論なりさせていただいていると認識しております。そういった議論は私どもやっておりませんので、そういったことを議会の意見書として出すことについては、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":265,"id":"exchange-099"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いしたいと思います。今、国が軍事費を２倍に引き上げて、今度３.５％、さらに５％も言われている中で、軍事費ではなく、やはり介護だったり、医療だったり、教育、そういうところに使うべきですし、最も深刻な状況を現場から訴えられている地方議会から意見書を上げていく、そして待ったなしに求められている切実な状況の改善につなげるべきだと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":266,"id":"exchange-100"},{"speaker":"吉田委員","kind":"意見","question":"本日結論を出すということで、採択でお願いいたします。だから、その方たちの成り手が少ないということは、社会生活をする人たちの力をそぐことにつながってしまいます。この中には、現在それを担っているのは、多くが女性である。そういう意味でも、ぜひ介護報酬の引上げはやるべきですし、それからそれはやはり国の役割であると思いますので、こういう意見書の提出はぜひ採択したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":267,"id":"exchange-101"},{"speaker":"やなぎさわ委員","kind":"意見","question":"本日結論を出すで、採択でお願いいたします。そして、来年の４月を待っている時間的余裕はないです。これだけ倒産がどんどん広がっている、 そして地域のインフラとも言える、地域資源とも言える訪問介護事業所がなくなっていくのは、代わりに１つできたからプラスマイナスゼロという状況ではない、大きな損失だと思いますので、早急にこういった意見書は品川区議会として上げるべきだと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":268,"id":"exchange-102"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"会派の意見としてそうなられたのでしょうかと思うのです。そうであれば、そういったこともぜひもっと詳しく説明をしていただきたい、委員間討議を含めてお話をいただきたかったと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":269,"id":"exchange-103"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.29ko.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":65,"characters":83437,"voices":276}}]);
